    volatile uint8_t head;
    volatile uint8_t tail;
} uart_tx_ring_buffer_t;

typedef struct {
    uint8_t buffer[UART_RX_BUF_SIZE];
    volatile uint8_t head;
    volatile uint8_t tail;
} uart_rx_ring_buffer_t;

static uart_tx_ring_buffer_t tx_ring;
static uart_rx_ring_buffer_t rx_ring;

void drv_uart_init(void) {
    tx_ring.head = 0;
    tx_ring.tail = 0;
    rx_ring.head = 0;
    rx_ring.tail = 0;

