bool drv_uart_send(const uint8_t *data, uint8_t length) {
    if (data == 0 || length == 0) {
        return false;
    }

    for (uint8_t i = 0; i < length; i++) {
        uint8_t next_head = (tx_ring.head + 1) % UART_TX_BUF_SIZE;
        if (next_head == tx_ring.tail) {
            // Buffer đầy, trả về false (non-blocking io)
            return false;
        }
        tx_ring.buffer[tx_ring.head] = data[i];
        tx_ring.head = next_head;
    }

    // ref: <missing_chunk>
    // Thiếu thông tin: Cần kích hoạt ngắt TX trống (TXE) tại đây.
    return true;
}

bool drv_uart_receive(uint8_t *data, uint8_t *length, uint8_t max_length) {
    if (data == 0 || length == 0 || max_length == 0) {
        return false;
    }

    *length = 0;
    while (rx_ring.tail != rx_ring.head && *length < max_length) {
        data[*length] = rx_ring.buffer[rx_ring.tail];
        rx_ring.tail = (rx_ring.tail + 1) % UART_RX_BUF_SIZE;
        (*length)++;
    }

    return (*length > 0);
}

