```file:src/drv_uart.c
#include "drv_uart.h"
#include <avr/io.h>

void drv_uart_init(void)
{
    // ref: ds-041, ATmega328P datasheet rev. DS40002061B, tr.180-190

    /* 
     * Cấu hình tốc độ baud: 115200
     * f_CPU = 16 MHz, chế độ U2X0 = 1 -> UBRR = 16
     */
    UBRR0H = (uint8_t)(16 >> 8);
    UBRR0L = (uint8_t)(16 & 0xFF);

    /* UCSR0A: Bật U2X0 (bit 1) = 1 để nhân đôi tốc độ, giảm sai số */
    UCSR0A = (1 << 1);

    /* UCSR0B: Bật bộ phát TXEN0 (bit 3) = 1, Bật bộ thu RXEN0 (bit 4) = 1 */
    UCSR0B = (1 << 3) | (1 << 4);

    /* 
     * UCSR0C: 
     * - Khung 8 bit dữ liệu: UCSZ01:UCSZ00 = 0b11
     * - Một bit dừng: USBS0 (bit 3) = 0
     */
    UCSR0C = (1 << UCSZ01) | (1 << UCSZ00);
}
```

