```file:src/drv_uart.c
#include "drv_uart.h"
#include <avr/io.h>

#define UART_TX_TIMEOUT 1000

void drv_uart_init(void) {
    // ref: ds-041, ATmega328P datasheet rev. DS40002061B, tr.180-190
    UBRR0H = 0;
    UBRR0L = 16;

    // ref: ds-041, ATmega328P datasheet rev. DS40002061B, tr.180-190
    // ref: ds-043, ATmega48A-PA-88A-PA-168A-PA-328-P-DS-DS40002061B.pdf, tr.200-203
    UCSR0A = (1 << U2X0) | (1 << TXC0);

    // ref: ds-041, ATmega328P datasheet rev. DS40002061B, tr.180-190
    UCSR0B = (1 << TXEN0) | (1 << RXEN0);

    // ref: ds-041, ATmega328P datasheet rev. DS40002061B, tr.180-190
    UCSR0C = (1 << UCSZ01) | (1 << UCSZ00);
}

bool drv_uart_transmit(uint8_t data) {
    uint16_t timeout = UART_TX_TIMEOUT;

    // ref: ds-043, ATmega48A-PA-88A-PA-168A-PA-328-P-DS-DS40002061B.pdf, tr.200-203
    while (!(UCSR0A & (1 << UDRE0))) {
        if (--timeout == 0) {
            return false;
        }
    }

    // ref: ds-043, ATmega48A-PA-88A-PA-168A-PA-328-P-DS-DS40002061B.pdf, tr.200-203
    UDR0 = data;
    return true;
}

bool drv_uart_receive(uint8_t *data) {
    // ref: ds-043, ATmega48A-PA-88A-PA-168A-PA-328-P-DS-DS40002061B.pdf, tr.200-203
    if (!(UCSR0A & (1 << RXC0))) {
        return false;
    }

    // ref: ds-043, ATmega48A-PA-88A-PA-168A-PA-328-P-DS-DS40002061B.pdf, tr.200-203
    uint8_t status = UCSR0A;
    uint8_t val = UDR0;

    if (status & ((1 << FE0) | (1 << DOR0) | (1 << UPE0))) {
        return false;
    }

    *data = val;
    return true;
}

bool drv_uart_is_tx_complete(void) {
    // ref: ds-043, ATmega48A-PA-88A-PA-168A-PA-328-P-DS-DS40002061B.pdf, tr.200-203
    return (UCSR0A & (1 << TXC0)) != 0;
}
```

