```file:src/drv_uart.c
void usart0_init(void) {
    // ref: ds-041, ATmega328P datasheet rev. DS40002061B, tr.180-190
    // f_CPU = 16 MHz, baud = 115200, chế độ U2X0 = 1 -> UBRR = 16
    UBRR0H = 0;
    UBRR0L = 16; 

    // Bật U2X0 (bit 1). Các cờ lỗi FE0, DOR0, UPE0 tự động được ghi 0 theo yêu cầu.
    UCSR0A = (1 << 1); 

    // Bật bộ thu RXEN0 (bit 4) và bộ phát TXEN0 (bit 3)
    UCSR0B = (1 << 4) | (1 << 3); 

    // Khung 8 bit dữ liệu (UCSZ01:UCSZ00 = 0b11), 1 bit dừng (USBS0 bit 3 = 0)
    UCSR0C = (1 << UCSZ01) | (1 << UCSZ00); 
}
```

```file:src/drv_uart.c
int8_t usart0_transmit(uint8_t data) {
    // ref: ds-043, ATmega48A-PA-88A-PA-168A-PA-328-P-DS-DS40002061B.pdf, tr.200-203
    // Kiểm tra cờ UDRE0 (bit 5). Trả về ngay để tránh blocking_io.
    if (!(UCSR0A & (1 << 5))) {
        return -1; // Bộ đệm phát chưa sẵn sàng, vòng lặp chính sẽ thử lại sau
    }

    // Chỉ ghi khi UDRE0 = 1 để tránh lỗi hỏng im lặng (bỏ qua byte)
    UDR0 = data;
    return 0;
}
```

```file:src/drv_uart.c
int16_t usart0_receive(void) {
    // ref: ds-043, ATmega48A-PA-88A-PA-168A-PA-328-P-DS-DS40002061B.pdf, tr.200-203
    // Kiểm tra cờ RXC0 (bit 7). Trả về ngay nếu không có dữ liệu (non-blocking).
    if (!(UCSR0A & (1 << 7))) {
        return -1; 
    }

    // Phải đọc cờ trạng thái TRƯỚC khi đọc UDR0
    uint8_t status = UCSR0A;
    uint8_t data = UDR0;

    // Kiểm tra FE0 (bit 4), DOR0 (bit 3), UPE0 (bit 2)
    if (status & ((1 << 4) | (1 << 3) | (1 << 2))) {
        return -2; // Lỗi khung, tràn bộ đệm, hoặc lỗi chẵn lẻ
    }

    return data;
}
