#ifndef LOGIC_PID_H
#define LOGIC_PID_H

#include <stdint.h>

/*
 * GHI CHÚ: 
 * Thiếu thông tin tài liệu thanh ghi phần cứng (không có trích đoạn nào được duyệt).
 * Tuy nhiên, module logic_pid chỉ chứa thuật toán điều khiển PID thuần túy sử dụng 
 * số nguyên (integer arithmetic), không yêu cầu truy cập thanh ghi phần cứng.
 */

typedef struct {
    int32_t kp;
    int32_t ki;
    int32_t kd;
    int32_t integral;
    int32_t prev_error;
    int32_t integral_limit;
    int32_t out_max;
    int32_t out_min;
    int32_t scale_factor;
} logic_pid_t;

void logic_pid_init(logic_pid_t *pid, int32_t kp, int32_t ki, int32_t kd, int32_t scale_factor, int32_t integral_limit, int32_t out_min, int32_t out_max);
int32_t logic_pid_compute(logic_pid_t *pid, int32_t setpoint, int32_t measured_value, int32_t dt_ms);
void logic_pid_reset(logic_pid_t *pid);

#endif /* LOGIC_PID_H */
