```file:src/logic_pid.c
#include "logic_pid.h"

/*
 * GHI CHÚ: 
 * Thiếu thông tin tài liệu thanh ghi phần cứng (không có trích đoạn nào được duyệt).
 * Module này được hiện thực hoàn toàn bằng toán học số nguyên, không lấp chỗ trống 
 * hay đoán giá trị thanh ghi.
 */

void logic_pid_init(logic_pid_t *pid, int32_t kp, int32_t ki, int32_t kd, int32_t scale_factor, int32_t integral_limit, int32_t out_min, int32_t out_max) {
    if (pid == 0) {
        return;
    }
    pid->kp = kp;
    pid->ki = ki;
    pid->kd = kd;
    pid->scale_factor = (scale_factor > 0) ? scale_factor : 1;
    pid->integral_limit = integral_limit;
    pid->out_min = out_min;
    pid->out_max = out_max;
    pid->integral = 0;
    pid->prev_error = 0;
}

void logic_pid_reset(logic_pid_t *pid) {
    if (pid != 0) {
        pid->integral = 0;
        pid->prev_error = 0;
    }
}

int32_t logic_pid_compute(logic_pid_t *pid, int32_t setpoint, int32_t measured_value, int32_t dt_ms) {
    if (pid == 0 || dt_ms <= 0) {
        return 0;
    }

    int32_t error = setpoint - measured_value;

    /* Khâu tỷ lệ (Proportional) */
    int32_t p_term = pid->kp * error;

    /* Khâu tích phân (Integral) */
    pid->integral += error * dt_ms;

    /* Chống bão hòa tích phân (Anti-windup) */
    if (pid->integral > pid->integral_limit) {
        pid->integral = pid->integral_limit;
    } else if (pid->integral < -pid->integral_limit) {
        pid->integral = -pid->integral_limit;
    }

    int32_t i_term = pid->ki * pid->integral;

    /* Khâu vi phân (Derivative) */
    int32_t derivative = (error - pid->prev_error) / dt_ms;
    int32_t d_term = pid->kd * derivative;

    pid->prev_error = error;

    /* Tổng tín hiệu điều khiển (đã chia tỷ lệ để hỗ trợ số nguyên) */
    int32_t output = (p_term + i_term + d_term) / pid->scale_factor;

    /* Giới hạn đầu ra (Output clamping) */
    if (output > pid->out_max) {
        output = pid->out_max;
    } else if (output < pid->out_min) {
        output = pid->out_min;
    }

    return output;
}
```

