#ifndef LOGIC_PID_H
#define LOGIC_PID_H

#include <stdint.h>

/* Hệ số scale cho tính toán số nguyên (Fixed-point arithmetic) */
#define LOGIC_PID_SCALE 1000

typedef struct {
    int32_t kp;
    int32_t ki;
    int32_t kd;
    int32_t out_min;
    int32_t out_max;
    int32_t integral;
    int32_t prev_error;
} logic_pid_t;

/**
 * @brief Khởi tạo bộ điều khiển PID
 * 
 * @param pid Con trỏ tới cấu trúc PID
 * @param kp Hệ số Kp (đã nhân với LOGIC_PID_SCALE)
 * @param ki Hệ số Ki (đã nhân với LOGIC_PID_SCALE)
 * @param kd Hệ số Kd (đã nhân với LOGIC_PID_SCALE)
 * @param out_min Giới hạn dưới của ngõ ra
 * @param out_max Giới hạn trên của ngõ ra
 */
void logic_pid_init(logic_pid_t *pid, int32_t kp, int32_t ki, int32_t kd, int32_t out_min, int32_t out_max);

/**
 * @brief Đặt lại trạng thái của bộ điều khiển PID (xóa tích phân và sai số trước đó)
 * 
 * @param pid Con trỏ tới cấu trúc PID
 */
void logic_pid_reset(logic_pid_t *pid);

/**
 * @brief Cập nhật tính toán PID
 * 
 * @param pid Con trỏ tới cấu trúc PID
 * @param setpoint Giá trị mong muốn
 * @param measured Giá trị đo được thực tế
 * @param dt_ms Thời gian lấy mẫu (ms)
 * @return int32_t Giá trị ngõ ra đã được tính toán và giới hạn
 */
int32_t logic_pid_update(logic_pid_t *pid, int32_t setpoint, int32_t measured, int32_t dt_ms);

#endif /* LOGIC_PID_H */
```

```file:src/logic_pid.c
#include "logic_pid.h"

/* Ghi chú: Module logic_pid là module thuật toán thuần túy, không giao tiếp trực tiếp 
   với phần cứng. Do đó không yêu cầu tài liệu thanh ghi và không có hàm cấu hình thanh ghi. */

void logic_pid_init(logic_pid_t *pid, int32_t kp, int32_t ki, int32_t kd, int32_t out_min, int32_t out_max) {
    if (!pid) {
        return;
    }
    pid->kp = kp;
    pid->ki = ki;
    pid->kd = kd;
    pid->out_min = out_min;
    pid->out_max = out_max;
    logic_pid_reset(pid);
}

void logic_pid_reset(logic_pid_t *pid) {
    if (!pid) {
        return;
    }
    pid->integral = 0;
    pid->prev_error = 0;
}

int32_t logic_pid_update(logic_pid_t *pid, int32_t setpoint, int32_t measured, int32_t dt_ms) {
    if (!pid || dt_ms <= 0) {
        return 0;
    }

    int32_t error = setpoint - measured;

    /* Khâu tỷ lệ (Proportional) */
    int32_t p_term = pid->kp * error;

    /* Khâu tích phân (Integral) 
       Sử dụng int64_t cho phép nhân trung gian để tránh tràn số trước khi chia */
    int64_t i_inc = (int64_t)pid->ki * error * dt_ms / 1000;
    pid->integral += (int32_t)i_inc;

    /* Chống bão hòa tích phân (Anti-windup) */
    int32_t max_i = pid->out_max * LOGIC_PID_SCALE;
    int32_t min_i = pid->out_min * LOGIC_PID_SCALE;
    if (pid->integral > max_i) {
        pid->integral = max_i;
    } else if (pid->integral < min_i) {
        pid->integral = min_i;
    }

    /* Khâu vi phân (Derivative) */
    int64_t derivative = (int64_t)(error - pid->prev_error) * 1000 / dt_ms;
    int32_t d_term = (int32_t)(pid->kd * derivative);

    pid->prev_error = error;

    /* Tổng ngõ ra */
    int32_t output = (p_term + pid->integral + d_term) / LOGIC_PID_SCALE;

    /* Giới hạn ngõ ra (Clamping) */
    if (output > pid->out_max) {
        output = pid->out_max;
    } else if (output < pid->out_min) {
        output = pid->out_min;
    }

    return output;
}
