```file:tests/test_logic_pid.c
#include <assert.h>
#include "../src/logic_pid.h"

/* Bộ kiểm thử đơn vị cơ bản để đảm bảo logic PID hoạt động đúng và vượt qua cổng kiểm chứng */
int main(void) {
    logic_pid_t pid;

    /* Kiểm tra khởi tạo và khâu tỷ lệ (P) */
    logic_pid_init(&pid, 1000, 0, 0, -100, 100); /* Kp = 1.0 */
    int32_t out = logic_pid_update(&pid, 10, 0, 10);
    assert(out == 10);

    /* Kiểm tra giới hạn ngõ ra (Clamping) */
    out = logic_pid_update(&pid, 200, 0, 10);
    assert(out == 100); /* Bị giới hạn ở out_max = 100 */

    out = logic_pid_update(&pid, -200, 0, 10);
    assert(out == -100); /* Bị giới hạn ở out_min = -100 */

    /* Kiểm tra khâu vi phân (D) */
    logic_pid_init(&pid, 0, 0, 1000, -1000, 1000); /* Kd = 1.0 */
    out = logic_pid_update(&pid, 10, 0, 10); 
    /* Sai số = 10, thời gian = 10ms -> đạo hàm = 1000. Ngõ ra = 1000 */
    assert(out == 1000);

    /* Kiểm tra khâu tích phân (I) */
    logic_pid_init(&pid, 0, 1000, 0, -100, 100); /* Ki = 1.0 */
    out = logic_pid_update(&pid, 10, 0, 10);
    /* Tích phân sau 10ms với sai số 10 = 10 * 10 / 1000 = 0.1 -> scale = 100. Ngõ ra = 0 */
    assert(out == 0);

    out = logic_pid_update(&pid, 10, 0, 1000);
    /* Tích phân thêm 1s với sai số 10 = 10. Ngõ ra = 10 */
    assert(out == 10);

    return 0;
}
