```file:src/logic_pid.c
#include "logic_pid.h"

void pid_init(pid_context_t *ctx, int32_t kp, int32_t ki, int32_t kd, int32_t scale_factor, int32_t out_min, int32_t out_max, int32_t i_min, int32_t i_max) {
    if (!ctx) return;
    ctx->kp = kp;
    ctx->ki = ki;
    ctx->kd = kd;
    ctx->scale_factor = (scale_factor > 0) ? scale_factor : 1;
    ctx->out_min = out_min;
    ctx->out_max = out_max;
    ctx->integral_min = i_min;
    ctx->integral_max = i_max;
    ctx->integral = 0;
    ctx->prev_error = 0;
}

int32_t pid_compute(pid_context_t *ctx, int32_t setpoint, int32_t measured) {
    if (!ctx) return 0;

    int32_t error = setpoint - measured;

    ctx->integral += error;
    if (ctx->integral > ctx->integral_max) {
        ctx->integral = ctx->integral_max;
    } else if (ctx->integral < ctx->integral_min) {
        ctx->integral = ctx->integral_min;
    }

    int64_t p_term = (int64_t)ctx->kp * error;
    int64_t i_term = (int64_t)ctx->ki * ctx->integral;
    int64_t d_term = (int64_t)ctx->kd * (error - ctx->prev_error);

    ctx->prev_error = error;

    int64_t total = p_term + i_term + d_term;
    int32_t output = (int32_t)(total / ctx->scale_factor);

    if (output > ctx->out_max) {
        output = ctx->out_max;
    } else if (output < ctx->out_min) {
        output = ctx->out_min;
    }

    return output;
}

void pid_reset(pid_context_t *ctx) {
    if (!ctx) return;
    ctx->integral = 0;
    ctx->prev_error = 0;
}
