```file:src/logic_pid.c
#include "logic_pid.h"

void pid_set_tunings(pid_state_t *pid, int32_t kp_q8, int32_t ki_q8, int32_t kd_q8, int32_t out_min, int32_t out_max, int32_t integral_limit) {
    if (!pid) return;
    pid->kp = kp_q8;
    pid->ki = ki_q8;
    pid->kd = kd_q8;
    pid->out_min = out_min;
    pid->out_max = out_max;
    pid->integral_limit = integral_limit;
    pid->integral = 0;
    pid->first_run = true;
    pid->last_measurement = 0;
}

int32_t pid_compute(pid_state_t *pid, int32_t setpoint, int32_t measurement) {
    if (!pid) return 0;

    int32_t error = setpoint - measurement;

    // Proportional term
    int32_t p_term = (int32_t)(((int64_t)pid->kp * error) / PID_Q_SCALE);

    // Derivative term on measurement
    int32_t d_term = 0;
    if (!pid->first_run) {
        int32_t d_meas = measurement - pid->last_measurement;
        d_term = (int32_t)(-((int64_t)pid->kd * d_meas) / PID_Q_SCALE);
    } else {
        pid->first_run = false;
    }
    pid->last_measurement = measurement;

    // Integral term
    int32_t i_term_add = (int32_t)(((int64_t)pid->ki * error) / PID_Q_SCALE);

    // Anti-windup
    int32_t tentative_out = p_term + pid->integral + i_term_add + d_term;

    if (tentative_out > pid->out_max && error > 0) {
        // Saturated high, and error is trying to increase it further -> stop integrating
    } else if (tentative_out < pid->out_min && error < 0) {
        // Saturated low, and error is trying to decrease it further -> stop integrating
    } else {
        pid->integral += i_term_add;
    }

    // Apply integral limit
    if (pid->integral > pid->integral_limit) {
        pid->integral = pid->integral_limit;
    } else if (pid->integral < -pid->integral_limit) {
        pid->integral = -pid->integral_limit;
    }

    // Final output calculation
    int32_t output = p_term + pid->integral + d_term;

    if (output > pid->out_max) {
        output = pid->out_max;
    } else if (output < pid->out_min) {
        output = pid->out_min;
    }

    return output;
}
