```file:src/logic_pid.h
#ifndef LOGIC_PID_H
#define LOGIC_PID_H

#include <stdint.h>
#include <stdbool.h>

/*
 * PID Fixed-Point Implementation
 * 
 * Hệ số tham chiếu từ sim/controller.py:
 * kp = 38.0, ki = 90.0 (mỗi giây), kd = 3.4 (giây), góc bằng radian.
 * 
 * Cách quy đổi sang số nguyên Q8 (PID_Q8_SCALE = 256) với dt cố định 10ms (0.01s):
 * - kp_q8 = (int32_t)(kp * 256) = 38.0 * 256 = 9728
 * - ki_q8 = (int32_t)(ki * dt * 256) = 90.0 * 0.01 * 256 = 230
 * - kd_q8 = (int32_t)((kd / dt) * 256) = (3.4 / 0.01) * 256 = 87040
 * 
 * Đơn vị:
 * - Điểm đặt (setpoint) và Số đo (measurement): milliradian (mrad).
 * - Giá trị trả về (output): Vận tốc động cơ (số nguyên).
 */

#define PID_Q8_SHIFT 8
#define PID_Q8_SCALE (1 << PID_Q8_SHIFT)

typedef struct {
    int32_t kp;
    int32_t ki;
    int32_t kd;

    int32_t integral;
    int32_t prev_measurement;
    bool first_call;

    int32_t out_min;
    int32_t out_max;
} pid_context_t;

void pid_init(pid_context_t *ctx, int32_t out_min, int32_t out_max);
void pid_set_tunings(pid_context_t *ctx, int32_t kp, int32_t ki, int32_t kd);
int32_t pid_compute(pid_context_t *ctx, int32_t setpoint, int32_t measurement);

#endif // LOGIC_PID_H
```

```file:src/logic_pid.c
#include "logic_pid.h"

void pid_init(pid_context_t *ctx, int32_t out_min, int32_t out_max) {
    if (!ctx) return;
    ctx->kp = 0;
    ctx->ki = 0;
    ctx->kd = 0;
    ctx->integral = 0;
    ctx->prev_measurement = 0;
    ctx->first_call = true;
    ctx->out_min = out_min;
    ctx->out_max = out_max;
}

void pid_set_tunings(pid_context_t *ctx, int32_t kp, int32_t ki, int32_t kd) {
    if (!ctx) return;
    ctx->kp = kp;
    ctx->ki = ki;
    ctx->kd = kd;
    // Tuyệt đối không reset integral, prev_measurement hay first_call ở đây
    // để tránh gây giật robot khi đổi tham số on-the-fly.
}

int32_t pid_compute(pid_context_t *ctx, int32_t setpoint, int32_t measurement) {
    if (!ctx) return 0;

    int32_t error = setpoint - measurement;

    // Khâu Proportional
    int32_t p_term = ctx->kp * error;

    // Khâu Derivative (tính trên số đo để tránh derivative kick)
    int32_t d_term = 0;
    if (ctx->first_call) {
        ctx->first_call = false;
    } else {
        d_term = -ctx->kd * (measurement - ctx->prev_measurement);
    }
    ctx->prev_measurement = measurement;

    // Khâu Integral
    int32_t i_term = ctx->ki * error;

    // Anti-windup: Kiểm tra bão hòa trước khi cộng dồn tích phân
    int32_t current_out = (p_term + ctx->integral + d_term) / PID_Q8_SCALE;

    if (current_out >= ctx->out_max) {
        // Đã bão hòa trần, chỉ cho phép cộng dồn nếu nó kéo đầu ra xuống
        if (i_term < 0) {
            ctx->integral += i_term;
        }
    } else if (current_out <= ctx->out_min) {
        // Đã bão hòa đáy, chỉ cho phép cộng dồn nếu nó kéo đầu ra lên
        if (i_term > 0) {
            ctx->integral += i_term;
        }
    } else {
        // Chưa bão hòa, cộng dồn bình thường
        ctx->integral += i_term;
    }

    // Tính toán đầu ra cuối cùng và kẹp giá trị
    int32_t final_out = (p_term + ctx->integral + d_term) / PID_Q8_SCALE;
    if (final_out > ctx->out_max) {
        final_out = ctx->out_max;
    } else if (final_out < ctx->out_min) {
        final_out = ctx->out_min;
    }

    return final_out;
}
