```file:src/logic_pid.h
#ifndef LOGIC_PID_H
#define LOGIC_PID_H

#include <stdint.h>
#include <stdbool.h>

/*
 * PID Fixed-Point Implementation (Q8 format)
 * 
 * Conversion from SI to Q8:
 * - Scale factor: 256 (Q8)
 * - dt = 10 ms = 0.01 s
 * 
 * SI Coefficients from sim/controller.py:
 * - kp_si = 38.0
 * - ki_si = 90.0 (per second)
 * - kd_si = 3.4 (seconds)
 * 
 * Q8 Coefficients (incorporating dt):
 * - kp_q8 = kp_si * 256
 * - ki_q8 = (ki_si * dt) * 256
 * - kd_q8 = (kd_si / dt) * 256
 * 
 * Units:
 * - Setpoint & Measurement: milli-radians (mrad) or any consistent integer unit.
 * - Output: Motor command (e.g., velocity or PWM duty cycle), bounded by output_limit.
 */

#define PID_Q8_SCALE 256

typedef struct {
    int32_t kp;
    int32_t ki;
    int32_t kd;

    int32_t integral;
    int32_t prev_measurement;
    bool first_run;

    int32_t output_limit;
} pid_context_t;

void pid_init(pid_context_t *ctx, int32_t output_limit);
void pid_set_tunings(pid_context_t *ctx, int32_t kp, int32_t ki, int32_t kd);
int32_t pid_compute(pid_context_t *ctx, int32_t setpoint, int32_t measurement);

#endif // LOGIC_PID_H
