```file:src/logic_pid.c
#include "logic_pid.h"

void pid_init(pid_context_t *ctx, int32_t output_limit) {
    if (!ctx) return;
    ctx->kp = 0;
    ctx->ki = 0;
    ctx->kd = 0;
    ctx->integral = 0;
    ctx->prev_measurement = 0;
    ctx->first_run = true;
    ctx->output_limit = output_limit;
}

void pid_set_tunings(pid_context_t *ctx, int32_t kp, int32_t ki, int32_t kd) {
    if (!ctx) return;
    ctx->kp = kp;
    ctx->ki = ki;
    ctx->kd = kd;
}

int32_t pid_compute(pid_context_t *ctx, int32_t setpoint, int32_t measurement) {
    if (!ctx) return 0;

    int32_t error = setpoint - measurement;

    int32_t p_term = ctx->kp * error;

    if (ctx->first_run) {
        ctx->first_run = false;
        ctx->prev_measurement = measurement;
    }

    int32_t d_meas = measurement - ctx->prev_measurement;
    int32_t d_term = -ctx->kd * d_meas;
    ctx->prev_measurement = measurement;

    int32_t i_term = ctx->integral + ctx->ki * error;

    int32_t total_unscaled = p_term + i_term + d_term;
    int32_t output = total_unscaled / PID_Q8_SCALE;

    bool saturated = false;
    if (output > ctx->output_limit) {
        output = ctx->output_limit;
        saturated = true;
    } else if (output < -ctx->output_limit) {
        output = -ctx->output_limit;
        saturated = true;
    }

    if (!saturated || (output == ctx->output_limit && error < 0) || (output == -ctx->output_limit && error > 0)) {
        ctx->integral = i_term;
    }

    return output;
}
