```file:src/logic_pid.h
#ifndef LOGIC_PID_H
#define LOGIC_PID_H

#include <stdint.h>
#include <stdbool.h>

/*
 * PID Fixed-Point Q8 Implementation
 * 
 * Conversion from SI to Q8 (dt = 10ms = 0.01s):
 * - kp_q8 = (int32_t)(kp_si * 256)
 * - ki_q8 = (int32_t)(ki_si * 0.01 * 256)
 * - kd_q8 = (int32_t)(kd_si / 0.01 * 256)
 * 
 * Example for sim/controller.py (kp = 38.0, ki = 90.0, kd = 3.4):
 * - kp_q8 = 38.0 * 256 = 9728
 * - ki_q8 = 90.0 * 0.01 * 256 = 230
 * - kd_q8 = 3.4 / 0.01 * 256 = 87040
 * 
 * Units:
 * - setpoint: milliradian (mrad)
 * - measurement: milliradian (mrad)
 * - return value: motor velocity command
 */

#define PID_Q8_SHIFT 8

typedef struct {
    int32_t kp;
    int32_t ki;
    int32_t kd;

    int64_t integral;
    int32_t prev_measurement;
    bool first_run;

    int32_t out_min;
    int32_t out_max;
} pid_context_t;

void pid_init(pid_context_t *ctx, int32_t out_min, int32_t out_max);
void pid_set_tunings(pid_context_t *ctx, int32_t kp, int32_t ki, int32_t kd);
int32_t pid_compute(pid_context_t *ctx, int32_t setpoint, int32_t measurement);

#endif // LOGIC_PID_H
```

```file:src/logic_pid.c
#include "logic_pid.h"

void pid_init(pid_context_t *ctx, int32_t out_min, int32_t out_max) {
    if (!ctx) return;
    ctx->kp = 0;
    ctx->ki = 0;
    ctx->kd = 0;
    ctx->integral = 0;
    ctx->prev_measurement = 0;
    ctx->first_run = true;
    ctx->out_min = out_min;
    ctx->out_max = out_max;
}

void pid_set_tunings(pid_context_t *ctx, int32_t kp, int32_t ki, int32_t kd) {
    if (!ctx) return;
    ctx->kp = kp;
    ctx->ki = ki;
    ctx->kd = kd;
}

int32_t pid_compute(pid_context_t *ctx, int32_t setpoint, int32_t measurement) {
    if (!ctx) return 0;

    int32_t error = setpoint - measurement;

    int64_t p_term = (int64_t)ctx->kp * error;

    int64_t d_term = 0;
    if (!ctx->first_run) {
        // Đạo hàm lấy theo số đo, không lấy theo sai số để tránh derivative kick
        d_term = -(int64_t)ctx->kd * (measurement - ctx->prev_measurement);
    } else {
        ctx->first_run = false;
    }
    ctx->prev_measurement = measurement;

    // Tính đầu ra dự kiến để kiểm tra bão hòa (Integral windup prevention)
    int64_t tentative_out = (p_term + d_term + ctx->integral) >> PID_Q8_SHIFT;

    bool saturated = false;
    if (tentative_out >= ctx->out_max && error > 0) {
        saturated = true;
    } else if (tentative_out <= ctx->out_min && error < 0) {
        saturated = true;
    }

    // Chỉ cộng dồn tích phân nếu đầu ra chưa bão hòa cùng chiều với sai số
    if (!saturated) {
        ctx->integral += (int64_t)ctx->ki * error;
    }

    // Tính lại đầu ra chính thức sau khi cập nhật tích phân
    int64_t final_out = (p_term + d_term + ctx->integral) >> PID_Q8_SHIFT;

    // Cắt xén đầu ra (Clamp)
    if (final_out > ctx->out_max) {
        final_out = ctx->out_max;
    } else if (final_out < ctx->out_min) {
        final_out = ctx->out_min;
    }

    return (int32_t)final_out;
}
