```file:src/logic_pid.h
#ifndef LOGIC_PID_H
#define LOGIC_PID_H

#include <stdint.h>
#include <stdbool.h>

/*
 * PID Controller for balancing robot.
 * Fixed-point arithmetic using Q8 format (scale = 256).
 *
 * UNITS:
 * - Setpoint and Measurement: milliradians (mrad).
 * - Return value, out_min, out_max: 1000x SI command.
 *   (e.g., if SI output is 0.38, this module outputs 380).
 *
 * CONVERSION FROM SI TO Q8 INTEGERS:
 * The control loop dt is fixed at 10 ms (0.01 s).
 * - kp_Q8 = kp_SI * 256
 * - ki_Q8 = ki_SI * dt * 256
 * - kd_Q8 = (kd_SI / dt) * 256
 *
 * Example for sim/controller.py SI parameters:
 * kp = 38.0  -> kp_Q8 = 38.0 * 256 = 9728
 * ki = 90.0  -> ki_Q8 = 90.0 * 0.01 * 256 = 230
 * kd = 3.4   -> kd_Q8 = (3.4 / 0.01) * 256 = 87040
 *
 * INTEGRAL LIMIT:
 * The reference integral_limit is 1.5 SI.
 * In our scaled output units (1000x), this is 1500.
 */

#define PID_Q8_SCALE 256
#define PID_INTEGRAL_LIMIT 1500

typedef struct {
    int32_t kp;
    int32_t ki;
    int32_t kd;
    int32_t out_min;
    int32_t out_max;

    int32_t integral;
    int32_t prev_meas;
    bool first_run;
} pid_ctx_t;

void pid_init(pid_ctx_t *ctx, int32_t kp, int32_t ki, int32_t kd, int32_t out_min, int32_t out_max);
void pid_set_tunings(pid_ctx_t *ctx, int32_t kp, int32_t ki, int32_t kd);
int32_t pid_compute(pid_ctx_t *ctx, int32_t setpoint, int32_t measurement);

#endif // LOGIC_PID_H
```

```file:src/logic_pid.c
#include "logic_pid.h"

void pid_init(pid_ctx_t *ctx, int32_t kp, int32_t ki, int32_t kd, int32_t out_min, int32_t out_max) {
    ctx->kp = kp;
    ctx->ki = ki;
    ctx->kd = kd;
    ctx->out_min = out_min;
    ctx->out_max = out_max;
    ctx->integral = 0;
    ctx->prev_meas = 0;
    ctx->first_run = true;
}

void pid_set_tunings(pid_ctx_t *ctx, int32_t kp, int32_t ki, int32_t kd) {
    ctx->kp = kp;
    ctx->ki = ki;
    ctx->kd = kd;
}

int32_t pid_compute(pid_ctx_t *ctx, int32_t setpoint, int32_t measurement) {
    int32_t error = setpoint - measurement;

    // Proportional term
    int32_t p_term = (ctx->kp * error) / PID_Q8_SCALE;

    // Derivative term (based on measurement to avoid derivative kick)
    int32_t d_term = 0;
    if (!ctx->first_run) {
        int32_t d_meas = measurement - ctx->prev_meas;
        d_term = -(ctx->kd * d_meas) / PID_Q8_SCALE;
    } else {
        ctx->first_run = false;
    }
    ctx->prev_meas = measurement;

    // Integral term
    int32_t i_term = (ctx->ki * error) / PID_Q8_SCALE;
    int32_t proposed_integral = ctx->integral + i_term;

    // Absolute integral limit (b)
    if (proposed_integral > PID_INTEGRAL_LIMIT) {
        proposed_integral = PID_INTEGRAL_LIMIT;
    } else if (proposed_integral < -PID_INTEGRAL_LIMIT) {
        proposed_integral = -PID_INTEGRAL_LIMIT;
    }

    int32_t proposed_out = p_term + proposed_integral + d_term;

    // Anti-windup (a): stop accumulating if output is saturated in the same direction as error
    bool saturate_high = (proposed_out >= ctx->out_max) && (error > 0);
    bool saturate_low = (proposed_out <= ctx->out_min) && (error < 0);

    if (!saturate_high && !saturate_low) {
        ctx->integral = proposed_integral;
    }

    // Clamp final output
    int32_t out = proposed_out;
    if (out > ctx->out_max) {
        out = ctx->out_max;
    } else if (out < ctx->out_min) {
        out = ctx->out_min;
    }

    return out;
}
