```file:src/drv_button.c
#include "drv_button.h"
#include <avr/io.h>

#ifndef DDB4
#define DDB4 4
#endif
#ifndef PORTB4
#define PORTB4 4
#endif
#ifndef PINB4
#define PINB4 4
#endif

static uint32_t last_debounce_time = 0;
static bool last_raw_state = false;
static bool validated_state = false;

void button_init(void) {
    // ref: ds-atme-gpio-01, ATmega48A-PA-88A-PA-168A-PA-328-P-DS-DS40002061B.pdf, tr.85-100
    DDRB &= ~(1 << DDB4);
    PORTB |= (1 << PORTB4);
}

bool button_get_event(uint32_t current_time_ms) {
    // ref: ds-atme-gpio-01, ATmega48A-PA-88A-PA-168A-PA-328-P-DS-DS40002061B.pdf, tr.85-100
    bool raw_state = ((PINB & (1 << PINB4)) == 0);

    bool event_triggered = false;

    if (raw_state != last_raw_state) {
        last_debounce_time = current_time_ms;
    }

    if ((current_time_ms - last_debounce_time) >= 20) {
        if (raw_state != validated_state) {
            validated_state = raw_state;
            if (validated_state == true) {
                event_triggered = true;
            }
        }
    }

    last_raw_state = raw_state;
    return event_triggered;
}
