#include "drv_button.h"
#include <avr/io.h>

static uint8_t debounce_counter = 0;
static bool button_state = false;

void button_init(void) {
    // ref: ds-atme-gpio-01, ATmega48A-PA-88A-PA-168A-PA-328-P-DS-DS40002061B.pdf, tr.85-100
    DDRB &= ~(1 << DDB4);
    PORTB |= (1 << PORTB4);
}

bool button_get_event(void) {
    bool is_pressed = (PINB & (1 << PINB4)) == 0;

    if (is_pressed != button_state) {
        debounce_counter++;
        if (debounce_counter >= 2) {
            button_state = is_pressed;
            debounce_counter = 0;
            if (button_state) {
                return true;
            }
        }
    } else {
        debounce_counter = 0;
    }

    return false;
}
