```file:src/drv_i2c.c
#include "drv_i2c.h"
#include <avr/io.h>
#include <avr/interrupt.h>
#include <stddef.h>

#ifndef TWIE
#define TWIE 0
#endif

static volatile i2c_status_t current_status = I2C_STATUS_IDLE;
static uint8_t target_addr;
static uint8_t *rx_buffer;
static const uint8_t *tx_buffer;
static uint8_t transfer_length;
static volatile uint8_t transfer_index;

void i2c_init(void) {
    // ref: ds-021, ATmega328P datasheet rev. DS40002061B, tr.222-224
    TWSR = 0x00; // TWPS1:TWPS0 = 0b00
    TWBR = 12;   // f_SCL = 400kHz with f_CPU = 16MHz
    TWCR = (1 << TWEN);
    current_status = I2C_STATUS_IDLE;
}

bool i2c_write_async(uint8_t addr, const uint8_t *data, uint8_t len) {
    cli();
    if (current_status == I2C_STATUS_BUSY) {
        sei();
        return false;
    }
    current_status = I2C_STATUS_BUSY;
    sei();

    target_addr = (addr << 1); // SLA+W
    tx_buffer = data;
    transfer_length = len;
    transfer_index = 0;

    // ref: ds-021, ATmega328P datasheet rev. DS40002061B, tr.222-224
    TWCR = (1 << TWINT) | (1 << TWSTA) | (1 << TWEN) | (1 << TWIE);
    return true;
}

bool i2c_read_async(uint8_t addr, uint8_t *data, uint8_t len) {
    if (len == 0) {
        return false;
    }

    cli();
    if (current_status == I2C_STATUS_BUSY) {
        sei();
        return false;
    }
    current_status = I2C_STATUS_BUSY;
    sei();

    target_addr = (addr << 1) | 1; // SLA+R
    rx_buffer = data;
    transfer_length = len;
    transfer_index = 0;

    // ref: ds-021, ATmega328P datasheet rev. DS40002061B, tr.222-224
    TWCR = (1 << TWINT) | (1 << TWSTA) | (1 << TWEN) | (1 << TWIE);
    return true;
}

i2c_status_t i2c_get_status(void) {
    cli();
    i2c_status_t status = current_status;
    sei();
    return status;
}

ISR(TWI_vect) {
    // ref: ds-022, ATmega328P datasheet rev. DS40002061B, tr.228-232
    uint8_t status = TWSR & 0xF8;

    switch (status) {
        case 0x08: // START transmitted
        case 0x10: // Repeated START transmitted
            TWDR = target_addr;
            TWCR = (1 << TWINT) | (1 << TWEN) | (1 << TWIE);
            break;

        case 0x18: // SLA+W transmitted, ACK received
        case 0x28: // Data transmitted, ACK received
            if (transfer_index < transfer_length) {
                TWDR = tx_buffer[transfer_index++];
                TWCR = (1 << TWINT) | (1 << TWEN) | (1 << TWIE);
            } else {
                // Done, send STOP
                TWCR = (1 << TWINT) | (1 << TWSTO) | (1 << TWEN) | (1 << TWIE);
                current_status = I2C_STATUS_SUCCESS;
            }
            break;

        case 0x40: // SLA+R transmitted, ACK received
            if (transfer_length > 1) {
                // Expect more than 1 byte, send ACK
                // ref: ds-023, ATmega328P datasheet rev. DS40002061B, tr.235-240
                TWCR = (1 << TWINT) | (1 << TWEA) | (1 << TWEN) | (1 << TWIE);
            } else {
                // Expect 1 byte, send NACK
                TWCR = (1 << TWINT) | (1 << TWEN) | (1 << TWIE);
            }
            break;

        case 0x50: // Data received, ACK returned
            rx_buffer[transfer_index++] = TWDR;
            if (transfer_index < transfer_length - 1) {
                // More bytes to receive, send ACK
                // ref: ds-023, ATmega328P datasheet rev. DS40002061B, tr.235-240
                TWCR = (1 << TWINT) | (1 << TWEA) | (1 << TWEN) | (1 << TWIE);
            } else {
                // Last byte to receive, send NACK
                TWCR = (1 << TWINT) | (1 << TWEN) | (1 << TWIE);
            }
            break;

        case 0x58: // Data received, NACK returned
            rx_buffer[transfer_index++] = TWDR;
            // Send STOP
            TWCR = (1 << TWINT) | (1 << TWSTO) | (1 << TWEN) | (1 << TWIE);
            current_status = I2C_STATUS_SUCCESS;
            break;

        case 0x38: // Arbitration lost
            TWCR = (1 << TWINT) | (1 << TWEN) | (1 << TWIE);
            current_status = I2C_STATUS_ERROR;
            break;

        case 0x20: // SLA+W transmitted, NACK received
        case 0x30: // Data transmitted, NACK received
        case 0x48: // SLA+R transmitted, NACK received
        default:
            // Error, send STOP
            TWCR = (1 << TWINT) | (1 << TWSTO) | (1 << TWEN) | (1 << TWIE);
            current_status = I2C_STATUS_ERROR;
            break;
    }
}
