```file:src/drv_stepper.c
#include "drv_stepper.h"
#include <avr/io.h>
#include <avr/interrupt.h>

volatile int16_t target_threshold_left = 0;
volatile int16_t target_threshold_right = 0;

int16_t current_threshold_left = 32767;
int16_t current_threshold_right = 32767;

uint16_t counter_left = 0;
uint16_t counter_right = 0;

void stepper_init(void) {
    // Configure PD4 (DIR_R), PD5 (STEP_R), PD6 (DIR_L), PD7 (STEP_L) as output
    DDRD |= (1 << PD4) | (1 << PD5) | (1 << PD6) | (1 << PD7);
    PORTD &= ~((1 << PD4) | (1 << PD5) | (1 << PD6) | (1 << PD7));

    // ref: ds-atme-timer2-01, ATmega48A-PA-88A-PA-168A-PA-328-P-DS-DS40002061B.pdf, tr.155,165-166
    TCCR2A = (1 << WGM21);
    TCCR2B = (1 << CS21);
    OCR2A = 39;
    TIMSK2 |= (1 << OCIE2A);
}

void stepper_set_speed(int16_t speed_left, int16_t speed_right) {
    uint8_t sreg = SREG;
    cli();
    target_threshold_left = speed_left;
    target_threshold_right = speed_right;
    SREG = sreg;
}

ISR(TIMER2_COMPA_vect) {
    // Left motor
    counter_left++;
    if (counter_left > current_threshold_left) {
        counter_left = 0;
        int16_t target = target_threshold_left;
        if (target == 0) {
            current_threshold_left = 32767;
        } else {
            if (target > 0) {
                PORTD |= (1 << PD6); // Left forward: DIR = 1
                current_threshold_left = target;
            } else {
                PORTD &= ~(1 << PD6); // Left backward: DIR = 0
                current_threshold_left = -target;
            }
        }
    }
    if (counter_left == 1 && current_threshold_left != 32767) {
        PORTD |= (1 << PD7); // STEP left HIGH
    } else if (counter_left == 2) {
        PORTD &= ~(1 << PD7); // STEP left LOW
    }

    // Right motor
    counter_right++;
    if (counter_right > current_threshold_right) {
        counter_right = 0;
        int16_t target = target_threshold_right;
        if (target == 0) {
            current_threshold_right = 32767;
        } else {
            if (target > 0) {
                PORTD &= ~(1 << PD4); // Right forward: DIR = 0
                current_threshold_right = target;
            } else {
                PORTD |= (1 << PD4); // Right backward: DIR = 1
                current_threshold_right = -target;
            }
        }
    }
    if (counter_right == 1 && current_threshold_right != 32767) {
        PORTD |= (1 << PD5); // STEP right HIGH
    } else if (counter_right == 2) {
        PORTD &= ~(1 << PD5); // STEP right LOW
    }
}
