    assert TCCR2B == (1 << 1)  # CS21 = 1
    assert OCR2A == 39
    assert TIMSK2 == (1 << 1)  # OCIE2A = 1

def test_stepper_direction_and_step():
    lib.stepper_set_speed(10, 10)

    # Run ISR enough times to guarantee a reset (max threshold is 32767)
    for _ in range(33000):
        lib.TIMER2_COMPA_vect_fn()

    # Sync to counter=1 (STEP goes high)
    synced = False
    for _ in range(20):
        lib.TIMER2_COMPA_vect_fn()
        PORTD = ctypes.c_uint8.in_dll(lib, "PORTD").value
        if (PORTD & (1 << 7)):
            synced = True
            break

    assert synced

    PORTD_after_1 = ctypes.c_uint8.in_dll(lib, "PORTD").value
    lib.TIMER2_COMPA_vect_fn() # counter = 2
    PORTD_after_2 = ctypes.c_uint8.in_dll(lib, "PORTD").value

    # Check DIR pins for positive speed
    # Left positive -> DIR=1 (PD6=1)
    # Right positive -> DIR=0 (PD4=0)
    assert (PORTD_after_1 & (1 << 6)) != 0
    assert (PORTD_after_1 & (1 << 4)) == 0

    # Check STEP pins duration (high at counter=1, low at counter=2)
    assert (PORTD_after_1 & (1 << 7)) != 0
    assert (PORTD_after_2 & (1 << 7)) == 0
    assert (PORTD_after_1 & (1 << 5)) != 0
    assert (PORTD_after_2 & (1 << 5)) == 0

def test_stepper_negative_direction():
    lib.stepper_set_speed(-10, -10)

    # Run ISR enough times to guarantee a reset
    for _ in range(33000):
        lib.TIMER2_COMPA_vect_fn()

    # Sync to counter=1
    for _ in range(20):
        lib.TIMER2_COMPA_vect_fn()
        PORTD = ctypes.c_uint8.in_dll(lib, "PORTD").value
        if (PORTD & (1 << 7)):
            break

    PORTD = ctypes.c_uint8.in_dll(lib, "PORTD").value

    # Check DIR pins for negative speed
    # Left negative -> DIR=0 (PD6=0)
    # Right negative -> DIR=1 (PD4=1)
    assert (PORTD & (1 << 6)) == 0
    assert (PORTD & (1 << 4)) != 0

def test_stepper_speed_difference():
    # Left threshold is smaller (faster), Right threshold is larger (slower)
    lib.stepper_set_speed(10, 20)

    # Run ISR enough times to guarantee a reset
    for _ in range(33000):
        lib.TIMER2_COMPA_vect_fn()

    left_steps = 0
    right_steps = 0

    # Count steps over 1000 ISR calls
    for _ in range(1000):
        lib.TIMER2_COMPA_vect_fn()
        PORTD = ctypes.c_uint8.in_dll(lib, "PORTD").value
        if (PORTD & (1 << 7)): # Left STEP high
            left_steps += 1
        if (PORTD & (1 << 5)): # Right STEP high
            right_steps += 1

    # Smaller threshold should produce more steps
    assert left_steps > right_steps
    # Left threshold 10 -> resets at 11 -> ~90 steps in 1000 calls
    assert left_steps > 80
    # Right threshold 20 -> resets at 21 -> ~47 steps in 1000 calls
    assert right_steps < 60
