#include "drv_stepper.h"
#include <avr/io.h>
#include <avr/interrupt.h>

volatile int16_t g_target_speed_left = 0;
volatile int16_t g_target_speed_right = 0;

void stepper_init(void) {
    // Cấu hình chân output
    // Phải: STEP = PD5, DIR = PD4
    // Trái: STEP = PD7, DIR = PD6
    DDRD |= (1 << PD4) | (1 << PD5) | (1 << PD6) | (1 << PD7);
    PORTD &= ~((1 << PD4) | (1 << PD5) | (1 << PD6) | (1 << PD7));

    // ref: ds-atme-timer2-01, ATmega48A-PA-88A-PA-168A-PA-328-P-DS-DS40002061B.pdf, tr.155,165-166
    TCCR2A = 0;
    TCCR2B = 0;
    TCNT2 = 0;

    // CTC mode: WGM21 = 1
    TCCR2A |= (1 << WGM21);

    // Prescaler 8: CS21 = 1
    TCCR2B |= (1 << CS21);

    // OCR2A = 39 (chu kỳ 20 us)
    OCR2A = 39;

    // Enable interrupt
    TIMSK2 |= (1 << OCIE2A);
}

void stepper_set_speed(int16_t left, int16_t right) {
    uint8_t sreg = SREG;
    cli();
    g_target_speed_left = left;
    g_target_speed_right = right;
    SREG = sreg;
}

ISR(TIMER2_COMPA_vect) {
    static uint16_t counter_left = 0;
    static uint16_t threshold_left = 0;
    static uint8_t is_stopped_left = 1;

    static uint16_t counter_right = 0;
    static uint16_t threshold_right = 0;
    static uint8_t is_stopped_right = 1;

    // Động cơ trái
    counter_left++;
    if (counter_left > threshold_left) {
        counter_left = 0;
        int16_t new_val = g_target_speed_left;
        if (new_val == 0) {
            is_stopped_left = 1;
            threshold_left = 0;
        } else {
            is_stopped_left = 0;
            if (new_val > 0) {
                threshold_left = (uint16_t)new_val;
                PORTD |= (1 << PD6); // Trái tiến: 1
            } else {
                threshold_left = (uint16_t)(-new_val);
                PORTD &= ~(1 << PD6); // Trái lùi: 0
            }
        }
    }
    if (!is_stopped_left) {
        if (counter_left == 1) {
            PORTD |= (1 << PD7);
        } else if (counter_left == 2) {
            PORTD &= ~(1 << PD7);
        }
    }

    // Động cơ phải
    counter_right++;
    if (counter_right > threshold_right) {
        counter_right = 0;
        int16_t new_val = g_target_speed_right;
        if (new_val == 0) {
            is_stopped_right = 1;
            threshold_right = 0;
        } else {
            is_stopped_right = 0;
            if (new_val > 0) {
                threshold_right = (uint16_t)new_val;
                PORTD &= ~(1 << PD4); // Phải tiến: 0
            } else {
                threshold_right = (uint16_t)(-new_val);
                PORTD |= (1 << PD4); // Phải lùi: 1
            }
        }
    }
    if (!is_stopped_right) {
        if (counter_right == 1) {
            PORTD |= (1 << PD5);
        } else if (counter_right == 2) {
            PORTD &= ~(1 << PD5);
        }
    }
}
