```file:src/drv_imu.c
#include "drv_imu.h"
#include "drv_i2c.h"
#include <avr/io.h>
#include <stddef.h>

#define MPU6050_ADDR         0x68
#define MPU6050_SMPLRT_DIV   0x19
#define MPU6050_CONFIG       0x1A
#define MPU6050_GYRO_CONFIG  0x1B
#define MPU6050_ACCEL_CONFIG 0x1C
#define MPU6050_ACCEL_XOUT_H 0x3B
#define MPU6050_GYRO_XOUT_H  0x43
#define MPU6050_PWR_MGMT_1   0x6B
#define MPU6050_WHO_AM_I     0x75

typedef enum {
    STATE_START = 0,
    STATE_WHOAMI_READ,
    STATE_RESET,
    STATE_RESET_WAIT,
    STATE_CONFIG,
    STATE_IDLE,
    STATE_READING,
    STATE_PROCESS
} imu_state_t;

static imu_state_t imu_state = STATE_START;
static uint8_t i2c_buf[16];
static uint8_t wait_counter = 0;
static int32_t tilt_angle_mdeg = 0;

void imu_init(void) {
    // ref: ds-021, ATmega328P datasheet rev. DS40002061B, tr.222-224
    TWBR = 12;
    TWSR &= ~((1 << 1) | (1 << 0));
    TWCR = (1 << 2);
    TWDR = 0xFF;

    imu_state = STATE_START;
    tilt_angle_mdeg = 0;
}

void imu_update(void) {
    i2c_status_t status = i2c_get_status();
    if (status == I2C_STATUS_BUSY) {
        return;
    }
    if (status == I2C_STATUS_ERROR) {
        imu_state = STATE_START;
        return;
    }

    switch (imu_state) {
        case STATE_START:
            i2c_buf[0] = MPU6050_WHO_AM_I;
            // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
            if (i2c_write_async(MPU6050_ADDR, i2c_buf, 1)) {
                imu_state = STATE_WHOAMI_READ;
            }
            break;

        case STATE_WHOAMI_READ:
            if (i2c_read_async(MPU6050_ADDR, i2c_buf, 1)) {
                imu_state = STATE_RESET;
            }
            break;

        case STATE_RESET:
            if (i2c_buf[0] != 0x68) {
                imu_state = STATE_START;
                break;
            }
            i2c_buf[0] = MPU6050_PWR_MGMT_1;
            i2c_buf[1] = 0x80;
            // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
            if (i2c_write_async(MPU6050_ADDR, i2c_buf, 2)) {
                imu_state = STATE_RESET_WAIT;
                wait_counter = 10;
            }
            break;

        case STATE_RESET_WAIT:
            if (wait_counter > 0) {
                wait_counter--;
            } else {
                i2c_buf[0] = MPU6050_PWR_MGMT_1;
                i2c_buf[1] = 0x01;
                // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
                if (i2c_write_async(MPU6050_ADDR, i2c_buf, 2)) {
                    imu_state = STATE_CONFIG;
                }
            }
            break;

        case STATE_CONFIG:
            i2c_buf[0] = MPU6050_SMPLRT_DIV;
            i2c_buf[1] = 0x09;
            i2c_buf[2] = 0x03;
            i2c_buf[3] = 0x00;
            i2c_buf[4] = 0x00;
            // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
            // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
            if (i2c_write_async(MPU6050_ADDR, i2c_buf, 5)) {
                imu_state = STATE_IDLE;
            }
            break;

        case STATE_IDLE:
            i2c_buf[0] = MPU6050_ACCEL_XOUT_H;
            // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
            if (i2c_write_async(MPU6050_ADDR, i2c_buf, 1)) {
                imu_state = STATE_READING;
            }
            break;

        case STATE_READING:
            // Read 14 bytes starting from ACCEL_XOUT_H to GYRO_ZOUT_L
            // GYRO_XOUT_H is at offset 8
            if (i2c_read_async(MPU6050_ADDR, i2c_buf, 14)) {
                imu_state = STATE_PROCESS;
            }
            break;

        case STATE_PROCESS:
            {
                int16_t accel_y = (int16_t)((i2c_buf[2] << 8) | i2c_buf[3]);
                int16_t accel_z = (int16_t)((i2c_buf[4] << 8) | i2c_buf[5]);
                int16_t gyro_x  = (int16_t)((i2c_buf[8] << 8) | i2c_buf[9]);

                int32_t accel_angle_mdeg = 0;
                if (accel_z != 0) {
                    accel_angle_mdeg = ((int32_t)accel_y * 57296) / accel_z;
                } else {
                    accel_angle_mdeg = (accel_y > 0) ? 90000 : -90000;
                }

                int32_t delta_angle_mdeg = ((int32_t)gyro_x * 20) / 131;

                tilt_angle_mdeg = (98 * (tilt_angle_mdeg + delta_angle_mdeg) + 2 * accel_angle_mdeg) / 100;
            }

            i2c_buf[0] = MPU6050_ACCEL_XOUT_H;
            if (i2c_write_async(MPU6050_ADDR, i2c_buf, 1)) {
                imu_state = STATE_READING;
            } else {
                imu_state = STATE_IDLE;
            }
            break;
    }
}

int32_t imu_get_tilt_angle(void) {
    return tilt_angle_mdeg;
}
