```file:src/drv_imu.c
#include "drv_imu.h"
#include "drv_i2c.h"
#include <avr/io.h>

// ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
#define MPU6050_WHO_AM_I     0x75
#define MPU6050_PWR_MGMT_1   0x6B
#define MPU6050_SMPLRT_DIV   0x19
#define MPU6050_CONFIG       0x1A

// ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
#define MPU6050_GYRO_CONFIG  0x1B
#define MPU6050_ACCEL_CONFIG 0x1C
#define MPU6050_ACCEL_XOUT_H 0x3B
#define MPU6050_GYRO_XOUT_H  0x43

static const uint8_t imu_whoami_cmd[] = {MPU6050_WHO_AM_I};
static const uint8_t imu_reset_cmd[] = {MPU6050_PWR_MGMT_1, 0x80};
static const uint8_t imu_wakeup_cmd[] = {MPU6050_PWR_MGMT_1, 0x01};
static const uint8_t imu_config_cmd[] = {MPU6050_SMPLRT_DIV, 0x09, 0x03, 0x00, 0x00};
static const uint8_t imu_read_cmd[] = {MPU6050_ACCEL_XOUT_H};

typedef enum {
    IMU_ST_UNINIT = 0,
    IMU_ST_INIT_WHOAMI_REQ,
    IMU_ST_INIT_WHOAMI_WAIT,
    IMU_ST_INIT_WHOAMI_READ,
    IMU_ST_INIT_WHOAMI_READ_WAIT,
    IMU_ST_INIT_RESET,
    IMU_ST_INIT_RESET_WAIT,
    IMU_ST_INIT_WAKEUP,
    IMU_ST_INIT_WAKEUP_WAIT,
    IMU_ST_INIT_CONFIG,
    IMU_ST_INIT_CONFIG_WAIT,
    IMU_ST_INIT_DELAY,
    IMU_ST_IDLE,
    IMU_ST_READ_ADDR,
    IMU_ST_READ_ADDR_WAIT,
    IMU_ST_READ_DATA,
    IMU_ST_READ_DATA_WAIT
} imu_state_t;

static imu_state_t imu_state = IMU_ST_UNINIT;
static uint8_t imu_rx_buf[14];
static uint8_t delay_counter = 0;
static uint32_t imu_ticks = 0;
static uint32_t last_process_ticks = 0;
static int32_t current_angle_scaled = 0;

void imu_init(void) {
    // ref: ds-021, ATmega328P datasheet rev. DS40002061B, tr.222-224
    TWSR = 0x00;
    // ref: ds-021, ATmega328P datasheet rev. DS40002061B, tr.222-224
    TWBR = 12;
    // ref: ds-021, ATmega328P datasheet rev. DS40002061B, tr.222-224
    TWDR = 0xFF;
    // ref: ds-021, ATmega328P datasheet rev. DS40002061B, tr.222-224
    TWCR = (1 << 2);

    i2c_init();
    imu_state = IMU_ST_INIT_WHOAMI_REQ;
}

static void imu_process_data(uint32_t dt_ticks) {
    int16_t accel_y = (int16_t)((imu_rx_buf[2] << 8) | imu_rx_buf[3]);
    int16_t accel_z = (int16_t)((imu_rx_buf[4] << 8) | imu_rx_buf[5]);
    int16_t gyro_x  = (int16_t)((imu_rx_buf[8] << 8) | imu_rx_buf[9]);

    int32_t az = accel_z / 16;
    if (az == 0) {
        az = (accel_z >= 0) ? 1 : -1;
    }

    int32_t accel_angle_scaled = ( (int32_t)(accel_y / 16) * 750574L ) / az;
    int32_t gyro_delta = (int32_t)gyro_x * (int32_t)dt_ticks;

    current_angle_scaled = (current_angle_scaled + gyro_delta) * 98 / 100 + accel_angle_scaled * 2 / 100;
}

void imu_update(void) {
    imu_ticks++;

    switch (imu_state) {
        case IMU_ST_UNINIT:
            break;

        case IMU_ST_INIT_WHOAMI_REQ:
            // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
            if (i2c_write_async(104, imu_whoami_cmd, 1)) {
                imu_state = IMU_ST_INIT_WHOAMI_WAIT;
            }
            break;

        case IMU_ST_INIT_WHOAMI_WAIT:
            if (i2c_get_status() == I2C_STATUS_SUCCESS) {
                imu_state = IMU_ST_INIT_WHOAMI_READ;
            } else if (i2c_get_status() == I2C_STATUS_ERROR) {
                imu_state = IMU_ST_INIT_WHOAMI_REQ;
            }
            break;

        case IMU_ST_INIT_WHOAMI_READ:
            // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
            if (i2c_read_async(104, imu_rx_buf, 1)) {
                imu_state = IMU_ST_INIT_WHOAMI_READ_WAIT;
            }
            break;

        case IMU_ST_INIT_WHOAMI_READ_WAIT:
            if (i2c_get_status() == I2C_STATUS_SUCCESS) {
                if (imu_rx_buf[0] == 0x68) {
                    imu_state = IMU_ST_INIT_RESET;
                } else {
                    imu_state = IMU_ST_INIT_WHOAMI_REQ;
                }
            } else if (i2c_get_status() == I2C_STATUS_ERROR) {
                imu_state = IMU_ST_INIT_WHOAMI_REQ;
            }
            break;

        case IMU_ST_INIT_RESET:
            // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
            if (i2c_write_async(104, imu_reset_cmd, 2)) {
                imu_state = IMU_ST_INIT_RESET_WAIT;
            }
            break;

        case IMU_ST_INIT_RESET_WAIT:
            if (i2c_get_status() == I2C_STATUS_SUCCESS) {
                imu_state = IMU_ST_INIT_WAKEUP;
            } else if (i2c_get_status() == I2C_STATUS_ERROR) {
                imu_state = IMU_ST_INIT_RESET;
            }
            break;

        case IMU_ST_INIT_WAKEUP:
            // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
            if (i2c_write_async(104, imu_wakeup_cmd, 2)) {
                imu_state = IMU_ST_INIT_WAKEUP_WAIT;
            }
            break;

        case IMU_ST_INIT_WAKEUP_WAIT:
            if (i2c_get_status() == I2C_STATUS_SUCCESS) {
                imu_state = IMU_ST_INIT_CONFIG;
            } else if (i2c_get_status() == I2C_STATUS_ERROR) {
                imu_state = IMU_ST_INIT_WAKEUP;
            }
            break;

        case IMU_ST_INIT_CONFIG:
            // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
            // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
            if (i2c_write_async(104, imu_config_cmd, 5)) {
                imu_state = IMU_ST_INIT_CONFIG_WAIT;
            }
            break;

        case IMU_ST_INIT_CONFIG_WAIT:
            if (i2c_get_status() == I2C_STATUS_SUCCESS) {
                imu_state = IMU_ST_INIT_DELAY;
                delay_counter = 0;
            } else if (i2c_get_status() == I2C_STATUS_ERROR) {
                imu_state = IMU_ST_INIT_CONFIG;
            }
            break;

        case IMU_ST_INIT_DELAY:
            delay_counter++;
            if (delay_counter >= 10) {
                imu_state = IMU_ST_IDLE;
                last_process_ticks = imu_ticks;
            }
            break;

        case IMU_ST_IDLE:
            // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
            if (i2c_write_async(104, imu_read_cmd, 1)) {
                imu_state = IMU_ST_READ_ADDR_WAIT;
            }
            break;

        case IMU_ST_READ_ADDR_WAIT:
            if (i2c_get_status() == I2C_STATUS_SUCCESS) {
                imu_state = IMU_ST_READ_DATA;
            } else if (i2c_get_status() == I2C_STATUS_ERROR) {
                imu_state = IMU_ST_IDLE;
            }
            break;

        case IMU_ST_READ_DATA:
            // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
            if (i2c_read_async(104, imu_rx_buf, 14)) {
                imu_state = IMU_ST_READ_DATA_WAIT;
            }
            break;

        case IMU_ST_READ_DATA_WAIT:
            if (i2c_get_status() == I2C_STATUS_SUCCESS) {
                uint32_t dt_ticks = imu_ticks - last_process_ticks;
                last_process_ticks = imu_ticks;
                imu_process_data(dt_ticks);
                imu_state = IMU_ST_IDLE;
            } else if (i2c_get_status() == I2C_STATUS_ERROR) {
                imu_state = IMU_ST_IDLE;
            }
            break;
    }
}

int16_t imu_get_tilt_angle(void) {
    return (int16_t)(current_angle_scaled / 13100);
}
