```file:src/drv_imu.c
#include "drv_imu.h"
#include "drv_i2c.h"
#include <avr/io.h>
#include <stddef.h>

#define MPU6050_ADDR 0x68

typedef enum {
    IMU_ST_UNINIT = 0,
    IMU_ST_CHECK_WHOAMI_REQ,
    IMU_ST_CHECK_WHOAMI_WAIT,
    IMU_ST_CHECK_WHOAMI_READ_WAIT,
    IMU_ST_RESET_REQ,
    IMU_ST_RESET_WAIT,
    IMU_ST_PWR_REQ,
    IMU_ST_PWR_WAIT,
    IMU_ST_PWR_DELAY,
    IMU_ST_CFG_REQ,
    IMU_ST_CFG_WAIT,
    IMU_ST_READY,
    IMU_ST_READ_ADDR_WAIT,
    IMU_ST_READ_DATA_WAIT,
    IMU_ST_ERROR
} imu_state_t;

static imu_state_t state = IMU_ST_UNINIT;
static uint8_t delay_counter = 0;
static uint8_t tx_buf[5];
static uint8_t rx_buf[14];
static int32_t current_angle_deg100 = 0;

void imu_init(void) {
    // ref: ds-021, ATmega328P datasheet rev. DS40002061B, tr.222-224
    TWBR = 12;
    TWSR = 0x00;
    TWCR = (1 << 2); // TWEN
    TWDR = 0xFF;

    state = IMU_ST_UNINIT;
    current_angle_deg100 = 0;
    delay_counter = 0;
}

static int32_t approx_atan2_deg100(int32_t y, int32_t x) {
    if (x == 0 && y == 0) return 0;
    int32_t abs_y = y > 0 ? y : -y;
    int32_t abs_x = x > 0 ? x : -x;
    int32_t a = abs_x < abs_y ? abs_x : abs_y;
    int32_t b = abs_x > abs_y ? abs_x : abs_y;
    if (b == 0) return 0;
    int32_t r = (a * 1000) / b;

    int32_t angle = (4500 * r) / 1000;

    if (abs_x < abs_y) angle = 9000 - angle;
    if (x < 0) angle = 18000 - angle;
    if (y < 0) angle = -angle;
    return angle;
}

static void imu_process_data(void) {
    // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
    // ACCEL_XOUT_H (0x3B) to GYRO_ZOUT_L (0x48)
    // GYRO_XOUT_H is 0x43
    int16_t accel_y = (int16_t)(((uint16_t)rx_buf[2] << 8) | rx_buf[3]);
    int16_t accel_z = (int16_t)(((uint16_t)rx_buf[4] << 8) | rx_buf[5]);
    int16_t gyro_x  = (int16_t)(((uint16_t)rx_buf[8] << 8) | rx_buf[9]);

    int32_t accel_angle = approx_atan2_deg100(accel_y, accel_z);

    // dt = 30ms, gyro sensitivity = 131 LSB/(deg/s)
    // delta_angle_deg100 = gyro_x * 100 * 0.03 / 131 = gyro_x * 3 / 131
    int32_t gyro_delta = ((int32_t)gyro_x * 3) / 131;

    current_angle_deg100 = (980 * (current_angle_deg100 + gyro_delta) + 20 * accel_angle) / 1000;
}

void imu_update(void) {
    i2c_status_t i2c_st = i2c_get_status();

    switch (state) {
        case IMU_ST_UNINIT:
            if (i2c_st == I2C_STATUS_IDLE || i2c_st == I2C_STATUS_SUCCESS) {
                tx_buf[0] = 0x75; // WHO_AM_I
                // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
                if (i2c_write_async(MPU6050_ADDR, tx_buf, 1)) {
                    state = IMU_ST_CHECK_WHOAMI_WAIT;
                }
            }
            break;

        case IMU_ST_CHECK_WHOAMI_WAIT:
            if (i2c_st == I2C_STATUS_SUCCESS) {
                if (i2c_read_async(MPU6050_ADDR, rx_buf, 1)) {
                    state = IMU_ST_CHECK_WHOAMI_READ_WAIT;
                }
            } else if (i2c_st == I2C_STATUS_ERROR) {
                state = IMU_ST_ERROR;
            }
            break;

        case IMU_ST_CHECK_WHOAMI_READ_WAIT:
            if (i2c_st == I2C_STATUS_SUCCESS) {
                if (rx_buf[0] == 0x68) {
                    state = IMU_ST_RESET_REQ;
                } else {
                    state = IMU_ST_ERROR;
                }
            } else if (i2c_st == I2C_STATUS_ERROR) {
                state = IMU_ST_ERROR;
            }
            break;

        case IMU_ST_RESET_REQ:
            if (i2c_st == I2C_STATUS_IDLE || i2c_st == I2C_STATUS_SUCCESS) {
                tx_buf[0] = 0x6B; // PWR_MGMT_1
                tx_buf[1] = 0x80; // Reset
                if (i2c_write_async(MPU6050_ADDR, tx_buf, 2)) {
                    state = IMU_ST_RESET_WAIT;
                }
            }
            break;

        case IMU_ST_RESET_WAIT:
            if (i2c_st == I2C_STATUS_SUCCESS) {
                delay_counter = 10; // 100ms
                state = IMU_ST_PWR_REQ;
            } else if (i2c_st == I2C_STATUS_ERROR) {
                state = IMU_ST_ERROR;
            }
            break;

        case IMU_ST_PWR_REQ:
            if (delay_counter > 0) {
                delay_counter--;
            } else {
                if (i2c_st == I2C_STATUS_IDLE || i2c_st == I2C_STATUS_SUCCESS) {
                    tx_buf[0] = 0x6B; // PWR_MGMT_1
                    tx_buf[1] = 0x01; // Clock PLL X
                    if (i2c_write_async(MPU6050_ADDR, tx_buf, 2)) {
                        state = IMU_ST_PWR_WAIT;
                    }
                }
            }
            break;

        case IMU_ST_PWR_WAIT:
            if (i2c_st == I2C_STATUS_SUCCESS) {
                delay_counter = 10; // 100ms
                state = IMU_ST_PWR_DELAY;
            } else if (i2c_st == I2C_STATUS_ERROR) {
                state = IMU_ST_ERROR;
            }
            break;

        case IMU_ST_PWR_DELAY:
            if (delay_counter > 0) {
                delay_counter--;
            } else {
                state = IMU_ST_CFG_REQ;
            }
            break;

        case IMU_ST_CFG_REQ:
            if (i2c_st == I2C_STATUS_IDLE || i2c_st == I2C_STATUS_SUCCESS) {
                // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
                // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
                tx_buf[0] = 0x19; // SMPLRT_DIV
                tx_buf[1] = 0x07; // SMPLRT_DIV = 7
                tx_buf[2] = 0x03; // CONFIG = 3
                tx_buf[3] = 0x00; // GYRO_CONFIG = 0
                tx_buf[4] = 0x00; // ACCEL_CONFIG = 0
                if (i2c_write_async(MPU6050_ADDR, tx_buf, 5)) {
                    state = IMU_ST_CFG_WAIT;
                }
            }
            break;

        case IMU_ST_CFG_WAIT:
            if (i2c_st == I2C_STATUS_SUCCESS) {
                state = IMU_ST_READY;
            } else if (i2c_st == I2C_STATUS_ERROR) {
                state = IMU_ST_ERROR;
            }
            break;

        case IMU_ST_READY:
            if (i2c_st == I2C_STATUS_IDLE || i2c_st == I2C_STATUS_SUCCESS) {
                tx_buf[0] = 0x3B; // ACCEL_XOUT_H
                if (i2c_write_async(MPU6050_ADDR, tx_buf, 1)) {
                    state = IMU_ST_READ_ADDR_WAIT;
                }
            }
            break;

        case IMU_ST_READ_ADDR_WAIT:
            if (i2c_st == I2C_STATUS_SUCCESS) {
                if (i2c_read_async(MPU6050_ADDR, rx_buf, 14)) {
                    state = IMU_ST_READ_DATA_WAIT;
                }
            } else if (i2c_st == I2C_STATUS_ERROR) {
                state = IMU_ST_ERROR;
            }
            break;

        case IMU_ST_READ_DATA_WAIT:
            if (i2c_st == I2C_STATUS_SUCCESS) {
                imu_process_data();
                state = IMU_ST_READY;
            } else if (i2c_st == I2C_STATUS_ERROR) {
                state = IMU_ST_ERROR;
            }
            break;

        case IMU_ST_ERROR:
            delay_counter++;
            if (delay_counter > 100) {
                state = IMU_ST_UNINIT;
                delay_counter = 0;
            }
            break;
    }
}

