                }
            } else if (i2c_st == I2C_STATUS_ERROR) {
                state = IMU_ST_ERROR;
            }
            break;

        case IMU_ST_RESET_REQ:
            if (i2c_st == I2C_STATUS_IDLE || i2c_st == I2C_STATUS_SUCCESS) {
                tx_buf[0] = 0x6B; // PWR_MGMT_1
                tx_buf[1] = 0x80; // Reset
