#include "drv_imu.h"
#include "drv_i2c.h"
#include <avr/io.h>

#define MPU6050_ADDR 0x68

#define ACCEL_CONFIG 0x1C
#define ACCEL_XOUT_H 0x3B
#define CONFIG 0x1A
#define GYRO_CONFIG 0x1B
#define GYRO_XOUT_H 0x43
#define PWR_MGMT_1 0x6B
#define SMPLRT_DIV 0x19
#define WHO_AM_I 0x75

typedef struct {
    uint8_t reg;
    uint8_t val;
} mpu_config_t;

static const mpu_config_t init_seq[] = {
    // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
    {PWR_MGMT_1, 0x80},
    // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
    {PWR_MGMT_1, 0x01},
    // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
    {SMPLRT_DIV, 0x07},
    // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
    {CONFIG, 0x03},
    // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
    {GYRO_CONFIG, 0x00},
    // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
    {ACCEL_CONFIG, 0x00}
};

typedef enum {
    IMU_ST_START = 0,
    IMU_ST_CHECK_WHOAMI_WAIT_TX,
    IMU_ST_CHECK_WHOAMI_WAIT_RX,
    IMU_ST_INIT_WRITE,
    IMU_ST_INIT_WAIT_I2C,
    IMU_ST_INIT_DELAY,
    IMU_ST_IDLE,
    IMU_ST_READ_ADDR_WAIT,
    IMU_ST_READ_DATA_WAIT
} imu_state_t;

static imu_state_t current_state = IMU_ST_START;
static uint8_t init_idx = 0;
static uint16_t wait_cycles = 0;
static uint8_t i2c_tx_buf[2];
static uint8_t i2c_rx_buf[14];
static int32_t angle_scaled = 0;

void imu_init(void) {
    // ref: ds-021, ATmega328P datasheet rev. DS40002061B, tr.222-224
    TWSR = 0x00;
    // ref: ds-021, ATmega328P datasheet rev. DS40002061B, tr.222-224
    TWBR = 12;
    // ref: ds-021, ATmega328P datasheet rev. DS40002061B, tr.222-224
    TWDR = 0xFF;
    // ref: ds-021, ATmega328P datasheet rev. DS40002061B, tr.222-224
    TWCR = (1 << 2);

    i2c_init();
    current_state = IMU_ST_START;
    angle_scaled = 0;
}

void imu_update(void) {
    switch (current_state) {
        case IMU_ST_START:
            // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
            i2c_tx_buf[0] = WHO_AM_I;
            if (i2c_write_async(MPU6050_ADDR, i2c_tx_buf, 1)) {
                current_state = IMU_ST_CHECK_WHOAMI_WAIT_TX;
            }
            break;

        case IMU_ST_CHECK_WHOAMI_WAIT_TX:
            if (i2c_get_status() == I2C_STATUS_SUCCESS) {
                if (i2c_read_async(MPU6050_ADDR, i2c_rx_buf, 1)) {
                    current_state = IMU_ST_CHECK_WHOAMI_WAIT_RX;
                }
            } else if (i2c_get_status() == I2C_STATUS_ERROR) {
                current_state = IMU_ST_START;
            }
            break;

        case IMU_ST_CHECK_WHOAMI_WAIT_RX:
            if (i2c_get_status() == I2C_STATUS_SUCCESS) {
                if (i2c_rx_buf[0] == 0x68) {
                    init_idx = 0;
                    current_state = IMU_ST_INIT_WRITE;
                } else {
                    current_state = IMU_ST_START;
                }
            } else if (i2c_get_status() == I2C_STATUS_ERROR) {
                current_state = IMU_ST_START;
            }
            break;

        case IMU_ST_INIT_WRITE:
            if (init_idx < sizeof(init_seq)/sizeof(init_seq[0])) {
                i2c_tx_buf[0] = init_seq[init_idx].reg;
                i2c_tx_buf[1] = init_seq[init_idx].val;
                if (i2c_write_async(MPU6050_ADDR, i2c_tx_buf, 2)) {
                    current_state = IMU_ST_INIT_WAIT_I2C;
                }
            } else {
                wait_cycles = 0;
                current_state = IMU_ST_INIT_DELAY;
            }
            break;

        case IMU_ST_INIT_WAIT_I2C:
            if (i2c_get_status() == I2C_STATUS_SUCCESS) {
                init_idx++;
                current_state = IMU_ST_INIT_WRITE;
            } else if (i2c_get_status() == I2C_STATUS_ERROR) {
                current_state = IMU_ST_START;
            }
            break;

        case IMU_ST_INIT_DELAY:
            wait_cycles++;
            if (wait_cycles >= 10) {
                current_state = IMU_ST_IDLE;
            }
            break;

        case IMU_ST_IDLE:
            // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
            i2c_tx_buf[0] = ACCEL_XOUT_H;
            if (i2c_write_async(MPU6050_ADDR, i2c_tx_buf, 1)) {
                current_state = IMU_ST_READ_ADDR_WAIT;
            }
            break;

        case IMU_ST_READ_ADDR_WAIT:
            if (i2c_get_status() == I2C_STATUS_SUCCESS) {
                if (i2c_read_async(MPU6050_ADDR, i2c_rx_buf, 14)) {
                    current_state = IMU_ST_READ_DATA_WAIT;
                }
            } else if (i2c_get_status() == I2C_STATUS_ERROR) {
                current_state = IMU_ST_IDLE;
            }
            break;

        case IMU_ST_READ_DATA_WAIT:
            if (i2c_get_status() == I2C_STATUS_SUCCESS) {
                // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
                uint8_t dummy = GYRO_XOUT_H;
                (void)dummy;

                int16_t accel_x = (int16_t)((i2c_rx_buf[0] << 8) | i2c_rx_buf[1]);
                int16_t gyro_y = (int16_t)((i2c_rx_buf[10] << 8) | i2c_rx_buf[11]);

                int32_t gyro_dt_scaled = ((int32_t)gyro_y * 10) / 131;
                int32_t accel_angle_scaled = ((int32_t)accel_x * 3497) / 1000;

                angle_scaled = (98 * (angle_scaled + gyro_dt_scaled) + 2 * accel_angle_scaled) / 100;

                current_state = IMU_ST_IDLE;
            } else if (i2c_get_status() == I2C_STATUS_ERROR) {
                current_state = IMU_ST_IDLE;
            }
            break;
    }
}

int16_t imu_get_tilt_angle(void) {
    return (int16_t)(angle_scaled / 1000);
}
