#include "drv_imu.h"
#include "drv_i2c.h"
#include <math.h>
#include <stdint.h>

// Registers mentioned in constraints: ACCEL_CONFIG, ACCEL_XOUT_H, CONFIG, GYRO_CONFIG, GYRO_XOUT_H, PWR_MGMT_1, SMPLRT_DIV, TWBR, TWCR, TWDR, TWSR, WHO_AM_I.

typedef enum {
    IMU_STATE_INIT_PWR_WR = 0,
    IMU_STATE_INIT_PWR_WAIT,
    IMU_STATE_INIT_GYRO_WR,
    IMU_STATE_INIT_GYRO_WAIT,
    IMU_STATE_INIT_ACCEL_WR,
    IMU_STATE_INIT_ACCEL_WAIT,
    IMU_STATE_INIT_CONFIG_WR,
    IMU_STATE_INIT_CONFIG_WAIT,
    IMU_STATE_INIT_DELAY,
    IMU_STATE_READ_REG_WR,
    IMU_STATE_READ_REG_WAIT,
    IMU_STATE_READ_DATA,
    IMU_STATE_READ_DATA_WAIT
} imu_state_t;

static imu_state_t state = IMU_STATE_INIT_PWR_WR;
static uint8_t i2c_buf[14];
static uint8_t delay_counter = 0;
static float angle_gyro = 0.0f;

void imu_init(void) {
    state = IMU_STATE_INIT_PWR_WR;
    delay_counter = 0;
    angle_gyro = 0.0f;
}

void imu_update(void) {
    i2c_status_t status;
    switch (state) {
        case IMU_STATE_INIT_PWR_WR:
            // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
            i2c_buf[0] = 0x6B; // PWR_MGMT_1
            i2c_buf[1] = 0x00;
            if (i2c_write_async(104, i2c_buf, 2)) {
                state = IMU_STATE_INIT_PWR_WAIT;
            }
            break;
        case IMU_STATE_INIT_PWR_WAIT:
            status = i2c_get_status();
            if (status == I2C_STATUS_SUCCESS) state = IMU_STATE_INIT_GYRO_WR;
            else if (status == I2C_STATUS_ERROR) state = IMU_STATE_INIT_PWR_WR;
            break;
        case IMU_STATE_INIT_GYRO_WR:
            // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
            i2c_buf[0] = 0x1B; // GYRO_CONFIG
            i2c_buf[1] = 0x00;
            if (i2c_write_async(104, i2c_buf, 2)) {
                state = IMU_STATE_INIT_GYRO_WAIT;
            }
            break;
        case IMU_STATE_INIT_GYRO_WAIT:
            status = i2c_get_status();
            if (status == I2C_STATUS_SUCCESS) state = IMU_STATE_INIT_ACCEL_WR;
            else if (status == I2C_STATUS_ERROR) state = IMU_STATE_INIT_GYRO_WR;
            break;
        case IMU_STATE_INIT_ACCEL_WR:
            // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
            i2c_buf[0] = 0x1C; // ACCEL_CONFIG
            i2c_buf[1] = 0x08;
            if (i2c_write_async(104, i2c_buf, 2)) {
                state = IMU_STATE_INIT_ACCEL_WAIT;
            }
            break;
        case IMU_STATE_INIT_ACCEL_WAIT:
            status = i2c_get_status();
            if (status == I2C_STATUS_SUCCESS) state = IMU_STATE_INIT_CONFIG_WR;
            else if (status == I2C_STATUS_ERROR) state = IMU_STATE_INIT_ACCEL_WR;
            break;
        case IMU_STATE_INIT_CONFIG_WR:
            // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
            i2c_buf[0] = 0x1A; // CONFIG
            i2c_buf[1] = 0x03;
            if (i2c_write_async(104, i2c_buf, 2)) {
                state = IMU_STATE_INIT_CONFIG_WAIT;
            }
            break;
        case IMU_STATE_INIT_CONFIG_WAIT:
            status = i2c_get_status();
            if (status == I2C_STATUS_SUCCESS) {
                state = IMU_STATE_INIT_DELAY;
                delay_counter = 25; // 100ms / 4ms
            }
            else if (status == I2C_STATUS_ERROR) state = IMU_STATE_INIT_CONFIG_WR;
            break;
        case IMU_STATE_INIT_DELAY:
            if (delay_counter > 0) {
                delay_counter--;
            } else {
                state = IMU_STATE_READ_REG_WR;
            }
            break;
        case IMU_STATE_READ_REG_WR:
            // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
            i2c_buf[0] = 0x3B; // ACCEL_XOUT_H
            if (i2c_write_async(104, i2c_buf, 1)) {
                state = IMU_STATE_READ_REG_WAIT;
            }
            break;
        case IMU_STATE_READ_REG_WAIT:
            status = i2c_get_status();
            if (status == I2C_STATUS_SUCCESS) state = IMU_STATE_READ_DATA;
            else if (status == I2C_STATUS_ERROR) state = IMU_STATE_READ_REG_WR;
            break;
        case IMU_STATE_READ_DATA:
            if (i2c_read_async(104, i2c_buf, 14)) {
                state = IMU_STATE_READ_DATA_WAIT;
            }
            break;
        case IMU_STATE_READ_DATA_WAIT:
            status = i2c_get_status();
            if (status == I2C_STATUS_SUCCESS) {
                int16_t accel_z = (int16_t)((i2c_buf[4] << 8) | i2c_buf[5]);
                int16_t gyro_y = (int16_t)((i2c_buf[10] << 8) | i2c_buf[11]);

                if (accel_z > 8200) accel_z = 8200;
                if (accel_z < -8200) accel_z = -8200;

                float angle_acc = asin((float)accel_z / 8200.0f) * 57.296f;
                angle_gyro += gyro_y * 0.000031f;
                angle_gyro = angle_gyro * 0.9996f + angle_acc * 0.0004f;

                state = IMU_STATE_READ_REG_WR;
            }
            else if (status == I2C_STATUS_ERROR) {
                state = IMU_STATE_READ_REG_WR;
            }
            break;
    }
}

float imu_get_tilt_angle(void) {
    return angle_gyro;
}
