def test_imu():
    src_files = ["src/drv_imu.c", "src/drv_i2c.c", "/Users/v/Documents/KTDT/packs/avr/hostmock/eaa_io_space.c"]
    cmd = ["cc", "-std=c11", "-Wall", "-fPIC", "-shared", "-I/Users/v/Documents/KTDT/packs/avr/hostmock", "-Isrc"] + src_files + ["-o", "libdrv_imu.so"]
    result = subprocess.run(cmd, capture_output=True, text=True)
    if result.returncode != 0:
        print(result.stderr)
        pytest.fail("Compilation failed")

    lib = ctypes.CDLL("./libdrv_imu.so")

    lib.imu_init.argtypes = []
    lib.imu_init.restype = None
    lib.imu_update.argtypes = []
    lib.imu_update.restype = None
    lib.imu_get_tilt_angle.argtypes = []
    lib.imu_get_tilt_angle.restype = ctypes.c_float
    lib.i2c_init.argtypes = []
    lib.i2c_init.restype = None

    class TWISimulator:
        def __init__(self, lib):
            self.lib = lib
            self.TWCR = ctypes.c_uint8.in_dll(lib, "TWCR")
            self.TWSR = ctypes.c_uint8.in_dll(lib, "TWSR")
            self.TWDR = ctypes.c_uint8.in_dll(lib, "TWDR")
            self.state = 'IDLE'
            self.written_data = []
            self.read_data = []
            self.error_inject = False

        def run_until_idle(self):
            for _ in range(100):
                if not (self.TWCR.value & 0x80):
                    break

                twcr = self.TWCR.value

                if twcr & 0x20: # TWSTA
                    if self.state == 'IDLE':
                        self.TWSR.value = 0x08 # START
                    else:
                        self.TWSR.value = 0x10 # REP_START
                    self.state = 'START'
                elif twcr & 0x10: # TWSTO
                    self.TWCR.value &= ~0x90 # Clear TWINT and TWSTO
                    self.state = 'IDLE'
                    break
                else:
                    if self.state == 'START':
                        sla = self.TWDR.value
                        if self.error_inject:
                            self.TWSR.value = 0x20 # SLA+W NACK
                        else:
                            if sla & 1:
                                self.TWSR.value = 0x40 # SLA+R ACK
                                self.state = 'MR_DATA'
                            else:
                                self.TWSR.value = 0x18 # SLA+W ACK
                                self.state = 'MT_DATA'
                    elif self.state == 'MT_DATA':
                        if self.error_inject:
                            self.TWSR.value = 0x30 # DATA NACK
                        else:
                            self.written_data.append(self.TWDR.value)
                            self.TWSR.value = 0x28 # DATA ACK
                    elif self.state == 'MR_DATA':
                        if self.read_data:
                            self.TWDR.value = self.read_data.pop(0)
                        else:
                            self.TWDR.value = 0

                        if twcr & 0x40: # TWEA
                            self.TWSR.value = 0x50 # DATA ACK
                        else:
                            self.TWSR.value = 0x58 # DATA NACK

                self.lib.TWI_vect_fn()

    lib.i2c_init()
    twi = TWISimulator(lib)

    lib.imu_init()

    # 1. PWR_MGMT_1
    lib.imu_update()
    twi.run_until_idle()
    assert twi.written_data == [0x6B, 0x00]
    twi.written_data.clear()

    # 2. GYRO_CONFIG
    lib.imu_update()
    twi.run_until_idle()
    assert twi.written_data == [0x1B, 0x00]
    twi.written_data.clear()

    # 3. ACCEL_CONFIG
    lib.imu_update()
    twi.run_until_idle()
    assert twi.written_data == [0x1C, 0x08]
    twi.written_data.clear()

    # 4. CONFIG
    lib.imu_update()
    twi.run_until_idle()
    assert twi.written_data == [0x1A, 0x03]
    twi.written_data.clear()

    # Delay
    lib.imu_update()
    for _ in range(25):
        lib.imu_update()

    # Read Reg
    lib.imu_update()
    twi.run_until_idle()
    assert twi.written_data == [0x3B]
    twi.written_data.clear()

    # Read Data
    lib.imu_update()
    mock_data = [0]*14
    mock_data[4] = (4100 >> 8) & 0xFF
    mock_data[5] = 4100 & 0xFF
    mock_data[10] = (131 >> 8) & 0xFF
    mock_data[11] = 131 & 0xFF
    twi.read_data = mock_data.copy()
    twi.run_until_idle()

    lib.imu_update()

    angle = lib.imu_get_tilt_angle()
    assert abs(angle - 0.016059) < 0.001

    # Test bus error
    lib.imu_update()
    twi.error_inject = True
    twi.run_until_idle()

    lib.imu_update()
    twi.error_inject = False
    twi.run_until_idle()
    assert twi.written_data == [0x3B]

    angle2 = lib.imu_get_tilt_angle()
    assert angle2 == angle

if __name__ == "__main__":
    test_imu()
