#include "drv_imu.h"
#include "drv_i2c.h"
#include <math.h>
#include <stddef.h>

#define MPU6050_ADDR 0x68

// ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
#define REG_SMPLRT_DIV 0x19
#define REG_CONFIG 0x1A
#define REG_PWR_MGMT_1 0x6B
#define REG_WHO_AM_I 0x75

// ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
#define REG_GYRO_CONFIG 0x1B
#define REG_ACCEL_CONFIG 0x1C
#define REG_ACCEL_XOUT_H 0x3B
#define REG_GYRO_XOUT_H 0x43

// ref: ds-021, ATmega328P datasheet rev. DS40002061B, tr.222-224
// TWBR, TWCR, TWSR, TWDR are configured and used in drv_i2c module.

typedef enum {
    IMU_STATE_INIT_WHOAMI_REG = 0,
    IMU_STATE_INIT_WHOAMI_REG_WAIT,
    IMU_STATE_INIT_WHOAMI_DATA,
    IMU_STATE_INIT_WHOAMI_DATA_WAIT,
    IMU_STATE_INIT_PWR,
    IMU_STATE_INIT_PWR_WAIT,
    IMU_STATE_INIT_SMPLRT,
    IMU_STATE_INIT_SMPLRT_WAIT,
    IMU_STATE_INIT_CONFIG,
    IMU_STATE_INIT_CONFIG_WAIT,
    IMU_STATE_INIT_GYRO,
    IMU_STATE_INIT_GYRO_WAIT,
    IMU_STATE_INIT_ACCEL,
    IMU_STATE_INIT_ACCEL_WAIT,
    IMU_STATE_IDLE,
    IMU_STATE_READ_REG,
    IMU_STATE_READ_REG_WAIT,
    IMU_STATE_READ_DATA,
    IMU_STATE_READ_DATA_WAIT
} imu_state_t;

static imu_state_t imu_state = IMU_STATE_INIT_WHOAMI_REG;
static uint8_t i2c_tx_buf[2];
static uint8_t i2c_rx_buf[14];
static float current_angle = 0.0f;

void imu_init(void) {
    i2c_init();
    imu_state = IMU_STATE_INIT_WHOAMI_REG;
    current_angle = 0.0f;
}

void imu_update(void) {
    i2c_status_t status = i2c_get_status();

    switch (imu_state) {
        case IMU_STATE_INIT_WHOAMI_REG:
            if (status == I2C_STATUS_IDLE || status == I2C_STATUS_SUCCESS || status == I2C_STATUS_ERROR) {
                i2c_tx_buf[0] = REG_WHO_AM_I;
                if (i2c_write_async(MPU6050_ADDR, i2c_tx_buf, 1)) {
                    imu_state = IMU_STATE_INIT_WHOAMI_REG_WAIT;
                }
            }
            break;

        case IMU_STATE_INIT_WHOAMI_REG_WAIT:
            if (status == I2C_STATUS_SUCCESS) imu_state = IMU_STATE_INIT_WHOAMI_DATA;
            else if (status == I2C_STATUS_ERROR) imu_state = IMU_STATE_INIT_WHOAMI_REG;
            break;

        case IMU_STATE_INIT_WHOAMI_DATA:
            if (status == I2C_STATUS_IDLE || status == I2C_STATUS_SUCCESS) {
                if (i2c_read_async(MPU6050_ADDR, i2c_rx_buf, 1)) {
                    imu_state = IMU_STATE_INIT_WHOAMI_DATA_WAIT;
                }
            }
            break;

        case IMU_STATE_INIT_WHOAMI_DATA_WAIT:
            if (status == I2C_STATUS_SUCCESS) {
                imu_state = IMU_STATE_INIT_PWR;
            } else if (status == I2C_STATUS_ERROR) {
                imu_state = IMU_STATE_INIT_WHOAMI_REG;
            }
            break;

        case IMU_STATE_INIT_PWR:
            if (status == I2C_STATUS_IDLE || status == I2C_STATUS_SUCCESS) {
                i2c_tx_buf[0] = REG_PWR_MGMT_1;
                i2c_tx_buf[1] = 0x00;
                if (i2c_write_async(MPU6050_ADDR, i2c_tx_buf, 2)) {
                    imu_state = IMU_STATE_INIT_PWR_WAIT;
                }
            }
            break;

        case IMU_STATE_INIT_PWR_WAIT:
            if (status == I2C_STATUS_SUCCESS) imu_state = IMU_STATE_INIT_SMPLRT;
            else if (status == I2C_STATUS_ERROR) imu_state = IMU_STATE_INIT_PWR;
            break;

        case IMU_STATE_INIT_SMPLRT:
            if (status == I2C_STATUS_IDLE || status == I2C_STATUS_SUCCESS) {
                i2c_tx_buf[0] = REG_SMPLRT_DIV;
                i2c_tx_buf[1] = 0x00;
                if (i2c_write_async(MPU6050_ADDR, i2c_tx_buf, 2)) {
                    imu_state = IMU_STATE_INIT_SMPLRT_WAIT;
                }
            }
            break;

        case IMU_STATE_INIT_SMPLRT_WAIT:
            if (status == I2C_STATUS_SUCCESS) imu_state = IMU_STATE_INIT_CONFIG;
            else if (status == I2C_STATUS_ERROR) imu_state = IMU_STATE_INIT_SMPLRT;
            break;

        case IMU_STATE_INIT_CONFIG:
            if (status == I2C_STATUS_IDLE || status == I2C_STATUS_SUCCESS) {
                i2c_tx_buf[0] = REG_CONFIG;
                i2c_tx_buf[1] = 0x03;
                if (i2c_write_async(MPU6050_ADDR, i2c_tx_buf, 2)) {
                    imu_state = IMU_STATE_INIT_CONFIG_WAIT;
                }
            }
            break;

        case IMU_STATE_INIT_CONFIG_WAIT:
            if (status == I2C_STATUS_SUCCESS) imu_state = IMU_STATE_INIT_GYRO;
            else if (status == I2C_STATUS_ERROR) imu_state = IMU_STATE_INIT_CONFIG;
            break;

        case IMU_STATE_INIT_GYRO:
            if (status == I2C_STATUS_IDLE || status == I2C_STATUS_SUCCESS) {
                i2c_tx_buf[0] = REG_GYRO_CONFIG;
                i2c_tx_buf[1] = 0x00;
                if (i2c_write_async(MPU6050_ADDR, i2c_tx_buf, 2)) {
                    imu_state = IMU_STATE_INIT_GYRO_WAIT;
                }
            }
            break;

        case IMU_STATE_INIT_GYRO_WAIT:
            if (status == I2C_STATUS_SUCCESS) imu_state = IMU_STATE_INIT_ACCEL;
            else if (status == I2C_STATUS_ERROR) imu_state = IMU_STATE_INIT_GYRO;
            break;

        case IMU_STATE_INIT_ACCEL:
            if (status == I2C_STATUS_IDLE || status == I2C_STATUS_SUCCESS) {
                i2c_tx_buf[0] = REG_ACCEL_CONFIG;
                i2c_tx_buf[1] = 0x08;
                if (i2c_write_async(MPU6050_ADDR, i2c_tx_buf, 2)) {
                    imu_state = IMU_STATE_INIT_ACCEL_WAIT;
                }
            }
            break;

        case IMU_STATE_INIT_ACCEL_WAIT:
            if (status == I2C_STATUS_SUCCESS) imu_state = IMU_STATE_IDLE;
            else if (status == I2C_STATUS_ERROR) imu_state = IMU_STATE_INIT_ACCEL;
            break;

        case IMU_STATE_IDLE:
            imu_state = IMU_STATE_READ_REG;
            break;

        case IMU_STATE_READ_REG:
            if (status == I2C_STATUS_IDLE || status == I2C_STATUS_SUCCESS || status == I2C_STATUS_ERROR) {
                i2c_tx_buf[0] = REG_ACCEL_XOUT_H;
                if (i2c_write_async(MPU6050_ADDR, i2c_tx_buf, 1)) {
                    imu_state = IMU_STATE_READ_REG_WAIT;
                }
            }
            break;

        case IMU_STATE_READ_REG_WAIT:
            if (status == I2C_STATUS_SUCCESS) {
                imu_state = IMU_STATE_READ_DATA;
            } else if (status == I2C_STATUS_ERROR) {
                imu_state = IMU_STATE_IDLE;
            }
            break;

        case IMU_STATE_READ_DATA:
            if (status == I2C_STATUS_IDLE || status == I2C_STATUS_SUCCESS) {
                if (i2c_read_async(MPU6050_ADDR, i2c_rx_buf, 14)) {
                    imu_state = IMU_STATE_READ_DATA_WAIT;
                }
            }
            break;

        case IMU_STATE_READ_DATA_WAIT:
            if (status == I2C_STATUS_SUCCESS) {
                int16_t accel_z = (int16_t)((i2c_rx_buf[4] << 8) | i2c_rx_buf[5]);
                int16_t gyro_y_raw = (int16_t)((i2c_rx_buf[10] << 8) | i2c_rx_buf[11]);

                if (accel_z > 8200) accel_z = 8200;
                if (accel_z < -8200) accel_z = -8200;

                float angle_acc = asin((float)accel_z / 8200.0f) * 57.296f;
                current_angle += gyro_y_raw * 0.000031f;
                current_angle = current_angle * 0.9996f + angle_acc * 0.0004f;

                imu_state = IMU_STATE_IDLE;
            } else if (status == I2C_STATUS_ERROR) {
                imu_state = IMU_STATE_IDLE;
            }
            break;
    }
}

float imu_get_tilt_angle(void) {
    return current_angle;
}
