import math

def setup_module():
    if not os.path.exists("src/drv_i2c.c"):
        os.makedirs("src", exist_ok=True)
        with open("src/drv_i2c.c", "w") as f:
            f.write("""
            #include "drv_i2c.h"
            #include <avr/io.h>
            #include <avr/interrupt.h>
            static i2c_status_t st = I2C_STATUS_IDLE;
            static const uint8_t *tx_buf;
            static uint8_t *rx_buf;
            static uint8_t buf_len;
            static uint8_t buf_idx;
            static uint8_t dev_addr;
            static bool is_read;

            void i2c_init(void) { TWCR = (1<<TWEN); }
            bool i2c_write_async(uint8_t addr, const uint8_t *data, uint8_t len) {
                if (st == I2C_STATUS_BUSY) return false;
                dev_addr = addr; tx_buf = data; buf_len = len; buf_idx = 0; is_read = false;
                st = I2C_STATUS_BUSY;
                TWCR = (1<<TWINT) | (1<<TWSTA) | (1<<TWEN) | (1<<TWIE);
                return true;
            }
            bool i2c_read_async(uint8_t addr, uint8_t *data, uint8_t len) {
                if (st == I2C_STATUS_BUSY) return false;
                dev_addr = addr; rx_buf = data; buf_len = len; buf_idx = 0; is_read = true;
                st = I2C_STATUS_BUSY;
                TWCR = (1<<TWINT) | (1<<TWSTA) | (1<<TWEN) | (1<<TWIE);
                return true;
            }
            i2c_status_t i2c_get_status(void) { return st; }

            ISR(TWI_vect) {
                uint8_t status = TWSR & 0xF8;
                switch(status) {
                    case 0x08:
                    case 0x10:
                        TWDR = (dev_addr << 1) | (is_read ? 1 : 0);
                        TWCR = (1<<TWINT) | (1<<TWEN) | (1<<TWIE);
                        break;
                    case 0x18:
                    case 0x28:
                        if (buf_idx < buf_len) {
                            TWDR = tx_buf[buf_idx++];
                            TWCR = (1<<TWINT) | (1<<TWEN) | (1<<TWIE);
                        } else {
                            TWCR = (1<<TWINT) | (1<<TWSTO) | (1<<TWEN);
                            st = I2C_STATUS_SUCCESS;
                        }
                        break;
                    case 0x40:
                        if (buf_len > 1) TWCR = (1<<TWINT) | (1<<TWEN) | (1<<TWIE) | (1<<TWEA);
                        else TWCR = (1<<TWINT) | (1<<TWEN) | (1<<TWIE);
                        break;
                    case 0x50:
                        rx_buf[buf_idx++] = TWDR;
                        if (buf_idx < buf_len - 1) TWCR = (1<<TWINT) | (1<<TWEN) | (1<<TWIE) | (1<<TWEA);
                        else TWCR = (1<<TWINT) | (1<<TWEN) | (1<<TWIE);
                        break;
                    case 0x58:
                        rx_buf[buf_idx++] = TWDR;
                        TWCR = (1<<TWINT) | (1<<TWSTO) | (1<<TWEN);
                        st = I2C_STATUS_SUCCESS;
                        break;
                    default:
                        TWCR = (1<<TWINT) | (1<<TWSTO) | (1<<TWEN);
                        st = I2C_STATUS_ERROR;
                }
            }
            """)

    if not os.path.exists("src/drv_i2c.h"):
