@pytest.fixture
def lib():
    l = ctypes.CDLL("./libdrv_imu.so")
    l.imu_init.argtypes = []
    l.imu_init.restype = None
    l.imu_update.argtypes = []
    l.imu_update.restype = None
    l.imu_get_tilt_angle.argtypes = []
    l.imu_get_tilt_angle.restype = ctypes.c_float
    l.i2c_get_status.argtypes = []
    l.i2c_get_status.restype = ctypes.c_int
    l.TWI_vect_fn.argtypes = []
    l.TWI_vect_fn.restype = None
    return l

def simulate_i2c_hw(lib, rx_data=None):
    if rx_data is None:
        rx_data = []
    TWCR = ctypes.c_uint8.in_dll(lib, "TWCR")
    TWSR = ctypes.c_uint8.in_dll(lib, "TWSR")
    TWDR = ctypes.c_uint8.in_dll(lib, "TWDR")

    rx_idx = 0
    for _ in range(100):
        if lib.i2c_get_status() != 1: # Not BUSY
            break

        if TWCR.value & 0x20: # START
            TWCR.value &= ~0x20
            TWSR.value = 0x08
            lib.TWI_vect_fn()
        elif TWCR.value & 0x10: # STOP
            TWCR.value &= ~0x10
            break
        else:
            if TWSR.value in (0x08, 0x10):
                sla = TWDR.value
                if sla & 1:
                    TWSR.value = 0x40
                else:
                    TWSR.value = 0x18
                lib.TWI_vect_fn()
            elif TWSR.value == 0x18:
                TWSR.value = 0x28
                lib.TWI_vect_fn()
            elif TWSR.value == 0x28:
                TWSR.value = 0x28
                lib.TWI_vect_fn()
            elif TWSR.value == 0x40:
                if rx_idx < len(rx_data):
                    TWDR.value = rx_data[rx_idx]
                    rx_idx += 1
                else:
                    TWDR.value = 0
                TWSR.value = 0x50 if (TWCR.value & 0x40) else 0x58
                lib.TWI_vect_fn()
            elif TWSR.value == 0x50:
                if rx_idx < len(rx_data):
                    TWDR.value = rx_data[rx_idx]
                    rx_idx += 1
                else:
                    TWDR.value = 0
                TWSR.value = 0x50 if (TWCR.value & 0x40) else 0x58
                lib.TWI_vect_fn()

def test_imu_init_sequence(lib):
    lib.imu_init()

    # 1. WHOAMI_REG
    lib.imu_update(); simulate_i2c_hw(lib)
    # 2. WHOAMI_DATA
    lib.imu_update(); simulate_i2c_hw(lib, [0x68])
    # 3. PWR
    lib.imu_update(); simulate_i2c_hw(lib)
    # 4. SMPLRT
    lib.imu_update(); simulate_i2c_hw(lib)
    # 5. CONFIG
    lib.imu_update(); simulate_i2c_hw(lib)
    # 6. GYRO
    lib.imu_update(); simulate_i2c_hw(lib)
    # 7. ACCEL
    lib.imu_update(); simulate_i2c_hw(lib)

    # Now should be in IDLE state
    lib.imu_update() # READ_REG
    simulate_i2c_hw(lib)

    # READ_DATA
    lib.imu_update()
    simulate_i2c_hw(lib, [0]*14)

    # Process data
    lib.imu_update()

    angle = lib.imu_get_tilt_angle()
    assert angle == 0.0

def test_imu_calculation(lib):
    lib.imu_init()

    # Skip init states
    lib.imu_update(); simulate_i2c_hw(lib)
    lib.imu_update(); simulate_i2c_hw(lib, [0x68])
    lib.imu_update(); simulate_i2c_hw(lib)
    lib.imu_update(); simulate_i2c_hw(lib)
    lib.imu_update(); simulate_i2c_hw(lib)
    lib.imu_update(); simulate_i2c_hw(lib)
    lib.imu_update(); simulate_i2c_hw(lib)

    # READ_REG
    lib.imu_update()
    simulate_i2c_hw(lib)

    # READ_DATA
    lib.imu_update()

    # accel_z = 4100, gyro_y = 1000
    rx_data = [0]*14
    rx_data[4] = (4100 >> 8) & 0xFF
    rx_data[5] = 4100 & 0xFF
    rx_data[10] = (1000 >> 8) & 0xFF
    rx_data[11] = 1000 & 0xFF

    simulate_i2c_hw(lib, rx_data)

    # Process data
    lib.imu_update()

    angle = lib.imu_get_tilt_angle()

    expected_acc = math.asin(4100 / 8200.0) * 57.296
    expected_gyro = 1000 * 0.000031
    expected_angle = expected_gyro * 0.9996 + expected_acc * 0.0004

    assert abs(angle - expected_angle) < 0.001

def test_imu_error_keeps_angle(lib):
    lib.imu_init()

    # Skip init states
    lib.imu_update(); simulate_i2c_hw(lib)
    lib.imu_update(); simulate_i2c_hw(lib, [0x68])
    lib.imu_update(); simulate_i2c_hw(lib)
