#include "drv_imu.h"
#include "drv_i2c.h"
#include <avr/io.h>
#include <math.h>

// ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
// ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
// ref: ds-021, ATmega328P datasheet rev. DS40002061B, tr.222-224

typedef enum {
    IMU_STATE_INIT_WHOAMI_REQ = 0,
    IMU_STATE_INIT_WHOAMI_WAIT,
    IMU_STATE_INIT_WHOAMI_READ_WAIT,
    IMU_STATE_INIT_PWR,
    IMU_STATE_INIT_PWR_WAIT,
    IMU_STATE_INIT_SMPLRT,
    IMU_STATE_INIT_SMPLRT_WAIT,
    IMU_STATE_INIT_GYRO,
    IMU_STATE_INIT_GYRO_WAIT,
    IMU_STATE_INIT_ACCEL,
    IMU_STATE_INIT_ACCEL_WAIT,
    IMU_STATE_INIT_CONFIG,
    IMU_STATE_INIT_CONFIG_WAIT,
    IMU_STATE_IDLE,
    IMU_STATE_READ_REQ,
    IMU_STATE_READ_WAIT
} imu_state_t;

static imu_state_t state = IMU_STATE_INIT_WHOAMI_REQ;
static uint8_t tx_buf[2];
static uint8_t rx_buf[14];
static float current_angle = 0.0f;

void imu_init(void) {
    // ref: ds-021, ATmega328P datasheet rev. DS40002061B, tr.222-224
    TWBR = 12;
    TWSR = 0x00;
    TWCR = (1 << 2);

    i2c_init();
    state = IMU_STATE_INIT_WHOAMI_REQ;
    current_angle = 0.0f;
}

void imu_update(void) {
    i2c_status_t status;
    switch (state) {
        case IMU_STATE_INIT_WHOAMI_REQ:
            tx_buf[0] = 0x75; // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
            if (i2c_write_async(0x68, tx_buf, 1)) {
                state = IMU_STATE_INIT_WHOAMI_WAIT;
            }
            break;
        case IMU_STATE_INIT_WHOAMI_WAIT:
            status = i2c_get_status();
            if (status == I2C_STATUS_SUCCESS) {
                if (i2c_read_async(0x68, rx_buf, 1)) {
                    state = IMU_STATE_INIT_WHOAMI_READ_WAIT;
                }
            } else if (status == I2C_STATUS_ERROR) {
                state = IMU_STATE_INIT_WHOAMI_REQ;
            }
            break;
        case IMU_STATE_INIT_WHOAMI_READ_WAIT:
            status = i2c_get_status();
            if (status == I2C_STATUS_SUCCESS) {
                if (rx_buf[0] == 0x68) {
                    state = IMU_STATE_INIT_PWR;
                } else {
                    state = IMU_STATE_INIT_WHOAMI_REQ;
                }
            } else if (status == I2C_STATUS_ERROR) {
                state = IMU_STATE_INIT_WHOAMI_REQ;
            }
            break;
        case IMU_STATE_INIT_PWR:
            tx_buf[0] = 0x6B; // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
            tx_buf[1] = 0x00;
            if (i2c_write_async(0x68, tx_buf, 2)) {
                state = IMU_STATE_INIT_PWR_WAIT;
            }
            break;
        case IMU_STATE_INIT_PWR_WAIT:
            status = i2c_get_status();
            if (status == I2C_STATUS_SUCCESS) {
                state = IMU_STATE_INIT_SMPLRT;
            } else if (status == I2C_STATUS_ERROR) {
                state = IMU_STATE_INIT_PWR;
            }
            break;
        case IMU_STATE_INIT_SMPLRT:
            tx_buf[0] = 0x19; // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
            tx_buf[1] = 0x00;
            if (i2c_write_async(0x68, tx_buf, 2)) {
                state = IMU_STATE_INIT_SMPLRT_WAIT;
            }
            break;
        case IMU_STATE_INIT_SMPLRT_WAIT:
            status = i2c_get_status();
            if (status == I2C_STATUS_SUCCESS) {
                state = IMU_STATE_INIT_GYRO;
            } else if (status == I2C_STATUS_ERROR) {
                state = IMU_STATE_INIT_SMPLRT;
            }
            break;
        case IMU_STATE_INIT_GYRO:
            tx_buf[0] = 0x1B; // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
            tx_buf[1] = 0x00;
            if (i2c_write_async(0x68, tx_buf, 2)) {
                state = IMU_STATE_INIT_GYRO_WAIT;
            }
            break;
        case IMU_STATE_INIT_GYRO_WAIT:
            status = i2c_get_status();
            if (status == I2C_STATUS_SUCCESS) {
                state = IMU_STATE_INIT_ACCEL;
            } else if (status == I2C_STATUS_ERROR) {
                state = IMU_STATE_INIT_GYRO;
            }
            break;
        case IMU_STATE_INIT_ACCEL:
            tx_buf[0] = 0x1C; // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
            tx_buf[1] = 0x08;
            if (i2c_write_async(0x68, tx_buf, 2)) {
                state = IMU_STATE_INIT_ACCEL_WAIT;
            }
            break;
        case IMU_STATE_INIT_ACCEL_WAIT:
            status = i2c_get_status();
            if (status == I2C_STATUS_SUCCESS) {
                state = IMU_STATE_INIT_CONFIG;
            } else if (status == I2C_STATUS_ERROR) {
                state = IMU_STATE_INIT_ACCEL;
            }
            break;
        case IMU_STATE_INIT_CONFIG:
            tx_buf[0] = 0x1A; // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
            tx_buf[1] = 0x03;
            if (i2c_write_async(0x68, tx_buf, 2)) {
                state = IMU_STATE_INIT_CONFIG_WAIT;
            }
            break;
        case IMU_STATE_INIT_CONFIG_WAIT:
            status = i2c_get_status();
            if (status == I2C_STATUS_SUCCESS) {
                state = IMU_STATE_IDLE;
            } else if (status == I2C_STATUS_ERROR) {
                state = IMU_STATE_INIT_CONFIG;
            }
            break;
        case IMU_STATE_IDLE:
            tx_buf[0] = 0x3B; // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
            if (i2c_write_async(0x68, tx_buf, 1)) {
                state = IMU_STATE_READ_REQ;
            }
            break;
        case IMU_STATE_READ_REQ:
            status = i2c_get_status();
            if (status == I2C_STATUS_SUCCESS) {
                if (i2c_read_async(0x68, rx_buf, 14)) {
                    state = IMU_STATE_READ_WAIT;
                }
            } else if (status == I2C_STATUS_ERROR) {
                state = IMU_STATE_IDLE;
            }
            break;
        case IMU_STATE_READ_WAIT:
            status = i2c_get_status();
            if (status == I2C_STATUS_SUCCESS) {
                int16_t accel_z = (int16_t)((rx_buf[4] << 8) | rx_buf[5]);
                int16_t gyro_y_raw = (int16_t)((rx_buf[10] << 8) | rx_buf[11]);

                if (accel_z > 8200) accel_z = 8200;
                if (accel_z < -8200) accel_z = -8200;

                float angle_acc = asin((float)accel_z / 8200.0f) * 57.296f;
                current_angle += gyro_y_raw * 0.000031f;
                current_angle = current_angle * 0.9996f + angle_acc * 0.0004f;

                state = IMU_STATE_IDLE;
            } else if (status == I2C_STATUS_ERROR) {
                state = IMU_STATE_IDLE;
            }
            break;
        default:
            break;
    }
}

float imu_get_tilt_angle(void) {
    return current_angle;
}
