import subprocess
import ctypes
import sys

def build_lib():
    src_files = ["src/drv_imu.c", "src/drv_i2c.c", "/Users/v/Documents/KTDT/packs/avr/hostmock/eaa_io_space.c"]
    cmd = ["cc", "-std=c11", "-Wall", "-fPIC", "-shared", "-I/Users/v/Documents/KTDT/packs/avr/hostmock"] + src_files + ["-o", "libdrv_imu.so", "-lm"]
    result = subprocess.run(cmd, capture_output=True, text=True)
    if result.returncode != 0:
        print("Compilation failed:")
        print(result.stderr)
        sys.exit(1)

def run_twi(lib, slave_mem, force_error=False):
    TWCR = ctypes.c_uint8.in_dll(lib, "TWCR")
    TWSR = ctypes.c_uint8.in_dll(lib, "TWSR")
    TWDR = ctypes.c_uint8.in_dll(lib, "TWDR")

    state = "IDLE"
    current_reg = 0

    for _ in range(1000):
        twcr = TWCR.value
        if not (twcr & 0x80):
            if twcr & 0x20:
                if state == "IDLE":
                    TWSR.value = 0x08
                else:
                    TWSR.value = 0x10
                TWCR.value = (twcr & ~0x20) | 0x80
                state = "IDLE"
            elif twcr & 0x10:
                TWCR.value = (twcr & ~0x10) | 0x80
                state = "IDLE"
                continue
            else:
                if state == "IDLE":
                    sla = TWDR.value
                    if force_error:
                        TWSR.value = 0x20 if sla == 0xD0 else 0x48
                    else:
                        if sla == 0xD0:
                            TWSR.value = 0x18
                            state = "RECV_REG"
                        elif sla == 0xD1:
                            TWSR.value = 0x40
                            state = "SEND_DATA"
                        else:
                            TWSR.value = 0x20
                    TWCR.value |= 0x80
                elif state == "RECV_REG":
                    current_reg = TWDR.value
                    TWSR.value = 0x28
                    state = "RECV_DATA"
                    TWCR.value |= 0x80
                elif state == "RECV_DATA":
                    slave_mem[current_reg] = TWDR.value
                    current_reg = (current_reg + 1) & 0xFF
                    TWSR.value = 0x28
                    TWCR.value |= 0x80
                elif state == "SEND_DATA":
                    TWDR.value = slave_mem[current_reg]
                    current_reg = (current_reg + 1) & 0xFF
                    if twcr & 0x40:
                        TWSR.value = 0x50
                    else:
                        TWSR.value = 0x58
                    TWCR.value |= 0x80

            if TWCR.value & 0x01:
                lib.TWI_vect_fn()
        else:
            break

def test_imu():
    build_lib()
    lib = ctypes.CDLL("./libdrv_imu.so")

    lib.imu_init.argtypes = []
    lib.imu_init.restype = None
    lib.imu_update.argtypes = []
    lib.imu_update.restype = None
    lib.imu_get_tilt_angle.argtypes = []
    lib.imu_get_tilt_angle.restype = ctypes.c_float

    slave_mem = [0] * 256
    slave_mem[0x75] = 0x68 # WHO_AM_I

    lib.imu_init()

    # Run init sequence
    for _ in range(30):
        lib.imu_update()
        run_twi(lib, slave_mem)

    assert slave_mem[0x6B] == 0x00, "PWR_MGMT_1 not configured correctly"
    assert slave_mem[0x1B] == 0x00, "GYRO_CONFIG not configured correctly"
    assert slave_mem[0x1C] == 0x08, "ACCEL_CONFIG not configured correctly"
    assert slave_mem[0x1A] == 0x03, "CONFIG not configured correctly"

    # Test positive angle
    accel_z = 4100
    gyro_y = 1000
    slave_mem[0x3F] = (accel_z >> 8) & 0xFF
    slave_mem[0x40] = accel_z & 0xFF
    slave_mem[0x45] = (gyro_y >> 8) & 0xFF
    slave_mem[0x46] = gyro_y & 0xFF

    lib.imu_update()
    run_twi(lib, slave_mem)
    lib.imu_update()
    run_twi(lib, slave_mem)
    lib.imu_update()

    angle1 = lib.imu_get_tilt_angle()
    expected_angle1 = (1000 * 0.000031) * 0.9996 + (30.0) * 0.0004
    assert abs(angle1 - expected_angle1) < 0.5, f"Angle mismatch: {angle1} vs {expected_angle1}"

    # Test error handling
    lib.imu_update()
    run_twi(lib, slave_mem, force_error=True)
    lib.imu_update()
    angle_err = lib.imu_get_tilt_angle()
    assert angle_err == angle1, "Angle reset to 0 on error!"

    # Test negative angle
    accel_z_neg = -4100 & 0xFFFF
    slave_mem[0x3F] = (accel_z_neg >> 8) & 0xFF
    slave_mem[0x40] = accel_z_neg & 0xFF
    slave_mem[0x45] = 0
    slave_mem[0x46] = 0

    lib.imu_update()
    run_twi(lib, slave_mem)
    lib.imu_update()
    run_twi(lib, slave_mem)
    lib.imu_update()

    angle2 = lib.imu_get_tilt_angle()
    assert angle2 < angle1, "Negative accel should decrease angle"

    print("All tests passed!")

if __name__ == "__main__":
    test_imu()
