#include "drv_i2c.h"
#include <math.h>
#include <stdint.h>
#include <stdbool.h>

typedef enum {
    IMU_STATE_INIT_PWR = 0,
    IMU_STATE_WAIT_PWR,
    IMU_STATE_INIT_GYRO,
    IMU_STATE_WAIT_GYRO,
    IMU_STATE_INIT_ACCEL,
    IMU_STATE_WAIT_ACCEL,
    IMU_STATE_INIT_CONFIG,
    IMU_STATE_WAIT_CONFIG,
    IMU_STATE_READY,
    IMU_STATE_WAIT_REG_ADDR,
    IMU_STATE_READING
} imu_state_t;

static imu_state_t state = IMU_STATE_INIT_PWR;
static uint8_t i2c_buf[14];
static float angle_gyro = 0.0f;

void imu_init(void) {
    state = IMU_STATE_INIT_PWR;
    angle_gyro = 0.0f;
}

void imu_update(void) {
    i2c_status_t status;
    switch (state) {
        case IMU_STATE_INIT_PWR:
            i2c_buf[0] = 0x6B;
            i2c_buf[1] = 0x00; // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
            if (i2c_write_async(0x68, i2c_buf, 2)) {
                state = IMU_STATE_WAIT_PWR;
            }
            break;
        case IMU_STATE_WAIT_PWR:
            status = i2c_get_status();
            if (status == I2C_STATUS_SUCCESS) {
                state = IMU_STATE_INIT_GYRO;
            } else if (status == I2C_STATUS_ERROR) {
                state = IMU_STATE_INIT_PWR;
            }
            break;
        case IMU_STATE_INIT_GYRO:
            i2c_buf[0] = 0x1B;
            i2c_buf[1] = 0x00; // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
            if (i2c_write_async(0x68, i2c_buf, 2)) {
                state = IMU_STATE_WAIT_GYRO;
            }
            break;
        case IMU_STATE_WAIT_GYRO:
            status = i2c_get_status();
            if (status == I2C_STATUS_SUCCESS) {
                state = IMU_STATE_INIT_ACCEL;
            } else if (status == I2C_STATUS_ERROR) {
                state = IMU_STATE_INIT_GYRO;
            }
            break;
        case IMU_STATE_INIT_ACCEL:
            i2c_buf[0] = 0x1C;
            i2c_buf[1] = 0x08; // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
            if (i2c_write_async(0x68, i2c_buf, 2)) {
                state = IMU_STATE_WAIT_ACCEL;
            }
            break;
        case IMU_STATE_WAIT_ACCEL:
            status = i2c_get_status();
            if (status == I2C_STATUS_SUCCESS) {
                state = IMU_STATE_INIT_CONFIG;
            } else if (status == I2C_STATUS_ERROR) {
                state = IMU_STATE_INIT_ACCEL;
            }
            break;
        case IMU_STATE_INIT_CONFIG:
            i2c_buf[0] = 0x1A;
            i2c_buf[1] = 0x03; // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
            if (i2c_write_async(0x68, i2c_buf, 2)) {
                state = IMU_STATE_WAIT_CONFIG;
            }
            break;
        case IMU_STATE_WAIT_CONFIG:
            status = i2c_get_status();
            if (status == I2C_STATUS_SUCCESS) {
                state = IMU_STATE_READY;
            } else if (status == I2C_STATUS_ERROR) {
                state = IMU_STATE_INIT_CONFIG;
            }
            break;
        case IMU_STATE_READY:
            i2c_buf[0] = 0x3B;
            if (i2c_write_async(0x68, i2c_buf, 1)) {
                state = IMU_STATE_WAIT_REG_ADDR;
            }
            break;
        case IMU_STATE_WAIT_REG_ADDR:
            status = i2c_get_status();
            if (status == I2C_STATUS_SUCCESS) {
                if (i2c_read_async(0x68, i2c_buf, 14)) {
                    state = IMU_STATE_READING;
                }
            } else if (status == I2C_STATUS_ERROR) {
                state = IMU_STATE_READY;
            }
            break;
        case IMU_STATE_READING:
            status = i2c_get_status();
            if (status == I2C_STATUS_SUCCESS) {
                int16_t accel_z = (int16_t)((i2c_buf[4] << 8) | i2c_buf[5]);
                int16_t gyro_y = (int16_t)((i2c_buf[10] << 8) | i2c_buf[11]);

                if (accel_z > 8200) accel_z = 8200;
                if (accel_z < -8200) accel_z = -8200;

                float angle_acc = asin((float)accel_z / 8200.0) * 57.296;
                angle_gyro += gyro_y * 0.000031;
                angle_gyro = angle_gyro * 0.9996 + angle_acc * 0.0004;

                state = IMU_STATE_READY;
            } else if (status == I2C_STATUS_ERROR) {
                state = IMU_STATE_READY;
            }
            break;
    }
}

float imu_get_tilt_angle(void) {
    return angle_gyro;
}
