import pytest

def setup_module(module):
    os.makedirs("src", exist_ok=True)
    if not os.path.exists("src/drv_i2c.h"):
        with open("src/drv_i2c.h", "w") as f:
            f.write("""
#ifndef DRV_I2C_H
#define DRV_I2C_H
#include <stdint.h>
#include <stdbool.h>
typedef enum {
    I2C_STATUS_IDLE = 0,
    I2C_STATUS_BUSY,
    I2C_STATUS_SUCCESS,
    I2C_STATUS_ERROR
} i2c_status_t;
void i2c_init(void);
bool i2c_write_async(uint8_t addr, const uint8_t *data, uint8_t len);
bool i2c_read_async(uint8_t addr, uint8_t *data, uint8_t len);
i2c_status_t i2c_get_status(void);
#endif
""")
    if not os.path.exists("src/drv_i2c.c"):
        with open("src/drv_i2c.c", "w") as f:
            f.write("""
#include "drv_i2c.h"
#include <avr/io.h>
#include <avr/interrupt.h>

static i2c_status_t status = I2C_STATUS_IDLE;
static uint8_t *buf;
static uint8_t len;
static uint8_t addr;
static bool is_read;

void i2c_init(void) {}
bool i2c_write_async(uint8_t a, const uint8_t *d, uint8_t l) {
    if (status == I2C_STATUS_BUSY) return false;
    addr = a; buf = (uint8_t*)d; len = l; is_read = false;
    status = I2C_STATUS_BUSY;
    TWCR = (1<<TWINT) | (1<<TWSTA) | (1<<TWEN) | (1<<TWIE);
    return true;
}
bool i2c_read_async(uint8_t a, uint8_t *d, uint8_t l) {
    if (status == I2C_STATUS_BUSY) return false;
    addr = a; buf = d; len = l; is_read = true;
    status = I2C_STATUS_BUSY;
    TWCR = (1<<TWINT) | (1<<TWSTA) | (1<<TWEN) | (1<<TWIE);
    return true;
}
i2c_status_t i2c_get_status(void) { return status; }

ISR(TWI_vect) {
    uint8_t st = TWSR & 0xF8;
    if (st == 0x08) {
        TWDR = (addr << 1) | (is_read ? 1 : 0);
        TWCR = (1<<TWINT) | (1<<TWEN) | (1<<TWIE);
    } else if (st == 0x18 || st == 0x28) {
        if (len > 0) {
            TWDR = *buf++;
            len--;
            TWCR = (1<<TWINT) | (1<<TWEN) | (1<<TWIE);
        } else {
            TWCR = (1<<TWINT) | (1<<TWSTO) | (1<<TWEN) | (1<<TWIE);
            status = I2C_STATUS_SUCCESS;
