    l.TWI_vect_fn.argtypes = []
    l.TWI_vect_fn.restype = None
    return l

def sim_twi(lib, read_data=None, inject_error=False):
    TWCR = ctypes.c_uint8.in_dll(lib, "TWCR")
    TWSR = ctypes.c_uint8.in_dll(lib, "TWSR")
    TWDR = ctypes.c_uint8.in_dll(lib, "TWDR")

    written_data = []
    if read_data is None:
        read_data = []

    for _ in range(50):
        if TWCR.value & 0x80:
            twcr = TWCR.value
            TWCR.value &= ~0x80

            if inject_error:
                TWSR.value = 0x38
                TWCR.value |= 0x80
                if twcr & 0x01:
                    lib.TWI_vect_fn()
                break

            if twcr & 0x20:
                TWSR.value = 0x08
            elif twcr & 0x10:
                TWCR.value &= ~0x10
                break
            else:
                if TWSR.value == 0x08:
                    if TWDR.value & 1:
                        TWSR.value = 0x40
                    else:
                        TWSR.value = 0x18
                elif TWSR.value in (0x18, 0x28):
                    written_data.append(TWDR.value)
                    TWSR.value = 0x28
                elif TWSR.value in (0x40, 0x50):
                    if read_data:
                        TWDR.value = read_data.pop(0)
                    else:
                        TWDR.value = 0
                    TWSR.value = 0x50 if (twcr & 0x40) else 0x58

            TWCR.value |= 0x80
            if twcr & 0x01:
                lib.TWI_vect_fn()

    return written_data

def test_imu_init_sequence(lib):
    lib.imu_init()

    # PWR_MGMT_1
    lib.imu_update()
    wd = sim_twi(lib)
    assert wd == [0x6B, 0x00]
    lib.imu_update()

    # GYRO_CONFIG
    lib.imu_update()
    wd = sim_twi(lib)
    assert wd == [0x1B, 0x00]
    lib.imu_update()

    # ACCEL_CONFIG
    lib.imu_update()
    wd = sim_twi(lib)
    assert wd == [0x1C, 0x08]
    lib.imu_update()

    # CONFIG
    lib.imu_update()
    wd = sim_twi(lib)
    assert wd == [0x1A, 0x03]
    lib.imu_update()

    # READY -> Ghi 0x3B
    lib.imu_update()
    wd = sim_twi(lib)
    assert wd == [0x3B]
    lib.imu_update()

    # Đọc 14 bytes
    data = [0]*14
    data[4] = 0x10 # 4096
    data[5] = 0x00
    data[10] = 0x03 # 1000
    data[11] = 0xE8

    sim_twi(lib, data)
    lib.imu_update()

    angle = lib.imu_get_tilt_angle()
    assert abs(angle - 0.04298) < 0.01

def test_imu_error_handling(lib):
    lib.imu_init()
    for _ in range(4):
        lib.imu_update()
        sim_twi(lib)
        lib.imu_update()

    old_angle = lib.imu_get_tilt_angle()

    # Ghi 0x3B
    lib.imu_update()
    sim_twi(lib)
    lib.imu_update()

    # Đọc 14 bytes nhưng bị lỗi
    sim_twi(lib, inject_error=True)
    lib.imu_update()

    new_angle = lib.imu_get_tilt_angle()
    assert old_angle == new_angle

def test_imu_angle_sign(lib):
    lib.imu_init()
    for _ in range(4):
        lib.imu_update()
        sim_twi(lib)
        lib.imu_update()

    # Ghi 0x3B
    lib.imu_update()
    sim_twi(lib)
    lib.imu_update()

    data = [0]*14
    # -4096 = 0xF000
    data[4] = 0xF0
    data[5] = 0x00
    data[10] = 0x00
    data[11] = 0x00

    sim_twi(lib, data)
    lib.imu_update()

    angle = lib.imu_get_tilt_angle()
    assert angle < 0.0
