import ctypes
import subprocess
import os

def test_imu():
    cmd = [
        "cc", "-std=c11", "-Wall", "-fPIC", "-shared",
        "src/drv_imu.c", "src/drv_i2c.c",
        "/Users/v/Documents/KTDT/packs/avr/hostmock/eaa_io_space.c",
        "-I/Users/v/Documents/KTDT/packs/avr/hostmock",
        "-o", "libdrv_imu.so"
    ]
    subprocess.run(cmd, check=True)

    lib = ctypes.CDLL("./libdrv_imu.so")

    lib.imu_init.argtypes = []
    lib.imu_init.restype = None
    lib.imu_update.argtypes = []
    lib.imu_update.restype = None
    lib.imu_get_tilt_angle.argtypes = []
    lib.imu_get_tilt_angle.restype = ctypes.c_float

    lib.TWI_vect_fn.argtypes = []
    lib.TWI_vect_fn.restype = None

    TWCR = ctypes.c_uint8.in_dll(lib, "TWCR")
    TWSR = ctypes.c_uint8.in_dll(lib, "TWSR")
    TWDR = ctypes.c_uint8.in_dll(lib, "TWDR")

    class TWISim:
        def __init__(self):
            self.state = 'IDLE'
            self.mem = {}
            self.read_buf = [0]*14
            self.read_idx = 0
            self.force_nack = False

        def step(self):
            if not (TWCR.value & 0x80):
                return False

            twcr = TWCR.value

            if twcr & 0x20:
                TWSR.value = 0x08 if self.state == 'IDLE' else 0x10
                self.state = 'START'
                TWCR.value &= ~0x20
            elif twcr & 0x10:
                self.state = 'IDLE'
                TWCR.value &= ~0x10
                TWCR.value &= ~0x80
                return False
            else:
                if self.state in ('START', 'REP_START'):
                    sla = TWDR.value
                    if sla & 1:
                        TWSR.value = 0x48 if self.force_nack else 0x40
                        self.state = 'SLA_R'
                    else:
                        TWSR.value = 0x20 if self.force_nack else 0x18
                        self.state = 'SLA_W'
                elif self.state == 'SLA_W':
                    self.reg = TWDR.value
                    TWSR.value = 0x30 if self.force_nack else 0x28
                    self.state = 'DATA_W'
                elif self.state == 'DATA_W':
                    self.mem[self.reg] = TWDR.value
                    self.reg += 1
                    TWSR.value = 0x30 if self.force_nack else 0x28
                elif self.state in ('SLA_R', 'DATA_R'):
                    if self.read_idx < len(self.read_buf):
                        TWDR.value = self.read_buf[self.read_idx]
                        self.read_idx += 1
                    else:
                        TWDR.value = 0

                    if twcr & 0x40:
                        TWSR.value = 0x50
                    else:
                        TWSR.value = 0x58
                    self.state = 'DATA_R'

            TWCR.value &= ~0x80
            lib.TWI_vect_fn()
            return True

        def run(self):
            while self.step():
                pass

    sim = TWISim()

    lib.imu_init()

    # Run updates to pass initialization
    for _ in range(10):
        lib.imu_update()
        sim.run()

    # Check if initialization registers are written correctly
    assert sim.mem.get(0x6B) == 0x00
    assert sim.mem.get(0x1B) == 0x00
    assert sim.mem.get(0x1C) == 0x08
    assert sim.mem.get(0x1A) == 0x03

    # Test positive angle
    accel_z = 4100
    gyro_y = 1000
    sim.read_buf[4] = (accel_z >> 8) & 0xFF
    sim.read_buf[5] = accel_z & 0xFF
    sim.read_buf[10] = (gyro_y >> 8) & 0xFF
    sim.read_buf[11] = gyro_y & 0xFF
    sim.read_idx = 0

    # Trigger write 0x3B
    lib.imu_update()
    sim.run()
    # Trigger read
    lib.imu_update()
    sim.run()
    # Process data
    lib.imu_update()

    angle1 = lib.imu_get_tilt_angle()
    assert angle1 > 0.01 and angle1 < 0.05

    # Test negative angle
    accel_z = -4100
    accel_z_u = accel_z & 0xFFFF
    sim.read_buf[4] = (accel_z_u >> 8) & 0xFF
    sim.read_buf[5] = accel_z_u & 0xFF
    sim.read_idx = 0

    # Trigger write 0x3B
    lib.imu_update()
    sim.run()
    # Trigger read
    lib.imu_update()
    sim.run()
    # Process data
    lib.imu_update()

    angle2 = lib.imu_get_tilt_angle()
    assert angle2 < angle1

    # Test bus error
    sim.force_nack = True
    # Trigger write 0x3B
    lib.imu_update()
    sim.run()
    # Process error
    lib.imu_update()

    angle3 = lib.imu_get_tilt_angle()
    assert angle3 == angle2

if __name__ == "__main__":
    test_imu()
