```
#include "drv_imu.h"
#include "drv_i2c.h"
#include <math.h>
#include <stdint.h>
#include <stdbool.h>

typedef enum {
    IMU_STATE_INIT_START = 0,
    IMU_STATE_INIT_PWR,
    IMU_STATE_INIT_GYRO,
    IMU_STATE_INIT_ACCEL,
    IMU_STATE_INIT_CONFIG,
    IMU_STATE_READY,
    IMU_STATE_REQ_READ,
    IMU_STATE_READING
} imu_state_t;

static imu_state_t state = IMU_STATE_INIT_START;
static uint8_t i2c_buf[14];
static float current_angle = 0.0f;

void imu_init(void) {
    i2c_init();
    state = IMU_STATE_INIT_START;
    current_angle = 0.0f;
}

void imu_update(void) {
    i2c_status_t status = i2c_get_status();

    if (status == I2C_STATUS_BUSY) {
        return;
    }

    switch (state) {
        case IMU_STATE_INIT_START:
            // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
            i2c_buf[0] = 0x6B; // PWR_MGMT_1
            i2c_buf[1] = 0x00;
            if (i2c_write_async(0x68, i2c_buf, 2)) {
                state = IMU_STATE_INIT_PWR;
            }
            break;

        case IMU_STATE_INIT_PWR:
            if (status == I2C_STATUS_SUCCESS) {
                // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
                i2c_buf[0] = 0x1B; // GYRO_CONFIG
                i2c_buf[1] = 0x00;
                if (i2c_write_async(0x68, i2c_buf, 2)) {
                    state = IMU_STATE_INIT_GYRO;
                }
            } else if (status == I2C_STATUS_ERROR) {
                state = IMU_STATE_INIT_START;
            }
            break;

        case IMU_STATE_INIT_GYRO:
            if (status == I2C_STATUS_SUCCESS) {
                // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
                i2c_buf[0] = 0x1C; // ACCEL_CONFIG
                i2c_buf[1] = 0x08;
                if (i2c_write_async(0x68, i2c_buf, 2)) {
                    state = IMU_STATE_INIT_ACCEL;
                }
            } else if (status == I2C_STATUS_ERROR) {
                state = IMU_STATE_INIT_START;
            }
            break;

        case IMU_STATE_INIT_ACCEL:
            if (status == I2C_STATUS_SUCCESS) {
                // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
                i2c_buf[0] = 0x1A; // CONFIG
                i2c_buf[1] = 0x03;
                if (i2c_write_async(0x68, i2c_buf, 2)) {
                    state = IMU_STATE_INIT_CONFIG;
                }
            } else if (status == I2C_STATUS_ERROR) {
                state = IMU_STATE_INIT_START;
            }
            break;

        case IMU_STATE_INIT_CONFIG:
            if (status == I2C_STATUS_SUCCESS) {
                state = IMU_STATE_READY;
            } else if (status == I2C_STATUS_ERROR) {
                state = IMU_STATE_INIT_START;
            }
            break;

        case IMU_STATE_READY:
            // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
            i2c_buf[0] = 0x3B; // ACCEL_XOUT_H
            if (i2c_write_async(0x68, i2c_buf, 1)) {
                state = IMU_STATE_REQ_READ;
            }
            break;

        case IMU_STATE_REQ_READ:
            if (status == I2C_STATUS_SUCCESS) {
                if (i2c_read_async(0x68, i2c_buf, 14)) {
                    state = IMU_STATE_READING;
                }
            } else if (status == I2C_STATUS_ERROR) {
                state = IMU_STATE_READY;
            }
            break;

        case IMU_STATE_READING:
            if (status == I2C_STATUS_SUCCESS) {
                int16_t accel_z = (int16_t)(((uint16_t)i2c_buf[4] << 8) | i2c_buf[5]);
                int16_t gyro_y = (int16_t)(((uint16_t)i2c_buf[10] << 8) | i2c_buf[11]);

                if (accel_z > 8200) accel_z = 8200;
                if (accel_z < -8200) accel_z = -8200;

                float angle_acc = asin((float)accel_z / 8200.0) * 57.296;
                current_angle += (float)gyro_y * 0.000031;
                current_angle = current_angle * 0.9996 + angle_acc * 0.0004;

                state = IMU_STATE_READY;
            } else if (status == I2C_STATUS_ERROR) {
                state = IMU_STATE_READY;
            }
            break;
    }
}

float imu_get_tilt_angle(void) {
    return current_angle;
}

```


