#include "drv_imu.h"
#include "drv_i2c.h"
#include <math.h>
#include <stdint.h>

#define MPU6050_ADDR 0x68

typedef enum {
    IMU_STATE_INIT_PWR = 0,
    IMU_STATE_INIT_PWR_WAIT,
    IMU_STATE_INIT_GYRO,
    IMU_STATE_INIT_GYRO_WAIT,
    IMU_STATE_INIT_ACCEL,
    IMU_STATE_INIT_ACCEL_WAIT,
    IMU_STATE_INIT_CONFIG,
    IMU_STATE_INIT_CONFIG_WAIT,
    IMU_STATE_IDLE,
    IMU_STATE_READ_REQ_WAIT,
    IMU_STATE_READ_DATA_WAIT
} imu_state_t;

static imu_state_t state = IMU_STATE_INIT_PWR;
static uint8_t i2c_buf[14];
static float angle_gyro = 0.0f;
static float final_angle = 0.0f;

void imu_init(void) {
    state = IMU_STATE_INIT_PWR;
    angle_gyro = 0.0f;
    final_angle = 0.0f;
}

void imu_update(void) {
    i2c_status_t status = i2c_get_status();

    switch (state) {
        case IMU_STATE_INIT_PWR:
            if (status == I2C_STATUS_IDLE || status == I2C_STATUS_SUCCESS || status == I2C_STATUS_ERROR) {
                i2c_buf[0] = 0x6B; // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
                i2c_buf[1] = 0x00;
                if (i2c_write_async(MPU6050_ADDR, i2c_buf, 2)) {
                    state = IMU_STATE_INIT_PWR_WAIT;
                }
            }
            break;

        case IMU_STATE_INIT_PWR_WAIT:
            if (status == I2C_STATUS_SUCCESS) {
                state = IMU_STATE_INIT_GYRO;
            } else if (status == I2C_STATUS_ERROR) {
                state = IMU_STATE_INIT_PWR;
            }
            break;

        case IMU_STATE_INIT_GYRO:
            if (status == I2C_STATUS_IDLE || status == I2C_STATUS_SUCCESS) {
                i2c_buf[0] = 0x1B; // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
                i2c_buf[1] = 0x00;
                if (i2c_write_async(MPU6050_ADDR, i2c_buf, 2)) {
                    state = IMU_STATE_INIT_GYRO_WAIT;
                }
            }
            break;

        case IMU_STATE_INIT_GYRO_WAIT:
            if (status == I2C_STATUS_SUCCESS) {
                state = IMU_STATE_INIT_ACCEL;
            } else if (status == I2C_STATUS_ERROR) {
                state = IMU_STATE_INIT_GYRO;
            }
            break;

        case IMU_STATE_INIT_ACCEL:
            if (status == I2C_STATUS_IDLE || status == I2C_STATUS_SUCCESS) {
                i2c_buf[0] = 0x1C; // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
                i2c_buf[1] = 0x08;
                if (i2c_write_async(MPU6050_ADDR, i2c_buf, 2)) {
                    state = IMU_STATE_INIT_ACCEL_WAIT;
                }
            }
            break;

        case IMU_STATE_INIT_ACCEL_WAIT:
            if (status == I2C_STATUS_SUCCESS) {
                state = IMU_STATE_INIT_CONFIG;
            } else if (status == I2C_STATUS_ERROR) {
                state = IMU_STATE_INIT_ACCEL;
            }
            break;

        case IMU_STATE_INIT_CONFIG:
            if (status == I2C_STATUS_IDLE || status == I2C_STATUS_SUCCESS) {
                i2c_buf[0] = 0x1A; // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
                i2c_buf[1] = 0x03;
                if (i2c_write_async(MPU6050_ADDR, i2c_buf, 2)) {
                    state = IMU_STATE_INIT_CONFIG_WAIT;
                }
            }
            break;

        case IMU_STATE_INIT_CONFIG_WAIT:
            if (status == I2C_STATUS_SUCCESS) {
                state = IMU_STATE_IDLE;
            } else if (status == I2C_STATUS_ERROR) {
                state = IMU_STATE_INIT_CONFIG;
            }
            break;

        case IMU_STATE_IDLE:
            if (status == I2C_STATUS_IDLE || status == I2C_STATUS_SUCCESS || status == I2C_STATUS_ERROR) {
                i2c_buf[0] = 0x3B; // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
                if (i2c_write_async(MPU6050_ADDR, i2c_buf, 1)) {
                    state = IMU_STATE_READ_REQ_WAIT;
                }
            }
            break;

        case IMU_STATE_READ_REQ_WAIT:
            if (status == I2C_STATUS_SUCCESS) {
                if (i2c_read_async(MPU6050_ADDR, i2c_buf, 14)) {
                    state = IMU_STATE_READ_DATA_WAIT;
                }
            } else if (status == I2C_STATUS_ERROR) {
                state = IMU_STATE_IDLE;
            }
            break;

        case IMU_STATE_READ_DATA_WAIT:
            if (status == I2C_STATUS_SUCCESS) {
                int16_t accel_z = (int16_t)(((uint16_t)i2c_buf[4] << 8) | i2c_buf[5]);
                int16_t gyro_y_raw = (int16_t)(((uint16_t)i2c_buf[10] << 8) | i2c_buf[11]);

                if (accel_z > 8200) accel_z = 8200;
                if (accel_z < -8200) accel_z = -8200;

                float angle_acc = asin((float)accel_z / 8200.0) * 57.296;
                angle_gyro += gyro_y_raw * 0.000031;
                angle_gyro = angle_gyro * 0.9996 + angle_acc * 0.0004;
                final_angle = angle_gyro;

                state = IMU_STATE_IDLE;
            } else if (status == I2C_STATUS_ERROR) {
                state = IMU_STATE_IDLE;
            }
            break;
    }
}

float imu_get_tilt_angle(void) {
    return final_angle;
}
