def run_i2c(lib, sim_device):
    TWCR = ctypes.c_uint8.in_dll(lib, "TWCR")
    TWSR = ctypes.c_uint8.in_dll(lib, "TWSR")
    TWDR = ctypes.c_uint8.in_dll(lib, "TWDR")

    while True:
        twcr_val = TWCR.value
        if not (twcr_val & 0x80):
            if twcr_val & 0x20:
                if sim_device.get('active', False):
                    TWSR.value = 0x10
                else:
                    TWSR.value = 0x08
                    sim_device['active'] = True
                TWCR.value = twcr_val | 0x80
                lib.TWI_vect_fn()
            elif twcr_val & 0x10:
                sim_device['active'] = False
                TWCR.value = (twcr_val & ~0x10) | 0x80
                break
            else:
                twsr_val = TWSR.value & 0xF8
                if twsr_val in (0x08, 0x10):
                    sla = TWDR.value
                    sim_device['is_read'] = (sla & 1) == 1
                    if sim_device['is_read']:
                        TWSR.value = 0x40
                    else:
                        TWSR.value = 0x18
                        sim_device['write_first_byte'] = True
                    TWCR.value = twcr_val | 0x80
                    lib.TWI_vect_fn()
                elif twsr_val in (0x18, 0x28):
                    data = TWDR.value
                    if sim_device.get('write_first_byte', False):
                        sim_device['reg_ptr'] = data
                        sim_device['write_first_byte'] = False
                    else:
                        sim_device['regs'][sim_device['reg_ptr']] = data
                        sim_device['reg_ptr'] = (sim_device['reg_ptr'] + 1) & 0xFF
                    TWSR.value = 0x28
                    TWCR.value = twcr_val | 0x80
                    lib.TWI_vect_fn()
                elif twsr_val in (0x40, 0x50):
                    TWDR.value = sim_device['regs'].get(sim_device['reg_ptr'], 0)
                    sim_device['reg_ptr'] = (sim_device['reg_ptr'] + 1) & 0xFF
                    if twcr_val & 0x40:
                        TWSR.value = 0x50
                    else:
                        TWSR.value = 0x58
                    TWCR.value = twcr_val | 0x80
                    lib.TWI_vect_fn()
                else:
                    break
        else:
            break

