#include "drv_imu.h"
#include "drv_i2c.h"
#include <avr/io.h>
#include <math.h>

#define ACCEL_CONFIG 0x1C // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
#define ACCEL_XOUT_H 0x3B // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
#define CONFIG 0x1A       // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
#define GYRO_CONFIG 0x1B  // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
#define GYRO_XOUT_H 0x43  // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
#define PWR_MGMT_1 0x6B   // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
#define SMPLRT_DIV 0x19   // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
#define WHO_AM_I 0x75     // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45

typedef enum {
    IMU_STATE_UNINIT = 0,
    IMU_STATE_WHOAMI_REG_REQ,
    IMU_STATE_WHOAMI_REG_WAIT,
    IMU_STATE_WHOAMI_READ_REQ,
    IMU_STATE_WHOAMI_READ_WAIT,
    IMU_STATE_INIT_SEQ_REQ,
    IMU_STATE_INIT_SEQ_WAIT,
    IMU_STATE_DELAY,
    IMU_STATE_READ_REG_REQ,
    IMU_STATE_READ_REG_WAIT,
    IMU_STATE_READ_DATA_REQ,
    IMU_STATE_READ_DATA_WAIT
} imu_state_t;

static imu_state_t state = IMU_STATE_UNINIT;
static uint8_t delay_counter = 0;
static uint8_t rx_buffer[14];
static float current_angle = 0.0f;

static const uint8_t whoami_reg[1] = {WHO_AM_I};
static const uint8_t read_reg[1] = {ACCEL_XOUT_H};

static const uint8_t init_sequence[][2] = {
    {PWR_MGMT_1, 0x00},
    {SMPLRT_DIV, 0x03},
    {CONFIG, 0x03},
    {GYRO_CONFIG, 0x00},
    {ACCEL_CONFIG, 0x08}
};
#define INIT_SEQ_LEN (sizeof(init_sequence) / 2)
static uint8_t init_idx = 0;

void imu_init(void) {
    TWBR = 12;       // ref: ds-021, ATmega328P datasheet rev. DS40002061B, tr.222-224
    TWSR = 0x00;     // ref: ds-021, ATmega328P datasheet rev. DS40002061B, tr.222-224
    TWCR = (1 << 2); // ref: ds-021, ATmega328P datasheet rev. DS40002061B, tr.222-224
    TWDR = 0xFF;     // ref: ds-021, ATmega328P datasheet rev. DS40002061B, tr.222-224

    i2c_init();
    state = IMU_STATE_WHOAMI_REG_REQ;
    current_angle = 0.0f;
}

void imu_update(void) {
    i2c_status_t status = i2c_get_status();

    switch (state) {
        case IMU_STATE_UNINIT:
            break;

        case IMU_STATE_WHOAMI_REG_REQ:
            if (status != I2C_STATUS_BUSY) {
                if (i2c_write_async(0x68, whoami_reg, 1)) {
                    state = IMU_STATE_WHOAMI_REG_WAIT;
                }
            }
            break;

        case IMU_STATE_WHOAMI_REG_WAIT:
            if (status == I2C_STATUS_SUCCESS) {
                state = IMU_STATE_WHOAMI_READ_REQ;
            } else if (status == I2C_STATUS_ERROR) {
                state = IMU_STATE_WHOAMI_REG_REQ;
            }
            break;

        case IMU_STATE_WHOAMI_READ_REQ:
            if (status != I2C_STATUS_BUSY) {
                if (i2c_read_async(0x68, rx_buffer, 1)) {
                    state = IMU_STATE_WHOAMI_READ_WAIT;
                }
            }
            break;

        case IMU_STATE_WHOAMI_READ_WAIT:
            if (status == I2C_STATUS_SUCCESS) {
                if (rx_buffer[0] == 0x68) {
                    init_idx = 0;
                    state = IMU_STATE_INIT_SEQ_REQ;
                } else {
                    state = IMU_STATE_WHOAMI_REG_REQ;
                }
            } else if (status == I2C_STATUS_ERROR) {
                state = IMU_STATE_WHOAMI_REG_REQ;
            }
            break;

        case IMU_STATE_INIT_SEQ_REQ:
            if (status != I2C_STATUS_BUSY) {
                if (i2c_write_async(0x68, init_sequence[init_idx], 2)) {
                    state = IMU_STATE_INIT_SEQ_WAIT;
                }
            }
            break;

        case IMU_STATE_INIT_SEQ_WAIT:
            if (status == I2C_STATUS_SUCCESS) {
                init_idx++;
                if (init_idx >= INIT_SEQ_LEN) {
                    delay_counter = 25;
                    state = IMU_STATE_DELAY;
                } else {
                    state = IMU_STATE_INIT_SEQ_REQ;
                }
            } else if (status == I2C_STATUS_ERROR) {
                state = IMU_STATE_INIT_SEQ_REQ;
            }
            break;

        case IMU_STATE_DELAY:
            if (delay_counter > 0) {
                delay_counter--;
            } else {
                state = IMU_STATE_READ_REG_REQ;
            }
            break;

        case IMU_STATE_READ_REG_REQ:
            if (status != I2C_STATUS_BUSY) {
                if (i2c_write_async(0x68, read_reg, 1)) {
                    state = IMU_STATE_READ_REG_WAIT;
                }
            }
            break;

        case IMU_STATE_READ_REG_WAIT:
            if (status == I2C_STATUS_SUCCESS) {
                state = IMU_STATE_READ_DATA_REQ;
            } else if (status == I2C_STATUS_ERROR) {
                state = IMU_STATE_READ_REG_REQ;
            }
            break;

        case IMU_STATE_READ_DATA_REQ:
            if (status != I2C_STATUS_BUSY) {
                if (i2c_read_async(0x68, rx_buffer, 14)) {
                    state = IMU_STATE_READ_DATA_WAIT;
                }
            }
            break;

        case IMU_STATE_READ_DATA_WAIT:
            if (status == I2C_STATUS_SUCCESS) {
                int16_t accel_z = (int16_t)(((uint16_t)rx_buffer[4] << 8) | rx_buffer[5]);
                int16_t gyro_y = (int16_t)(((uint16_t)rx_buffer[10] << 8) | rx_buffer[11]);

                if (accel_z > 8200) accel_z = 8200;
                if (accel_z < -8200) accel_z = -8200;

                float angle_acc = asin((float)accel_z / 8200.0f) * 57.296f;
                current_angle += (float)gyro_y * 0.000031f;
                current_angle = current_angle * 0.9996f + angle_acc * 0.0004f;

                state = IMU_STATE_READ_REG_REQ;
            } else if (status == I2C_STATUS_ERROR) {
                state = IMU_STATE_READ_REG_REQ;
            }
            break;
    }
}

float imu_get_tilt_angle(void) {
    return current_angle;
}
