    lib.imu_get_tilt_angle.restype = ctypes.c_float
    lib.TWI_vect_fn.argtypes = []
    lib.TWI_vect_fn.restype = None

    class TWISim:
        def __init__(self, lib):
            self.lib = lib
            self.TWCR = ctypes.c_uint8.in_dll(lib, "TWCR")
            self.TWSR = ctypes.c_uint8.in_dll(lib, "TWSR")
            self.TWDR = ctypes.c_uint8.in_dll(lib, "TWDR")
            self.error = False
            self.written = []
            self.to_read = []
            self.state = 'IDLE'

        def run_until_idle(self):
            for _ in range(100):
                twcr = self.TWCR.value
                if not (twcr & 0x80):
                    if twcr & 0x20:
                        self.TWSR.value = 0x08 if self.state == 'IDLE' else 0x10
                        self.state = 'START'
                        self.TWCR.value = twcr | 0x80
                        self.lib.TWI_vect_fn()
                    elif twcr & 0x10:
                        self.TWCR.value = twcr & ~0x10
                        self.state = 'IDLE'
                    else:
                        if self.state == 'START':
                            sla = self.TWDR.value
                            if sla == 0xD0:
                                self.TWSR.value = 0x18 if not self.error else 0x20
                                self.state = 'TX'
                            elif sla == 0xD1:
                                self.TWSR.value = 0x40 if not self.error else 0x48
                                self.state = 'RX'
                        elif self.state == 'TX':
                            self.written.append(self.TWDR.value)
                            self.TWSR.value = 0x28 if not self.error else 0x30
                        elif self.state == 'RX':
                            if self.to_read:
                                self.TWDR.value = self.to_read.pop(0)
                            else:
                                self.TWDR.value = 0
                            if twcr & 0x40:
                                self.TWSR.value = 0x50
                            else:
                                self.TWSR.value = 0x58
                        self.TWCR.value = twcr | 0x80
                        self.lib.TWI_vect_fn()
                else:
                    break

    lib.imu_init()
    sim = TWISim(lib)

    # 1. WHO_AM_I Reg Req
    lib.imu_update()
    sim.run_until_idle()
    assert sim.written == [0x75]
    sim.written = []

    # 2. WHO_AM_I Read Req
    sim.to_read = [0x68]
    lib.imu_update()
    sim.run_until_idle()

    # 3. Init Sequence
    expected_seq = [
        [0x6B, 0x00],
        [0x19, 0x03],
        [0x1A, 0x03],
        [0x1B, 0x00],
        [0x1C, 0x08]
    ]

    for expected in expected_seq:
        lib.imu_update()
        sim.run_until_idle()
        assert sim.written == expected
        sim.written = []

    # Delay
    for _ in range(26):
        lib.imu_update()

    # Read Reg Req
    lib.imu_update()
    sim.run_until_idle()
    assert sim.written == [0x3B]
    sim.written = []

    # Read Data Req
    sim.to_read = [0]*14
    sim.to_read[4] = 0x10
    sim.to_read[5] = 0x04
    sim.to_read[10] = 0x03
    sim.to_read[11] = 0xE8

    lib.imu_update()
    sim.run_until_idle()

    angle1 = lib.imu_get_tilt_angle()

    angle_acc = math.asin(4100 / 8200.0) * 57.296
    angle_gyro = 1000 * 0.000031
    expected_angle1 = angle_gyro * 0.9996 + angle_acc * 0.0004
    assert abs(angle1 - expected_angle1) < 0.001

    # Error handling
    lib.imu_update()
    sim.run_until_idle()
    sim.written = []

    sim.error = True
    lib.imu_update()
    sim.run_until_idle()

    angle2 = lib.imu_get_tilt_angle()
    assert angle2 == angle1

    sim.error = False

    # Positive Clamping
    lib.imu_update()
    sim.run_until_idle()
    sim.written = []

    sim.to_read = [0]*14
    sim.to_read[4] = (9000 >> 8) & 0xFF
    sim.to_read[5] = 9000 & 0xFF
    sim.to_read[10] = 0
    sim.to_read[11] = 0

    lib.imu_update()
    sim.run_until_idle()

    angle3 = lib.imu_get_tilt_angle()
    angle_acc3 = math.asin(8200 / 8200.0) * 57.296
    angle_gyro3 = angle1 + 0 * 0.000031
    expected_angle3 = angle_gyro3 * 0.9996 + angle_acc3 * 0.0004
    assert abs(angle3 - expected_angle3) < 0.001

    # Negative Clamping
    lib.imu_update()
    sim.run_until_idle()
    sim.written = []

    sim.to_read = [0]*14
    val = -9000 & 0xFFFF
    sim.to_read[4] = (val >> 8) & 0xFF
    sim.to_read[5] = val & 0xFF
    sim.to_read[10] = 0
    sim.to_read[11] = 0

    lib.imu_update()
    sim.run_until_idle()

    angle4 = lib.imu_get_tilt_angle()
    angle_acc4 = math.asin(-8200 / 8200.0) * 57.296
    angle_gyro4 = angle3 + 0 * 0.000031
    expected_angle4 = angle_gyro4 * 0.9996 + angle_acc4 * 0.0004
    assert abs(angle4 - expected_angle4) < 0.001
