```file:src/drv_imu.c
#include "drv_imu.h"
#include "drv_i2c.h"
#include <math.h>
#include <stdint.h>

#define MPU6050_ADDR   0x68

#define WHO_AM_I       0x75
#define PWR_MGMT_1     0x6B
#define SMPLRT_DIV     0x19
#define CONFIG         0x1A
#define GYRO_CONFIG    0x1B
#define ACCEL_CONFIG   0x1C
#define ACCEL_XOUT_H   0x3B
#define GYRO_XOUT_H    0x43

// Note: TWBR, TWCR, TWDR, TWSR are configured in drv_i2c.c

typedef enum {
    IMU_STATE_WHOAMI = 0,
    IMU_STATE_WHOAMI_WAIT_REQ,
    IMU_STATE_WHOAMI_WAIT_DATA,
    IMU_STATE_PWR,
    IMU_STATE_PWR_WAIT,
    IMU_STATE_SMPLRT,
    IMU_STATE_SMPLRT_WAIT,
    IMU_STATE_GYRO,
    IMU_STATE_GYRO_WAIT,
    IMU_STATE_ACCEL,
    IMU_STATE_ACCEL_WAIT,
    IMU_STATE_CONFIG,
    IMU_STATE_CONFIG_WAIT,
    IMU_STATE_DELAY,
    IMU_STATE_READY,
    IMU_STATE_READ_REQ_WAIT,
    IMU_STATE_READ_DATA_WAIT
} imu_state_t;

static imu_state_t state = IMU_STATE_WHOAMI;
static uint8_t delay_counter = 0;
static uint8_t i2c_buf[14];
static float angle_gyro = 0.0f;

void imu_init(void) {
    state = IMU_STATE_WHOAMI;
    angle_gyro = 0.0f;
}

void imu_update(void) {
    i2c_status_t status;
    switch (state) {
        case IMU_STATE_WHOAMI:
            // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
            i2c_buf[0] = WHO_AM_I;
            if (i2c_write_async(MPU6050_ADDR, i2c_buf, 1)) {
                state = IMU_STATE_WHOAMI_WAIT_REQ;
            }
            break;
        case IMU_STATE_WHOAMI_WAIT_REQ:
            status = i2c_get_status();
            if (status == I2C_STATUS_SUCCESS) {
                if (i2c_read_async(MPU6050_ADDR, i2c_buf, 1)) {
                    state = IMU_STATE_WHOAMI_WAIT_DATA;
                }
            } else if (status == I2C_STATUS_ERROR) {
                state = IMU_STATE_WHOAMI;
            }
            break;
        case IMU_STATE_WHOAMI_WAIT_DATA:
            status = i2c_get_status();
            if (status == I2C_STATUS_SUCCESS) {
                if (i2c_buf[0] == 0x68) {
                    state = IMU_STATE_PWR;
                } else {
                    state = IMU_STATE_WHOAMI;
                }
            } else if (status == I2C_STATUS_ERROR) {
                state = IMU_STATE_WHOAMI;
            }
            break;

        case IMU_STATE_PWR:
            // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
            i2c_buf[0] = PWR_MGMT_1;
            i2c_buf[1] = 0x00;
            if (i2c_write_async(MPU6050_ADDR, i2c_buf, 2)) {
                state = IMU_STATE_PWR_WAIT;
            }
            break;
        case IMU_STATE_PWR_WAIT:
            status = i2c_get_status();
            if (status == I2C_STATUS_SUCCESS) state = IMU_STATE_SMPLRT;
            else if (status == I2C_STATUS_ERROR) state = IMU_STATE_PWR;
            break;

        case IMU_STATE_SMPLRT:
            // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
            i2c_buf[0] = SMPLRT_DIV;
            i2c_buf[1] = 0x00;
            if (i2c_write_async(MPU6050_ADDR, i2c_buf, 2)) {
                state = IMU_STATE_SMPLRT_WAIT;
            }
            break;
        case IMU_STATE_SMPLRT_WAIT:
            status = i2c_get_status();
            if (status == I2C_STATUS_SUCCESS) state = IMU_STATE_GYRO;
            else if (status == I2C_STATUS_ERROR) state = IMU_STATE_SMPLRT;
            break;

        case IMU_STATE_GYRO:
            // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
            i2c_buf[0] = GYRO_CONFIG;
            i2c_buf[1] = 0x00;
            if (i2c_write_async(MPU6050_ADDR, i2c_buf, 2)) {
                state = IMU_STATE_GYRO_WAIT;
            }
            break;
        case IMU_STATE_GYRO_WAIT:
            status = i2c_get_status();
            if (status == I2C_STATUS_SUCCESS) state = IMU_STATE_ACCEL;
            else if (status == I2C_STATUS_ERROR) state = IMU_STATE_GYRO;
            break;

        case IMU_STATE_ACCEL:
            // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
            i2c_buf[0] = ACCEL_CONFIG;
            i2c_buf[1] = 0x08;
            if (i2c_write_async(MPU6050_ADDR, i2c_buf, 2)) {
                state = IMU_STATE_ACCEL_WAIT;
            }
            break;
        case IMU_STATE_ACCEL_WAIT:
            status = i2c_get_status();
            if (status == I2C_STATUS_SUCCESS) state = IMU_STATE_CONFIG;
            else if (status == I2C_STATUS_ERROR) state = IMU_STATE_ACCEL;
            break;

        case IMU_STATE_CONFIG:
            // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
            i2c_buf[0] = CONFIG;
            i2c_buf[1] = 0x03;
            if (i2c_write_async(MPU6050_ADDR, i2c_buf, 2)) {
                state = IMU_STATE_CONFIG_WAIT;
            }
            break;
        case IMU_STATE_CONFIG_WAIT:
            status = i2c_get_status();
            if (status == I2C_STATUS_SUCCESS) {
                state = IMU_STATE_DELAY;
                delay_counter = 25; // 100ms / 4ms = 25
            }
            else if (status == I2C_STATUS_ERROR) state = IMU_STATE_CONFIG;
            break;

        case IMU_STATE_DELAY:
            if (delay_counter > 0) {
                delay_counter--;
            } else {
                state = IMU_STATE_READY;
            }
            break;

        case IMU_STATE_READY:
            // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
            i2c_buf[0] = ACCEL_XOUT_H;
            if (i2c_write_async(MPU6050_ADDR, i2c_buf, 1)) {
                state = IMU_STATE_READ_REQ_WAIT;
            }
            break;
        case IMU_STATE_READ_REQ_WAIT:
            status = i2c_get_status();
            if (status == I2C_STATUS_SUCCESS) {
                if (i2c_read_async(MPU6050_ADDR, i2c_buf, 14)) {
                    state = IMU_STATE_READ_DATA_WAIT;
                }
            } else if (status == I2C_STATUS_ERROR) {
                state = IMU_STATE_READY;
            }
            break;

        case IMU_STATE_READ_DATA_WAIT:
            status = i2c_get_status();
            if (status == I2C_STATUS_SUCCESS) {
                int16_t accel_z = (int16_t)((i2c_buf[4] << 8) | i2c_buf[5]);
                int16_t gyro_y = (int16_t)((i2c_buf[10] << 8) | i2c_buf[11]);

                if (accel_z > 8200) accel_z = 8200;
                if (accel_z < -8200) accel_z = -8200;

                float angle_acc = asin((float)accel_z / 8200.0f) * 57.296f;
                angle_gyro += (float)gyro_y * 0.000031f;
                angle_gyro = angle_gyro * 0.9996f + angle_acc * 0.0004f;

                state = IMU_STATE_READY;
            } else if (status == I2C_STATUS_ERROR) {
                state = IMU_STATE_READY;
            }
            break;
    }
}

float imu_get_tilt_angle(void) {
    return angle_gyro;
}
