import os
import subprocess
import ctypes
import pytest

def compile_lib():
    src_files = ["src/drv_imu.c", "src/drv_i2c.c", "/Users/v/Documents/KTDT/packs/avr/hostmock/eaa_io_space.c"]
    cmd = ["cc", "-std=c11", "-Wall", "-fPIC", "-shared", "-I/Users/v/Documents/KTDT/packs/avr/hostmock", "-Isrc"] + src_files + ["-o", "libdrv_imu.so", "-lm"]
    result = subprocess.run(cmd, capture_output=True, text=True)
    if result.returncode != 0:
        print(result.stderr)
        pytest.fail("Compilation failed")
    return ctypes.CDLL("./libdrv_imu.so")

def run_i2c(lib, sim_read_data=None, fail_on_addr=None):
    TWCR = ctypes.c_uint8.in_dll(lib, "TWCR")
    TWSR = ctypes.c_uint8.in_dll(lib, "TWSR")
    TWDR = ctypes.c_uint8.in_dll(lib, "TWDR")

    written_data = []
    read_idx = 0

    while TWCR.value & 0x80:
        twcr = TWCR.value

        if twcr & 0x10: # TWSTO
            TWCR.value &= ~0x10
            break

        if twcr & 0x20: # TWSTA
            TWSR.value = 0x08
            lib.TWI_vect_fn()
            continue

        state = TWSR.value & 0xF8

        if state == 0x08 or state == 0x10:
            sla = TWDR.value
            addr = sla >> 1
            is_read = sla & 1

            if addr == fail_on_addr:
                TWSR.value = 0x20 if not is_read else 0x48
                lib.TWI_vect_fn()
                continue

            if not is_read:
                TWSR.value = 0x18
            else:
                TWSR.value = 0x40
                if sim_read_data and read_idx < len(sim_read_data):
                    TWDR.value = sim_read_data[read_idx]
                    read_idx += 1
            lib.TWI_vect_fn()

        elif state == 0x18 or state == 0x28:
            data = TWDR.value
            written_data.append(data)
            TWSR.value = 0x28
            lib.TWI_vect_fn()

        elif state == 0x40 or state == 0x50:
            if twcr & 0x40: # TWEA
                TWSR.value = 0x50
            else:
                TWSR.value = 0x58
            if sim_read_data and read_idx < len(sim_read_data):
                TWDR.value = sim_read_data[read_idx]
                read_idx += 1
            lib.TWI_vect_fn()

        elif state == 0x58:
            lib.TWI_vect_fn()

        elif state == 0x20 or state == 0x48:
            lib.TWI_vect_fn()

        else:
            break

    return written_data

def test_imu():
    lib = compile_lib()

    lib.imu_init.argtypes = []
    lib.imu_init.restype = None
    lib.imu_update.argtypes = []
    lib.imu_update.restype = None
    lib.imu_get_tilt_angle.argtypes = []
    lib.imu_get_tilt_angle.restype = ctypes.c_float
    lib.i2c_init.argtypes = []
    lib.i2c_init.restype = None
    lib.TWI_vect_fn.argtypes = []
    lib.TWI_vect_fn.restype = None

    lib.i2c_init()
    lib.imu_init()

    # 1. WHO_AM_I req
    lib.imu_update()
    written = run_i2c(lib)
    assert written == [0x75]

    # WHO_AM_I read
    lib.imu_update()
    run_i2c(lib, sim_read_data=[0x68])

    # WHO_AM_I wait data
    lib.imu_update()

    # 2. PWR_MGMT_1
    lib.imu_update()
    written = run_i2c(lib)
    assert written == [0x6B, 0x00]
    lib.imu_update()

    # 3. SMPLRT_DIV
    lib.imu_update()
    written = run_i2c(lib)
    assert written == [0x19, 0x00]
    lib.imu_update()

    # 4. GYRO_CONFIG
    lib.imu_update()
    written = run_i2c(lib)
    assert written == [0x1B, 0x00]
    lib.imu_update()

    # 5. ACCEL_CONFIG
    lib.imu_update()
    written = run_i2c(lib)
    assert written == [0x1C, 0x08]
    lib.imu_update()

    # 6. CONFIG
    lib.imu_update()
    written = run_i2c(lib)
    assert written == [0x1A, 0x03]
    lib.imu_update()

    # 7. DELAY
    for _ in range(26):
        lib.imu_update()

    # 8. READ_REQ
    lib.imu_update()
    written = run_i2c(lib)
    assert written == [0x3B]

    # 9. READ_DATA
    lib.imu_update()
    read_data = [0]*14
    # accel_z = 4100 -> 0x1004
    read_data[4] = 0x10
    read_data[5] = 0x04
    # gyro_y = 1000 -> 0x03E8
    read_data[10] = 0x03
    read_data[11] = 0xE8
    run_i2c(lib, sim_read_data=read_data)

    # 10. READ_DATA_WAIT
    lib.imu_update()

    angle = lib.imu_get_tilt_angle()
    assert abs(angle - 0.0429) < 0.001

    # Test bus error does not reset angle
    lib.imu_update()
    written = run_i2c(lib, fail_on_addr=0x68) # Fail the write
    lib.imu_update() # Should go back to READY

    angle2 = lib.imu_get_tilt_angle()
    assert angle2 == angle # Angle should not change

    # 11. Test negative angle
    lib.imu_update()
    written = run_i2c(lib)
    assert written == [0x3B]

    lib.imu_update()
    read_data = [0]*14
    # accel_z = -4100 -> 0xEFFC
    read_data[4] = 0xEF
    read_data[5] = 0xFC
    # gyro_y = -1000 -> 0xFC18
    read_data[10] = 0xFC
    read_data[11] = 0x18
    run_i2c(lib, sim_read_data=read_data)

    lib.imu_update()

    angle3 = lib.imu_get_tilt_angle()
    assert abs(angle3) < 0.001
