#include "drv_imu.h"
#include "drv_i2c.h"
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

typedef enum {
    IMU_STATE_WHO_AM_I_REQ = 0,
    IMU_STATE_WHO_AM_I_READ,
    IMU_STATE_WHO_AM_I_WAIT,
    IMU_STATE_PWR_MGMT_1,
    IMU_STATE_PWR_MGMT_1_WAIT,
    IMU_STATE_SMPLRT_DIV,
    IMU_STATE_SMPLRT_DIV_WAIT,
    IMU_STATE_GYRO_CONFIG,
    IMU_STATE_GYRO_CONFIG_WAIT,
    IMU_STATE_ACCEL_CONFIG,
    IMU_STATE_ACCEL_CONFIG_WAIT,
    IMU_STATE_CONFIG,
    IMU_STATE_CONFIG_WAIT,
    IMU_STATE_DELAY,
    IMU_STATE_READY,
    IMU_STATE_READ_DATA,
    IMU_STATE_READ_DATA_WAIT
} imu_state_t;

static imu_state_t state = IMU_STATE_WHO_AM_I_REQ;
static uint8_t tx_buf[2];
static uint8_t rx_buf[14];
static uint8_t delay_counter = 0;
static float current_angle = 0.0f;

void imu_init(void) {
    state = IMU_STATE_WHO_AM_I_REQ;
    delay_counter = 0;
    current_angle = 0.0f;
}

void imu_update(void) {
    switch (state) {
        case IMU_STATE_WHO_AM_I_REQ:
            tx_buf[0] = 0x75; // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
            if (i2c_write_async(0x68, tx_buf, 1)) {
                state = IMU_STATE_WHO_AM_I_READ;
            }
            break;

        case IMU_STATE_WHO_AM_I_READ:
            if (i2c_get_status() == I2C_STATUS_SUCCESS) {
                if (i2c_read_async(0x68, rx_buf, 1)) {
                    state = IMU_STATE_WHO_AM_I_WAIT;
                }
            } else if (i2c_get_status() == I2C_STATUS_ERROR) {
                state = IMU_STATE_WHO_AM_I_REQ;
            }
            break;

        case IMU_STATE_WHO_AM_I_WAIT:
            if (i2c_get_status() == I2C_STATUS_SUCCESS) {
                if (rx_buf[0] == 0x68) {
                    state = IMU_STATE_PWR_MGMT_1;
                } else {
                    state = IMU_STATE_WHO_AM_I_REQ;
                }
            } else if (i2c_get_status() == I2C_STATUS_ERROR) {
                state = IMU_STATE_WHO_AM_I_REQ;
            }
            break;

        case IMU_STATE_PWR_MGMT_1:
            tx_buf[0] = 0x6B;
