            // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
            tx_buf[0] = 0x6B; // PWR_MGMT_1
            tx_buf[1] = 0x00;
            if (i2c_write_async(104, tx_buf, 2)) {
                state = IMU_STATE_INIT_PWR_WAIT;
            }
            break;

        case IMU_STATE_INIT_PWR_WAIT:
            if (i2c_get_status() == I2C_STATUS_SUCCESS) {
                state = IMU_STATE_INIT_SMPLRT;
            } else if (i2c_get_status() == I2C_STATUS_ERROR) {
                state = IMU_STATE_INIT_PWR;
            }
            break;

        case IMU_STATE_INIT_SMPLRT:
            // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
            tx_buf[0] = 0x19; // SMPLRT_DIV
            tx_buf[1] = 0x00;
            if (i2c_write_async(104, tx_buf, 2)) {
                state = IMU_STATE_INIT_SMPLRT_WAIT;
            }
            break;

        case IMU_STATE_INIT_SMPLRT_WAIT:
            if (i2c_get_status() == I2C_STATUS_SUCCESS) {
                state = IMU_STATE_INIT_CONFIG;
            } else if (i2c_get_status() == I2C_STATUS_ERROR) {
                state = IMU_STATE_INIT_SMPLRT;
            }
            break;

        case IMU_STATE_INIT_CONFIG:
            // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
            tx_buf[0] = 0x1A; // CONFIG
            tx_buf[1] = 0x03;
            if (i2c_write_async(104, tx_buf, 2)) {
                state = IMU_STATE_INIT_CONFIG_WAIT;
            }
            break;

        case IMU_STATE_INIT_CONFIG_WAIT:
            if (i2c_get_status() == I2C_STATUS_SUCCESS) {
                state = IMU_STATE_INIT_GYRO;
            } else if (i2c_get_status() == I2C_STATUS_ERROR) {
                state = IMU_STATE_INIT_CONFIG;
            }
            break;

        case IMU_STATE_INIT_GYRO:
            // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
            tx_buf[0] = 0x1B; // GYRO_CONFIG
            tx_buf[1] = 0x00;
            if (i2c_write_async(104, tx_buf, 2)) {
                state = IMU_STATE_INIT_GYRO_WAIT;
            }
            break;

        case IMU_STATE_INIT_GYRO_WAIT:
            if (i2c_get_status() == I2C_STATUS_SUCCESS) {
                state = IMU_STATE_INIT_ACCEL;
            } else if (i2c_get_status() == I2C_STATUS_ERROR) {
                state = IMU_STATE_INIT_GYRO;
            }
            break;

        case IMU_STATE_INIT_ACCEL:
            // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
            tx_buf[0] = 0x1C; // ACCEL_CONFIG
            tx_buf[1] = 0x08;
            if (i2c_write_async(104, tx_buf, 2)) {
                state = IMU_STATE_INIT_ACCEL_WAIT;
            }
            break;

        case IMU_STATE_INIT_ACCEL_WAIT:
            if (i2c_get_status() == I2C_STATUS_SUCCESS) {
                state = IMU_STATE_IDLE;
            } else if (i2c_get_status() == I2C_STATUS_ERROR) {
                state = IMU_STATE_INIT_ACCEL;
            }
            break;

        case IMU_STATE_IDLE:
            // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
            tx_buf[0] = 0x3B; // ACCEL_XOUT_H
            if (i2c_write_async(104, tx_buf, 1)) {
                state = IMU_STATE_SET_REG_WAIT;
            }
            break;

        case IMU_STATE_SET_REG_WAIT:
            if (i2c_get_status() == I2C_STATUS_SUCCESS) {
                state = IMU_STATE_READ_REQ;
            } else if (i2c_get_status() == I2C_STATUS_ERROR) {
                state = IMU_STATE_IDLE;
            }
            break;

        case IMU_STATE_READ_REQ:
            if (i2c_read_async(104, i2c_buf, 14)) {
                state = IMU_STATE_READ_WAIT;
            }
            break;

        case IMU_STATE_READ_WAIT:
            if (i2c_get_status() == I2C_STATUS_SUCCESS) {
                int16_t accel_z = (int16_t)((i2c_buf[4] << 8) | i2c_buf[5]);
                int16_t gyro_y = (int16_t)((i2c_buf[10] << 8) | i2c_buf[11]);

                float az = (float)accel_z;
                if (az > 8200.0f) az = 8200.0f;
                if (az < -8200.0f) az = -8200.0f;

                float angle_acc = asin(az / 8200.0f) * 57.296f;
                angle_gyro += (float)gyro_y * 0.000031f;
                angle_gyro = angle_gyro * 0.9996f + angle_acc * 0.0004f;

                state = IMU_STATE_IDLE;
            } else if (i2c_get_status() == I2C_STATUS_ERROR) {
                state = IMU_STATE_IDLE;
            }
            break;
    }
}

float imu_get_tilt_angle(void) {
    return angle_gyro;
}
