import ctypes
import pytest
import os

class MPU6050_Mock:
    def __init__(self, lib):
        self.lib = lib
        self.TWCR = ctypes.c_uint8.in_dll(lib, "TWCR")
        self.TWDR = ctypes.c_uint8.in_dll(lib, "TWDR")
        self.TWSR = ctypes.c_uint8.in_dll(lib, "TWSR")
        self.regs = {i: 0 for i in range(256)}
        self.regs[0x75] = 0x68 # WHO_AM_I
        self.state = "IDLE"
        self.reg_ptr = 0
        self.is_read = False

    def call_isr(self):
        if hasattr(self.lib, 'TWI_vect_fn'):
            self.lib.TWI_vect_fn()

    def step(self):
        twcr = self.TWCR.value
        if not (twcr & 0x80):
            return False

        self.TWCR.value = twcr & ~0x80

        if twcr & 0x20: # TWSTA
            self.TWSR.value = 0x10 if self.state != "IDLE" else 0x08
            self.state = "START"
            self.TWCR.value |= 0x80
            self.call_isr()
            return True

        if twcr & 0x10: # TWSTO
            self.state = "IDLE"
            self.TWCR.value &= ~0x10
            return True

        if self.state == "START":
            sla = self.TWDR.value
            if (sla >> 1) == 104:
                self.is_read = (sla & 1) == 1
                self.TWSR.value = 0x40 if self.is_read else 0x18
                self.state = "READ" if self.is_read else "WRITE_REG"
            else:
                self.TWSR.value = 0x48 if (sla & 1) else 0x20
            self.TWCR.value |= 0x80
            self.call_isr()
            return True

        if self.state == "WRITE_REG":
            self.reg_ptr = self.TWDR.value
            self.TWSR.value = 0x28
            self.state = "WRITE_DATA"
            self.TWCR.value |= 0x80
            self.call_isr()
            return True

        if self.state == "WRITE_DATA":
            self.regs[self.reg_ptr] = self.TWDR.value
            self.reg_ptr = (self.reg_ptr + 1) & 0xFF
            self.TWSR.value = 0x28
            self.TWCR.value |= 0x80
            self.call_isr()
            return True

        if self.state == "READ":
            self.TWDR.value = self.regs[self.reg_ptr]
            self.reg_ptr = (self.reg_ptr + 1) & 0xFF
            if twcr & 0x40: # TWEA
                self.TWSR.value = 0x50
            else:
                self.TWSR.value = 0x58
            self.TWCR.value |= 0x80
            self.call_isr()
            return True

        return False

    def run_until_idle(self):
        max_steps = 1000
        steps = 0
        while self.step():
            steps += 1
            if steps > max_steps:
                raise RuntimeError("I2C mock stuck in loop")

def test_imu_init_and_read():
    lib_path = os.environ.get("LIB_PATH", "./libdrv_imu.so")
    if not os.path.exists(lib_path):
        pytest.skip("Library not found")
    lib = ctypes.CDLL(lib_path)

    lib.imu_init.argtypes = []
    lib.imu_init.restype = None
    lib.imu_update.argtypes = []
    lib.imu_update.restype = None
    lib.imu_get_tilt_angle.argtypes = []
    lib.imu_get_tilt_angle.restype = ctypes.c_float

    mock = MPU6050_Mock(lib)

    lib.imu_init()

    for _ in range(30):
        lib.imu_update()
        mock.run_until_idle()

    assert mock.regs[0x6B] == 0x00, "PWR_MGMT_1 not set correctly"
    assert mock.regs[0x1A] == 0x03, "CONFIG not set correctly"
    assert mock.regs[0x1B] == 0x00, "GYRO_CONFIG not set correctly"
    assert mock.regs[0x1C] == 0x08, "ACCEL_CONFIG not set correctly"
    assert mock.regs[0x19] == 0x00, "SMPLRT_DIV not set correctly"

    mock.regs[0x3F] = 0x03
    mock.regs[0x40] = 0xE8
    mock.regs[0x45] = 0x01
    mock.regs[0x46] = 0xF4

    lib.imu_update()
    mock.run_until_idle()
    lib.imu_update()

    angle = lib.imu_get_tilt_angle()
    assert abs(angle - 0.018295) < 0.001, f"Expected ~0.0183, got {angle}"

    def step_nack():
        twcr = mock.TWCR.value
        if not (twcr & 0x80): return False
        mock.TWCR.value = twcr & ~0x80

        if twcr & 0x20:
            mock.TWSR.value = 0x08
            mock.state = "START"
            mock.TWCR.value |= 0x80
            mock.call_isr()
            return True

        if mock.state == "START":
            mock.TWSR.value = 0x20
            mock.TWCR.value |= 0x80
            mock.call_isr()
            return True

        if twcr & 0x10:
            mock.state = "IDLE"
            mock.TWCR.value &= ~0x10
            return True

        return False

    orig_step = mock.step
    mock.step = step_nack

    lib.imu_update()
    for _ in range(10):
        if not mock.step(): break

    lib.imu_update()
    angle_after_err = lib.imu_get_tilt_angle()
    assert angle_after_err == angle, "Angle changed after bus error!"

    mock.step = orig_step

    mock.regs[0x3F] = 0xFC
    mock.regs[0x40] = 0x18
    mock.regs[0x45] = 0xFE
    mock.regs[0x46] = 0x0C

    lib.imu_update()
    mock.run_until_idle()
    lib.imu_update()

    angle2 = lib.imu_get_tilt_angle()
    assert angle2 < 0.01, f"Expected negative or near zero, got {angle2}"
