#include "drv_i2c.h"
#include <avr/io.h>
#include <avr/interrupt.h>
#include <stddef.h>

static volatile i2c_status_t i2c_status = I2C_STATUS_IDLE;
static uint8_t i2c_addr;
static const uint8_t *i2c_write_buf;
static uint8_t *i2c_read_buf;
static uint8_t i2c_len;
static uint8_t i2c_idx;
static bool i2c_is_read;

void i2c_init(void) {
    // ref: ds-021, ATmega328P datasheet rev. DS40002061B, tr.222-224
    TWSR = 0x00;
    TWBR = 12;
    TWCR = (1 << TWEN);
    i2c_status = I2C_STATUS_IDLE;
}

bool i2c_write_async(uint8_t addr, const uint8_t *data, uint8_t len) {
    cli();
    if (i2c_status == I2C_STATUS_BUSY) {
        sei();
        return false;
    }
    i2c_status = I2C_STATUS_BUSY;
    sei();

    i2c_addr = addr;
    i2c_write_buf = data;
    i2c_len = len;
    i2c_idx = 0;
    i2c_is_read = false;

    // ref: ds-021, ATmega328P datasheet rev. DS40002061B, tr.222-224
    TWCR = (1 << TWINT) | (1 << TWSTA) | (1 << TWEN) | (1 << TWIE);
    return true;
}

bool i2c_read_async(uint8_t addr, uint8_t *data, uint8_t len) {
    cli();
    if (i2c_status == I2C_STATUS_BUSY) {
        sei();
        return false;
    }
    i2c_status = I2C_STATUS_BUSY;
    sei();

    i2c_addr = addr;
    i2c_read_buf = data;
    i2c_len = len;
    i2c_idx = 0;
    i2c_is_read = true;

    // ref: ds-021, ATmega328P datasheet rev. DS40002061B, tr.222-224
    TWCR = (1 << TWINT) | (1 << TWSTA) | (1 << TWEN) | (1 << TWIE);
    return true;
}

i2c_status_t i2c_get_status(void) {
    i2c_status_t st;
    cli();
    st = i2c_status;
    sei();
    return st;
}

ISR(TWI_vect) {
    uint8_t status = TWSR & 0xF8;
    switch (status) {
        case 0x08: // START transmitted
        case 0x10: // Repeated START transmitted
            TWDR = (i2c_addr << 1) | (i2c_is_read ? 1 : 0);
            TWCR = (1 << TWINT) | (1 << TWEN) | (1 << TWIE);
            break;

        case 0x18: // SLA+W transmitted, ACK received
        case 0x28: // Data transmitted, ACK received
            if (i2c_idx < i2c_len) {
                TWDR = i2c_write_buf[i2c_idx++];
                TWCR = (1 << TWINT) | (1 << TWEN) | (1 << TWIE);
            } else {
                TWCR = (1 << TWINT) | (1 << TWEN) | (1 << TWSTO) | (1 << TWIE);
                i2c_status = I2C_STATUS_SUCCESS;
            }
            break;

        case 0x40: // SLA+R transmitted, ACK received
            if (i2c_idx < i2c_len - 1) {
                TWCR = (1 << TWINT) | (1 << TWEN) | (1 << TWEA) | (1 << TWIE);
            } else {
                TWCR = (1 << TWINT) | (1 << TWEN) | (1 << TWIE);
            }
            break;

        case 0x50: // Data received, ACK returned
            i2c_read_buf[i2c_idx++] = TWDR;
            if (i2c_idx < i2c_len - 1) {
                TWCR = (1 << TWINT) | (1 << TWEN) | (1 << TWEA) | (1 << TWIE);
            } else {
                TWCR = (1 << TWINT) | (1 << TWEN) | (1 << TWIE);
            }
            break;

        case 0x58: // Data received, NACK returned
            i2c_read_buf[i2c_idx++] = TWDR;
            TWCR = (1 << TWINT) | (1 << TWEN) | (1 << TWSTO) | (1 << TWIE);
            i2c_status = I2C_STATUS_SUCCESS;
            break;

        case 0x20: // SLA+W NACK
        case 0x30: // Data NACK
        case 0x48: // SLA+R NACK
        case 0x38: // Arbitration lost
        default:
            TWCR = (1 << TWINT) | (1 << TWEN) | (1 << TWSTO) | (1 << TWIE);
            i2c_status = I2C_STATUS_ERROR;
            break;
    }
}
