```file:src/drv_imu.c
#include "drv_imu.h"
#include "drv_i2c.h"
#include <math.h>
#include <stdint.h>
#include <stdbool.h>

#define IMU_ADDR 104

#define WHO_AM_I 0x75
#define PWR_MGMT_1 0x6B
#define SMPLRT_DIV 0x19
#define CONFIG 0x1A
#define GYRO_CONFIG 0x1B
#define ACCEL_CONFIG 0x1C
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H 0x43

typedef enum {
    IMU_STATE_INIT_START,
    IMU_STATE_INIT_WHOAMI_REQ,
    IMU_STATE_INIT_WHOAMI_WAIT,
    IMU_STATE_INIT_PWR,
    IMU_STATE_INIT_CONFIG,
    IMU_STATE_INIT_GYRO,
    IMU_STATE_INIT_ACCEL,
    IMU_STATE_INIT_SMPLRT,
    IMU_STATE_WRITE_PTR_WAIT,
    IMU_STATE_IDLE,
    IMU_STATE_READ_WAIT
} imu_state_t;

static imu_state_t imu_state = IMU_STATE_INIT_START;
static uint8_t i2c_buf[14];
static float current_angle = 0.0f;

void imu_init(void) {
    i2c_init();
    imu_state = IMU_STATE_INIT_START;
    current_angle = 0.0f;
}

void imu_update(void) {
    i2c_status_t status = i2c_get_status();

    switch (imu_state) {
        case IMU_STATE_INIT_START:
            if (status != I2C_STATUS_BUSY) {
                i2c_buf[0] = WHO_AM_I;
                // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
                i2c_write_async(IMU_ADDR, i2c_buf, 1);
                imu_state = IMU_STATE_INIT_WHOAMI_REQ;
            }
            break;

        case IMU_STATE_INIT_WHOAMI_REQ:
            if (status == I2C_STATUS_SUCCESS) {
                i2c_read_async(IMU_ADDR, i2c_buf, 1);
                imu_state = IMU_STATE_INIT_WHOAMI_WAIT;
            } else if (status == I2C_STATUS_ERROR) {
                imu_state = IMU_STATE_INIT_START;
            }
            break;

        case IMU_STATE_INIT_WHOAMI_WAIT:
            if (status == I2C_STATUS_SUCCESS) {
                if (i2c_buf[0] == 0x68) {
                    i2c_buf[0] = PWR_MGMT_1;
                    i2c_buf[1] = 0x00;
                    // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
                    i2c_write_async(IMU_ADDR, i2c_buf, 2);
                    imu_state = IMU_STATE_INIT_PWR;
                } else {
                    imu_state = IMU_STATE_INIT_START;
                }
            } else if (status == I2C_STATUS_ERROR) {
                imu_state = IMU_STATE_INIT_START;
            }
            break;

        case IMU_STATE_INIT_PWR:
            if (status == I2C_STATUS_SUCCESS) {
                i2c_buf[0] = CONFIG;
                i2c_buf[1] = 0x03;
                // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
                i2c_write_async(IMU_ADDR, i2c_buf, 2);
                imu_state = IMU_STATE_INIT_CONFIG;
            } else if (status == I2C_STATUS_ERROR) {
                imu_state = IMU_STATE_INIT_START;
            }
            break;

        case IMU_STATE_INIT_CONFIG:
            if (status == I2C_STATUS_SUCCESS) {
                i2c_buf[0] = GYRO_CONFIG;
                i2c_buf[1] = 0x00;
                // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
                i2c_write_async(IMU_ADDR, i2c_buf, 2);
                imu_state = IMU_STATE_INIT_GYRO;
            } else if (status == I2C_STATUS_ERROR) {
                imu_state = IMU_STATE_INIT_START;
            }
            break;

        case IMU_STATE_INIT_GYRO:
            if (status == I2C_STATUS_SUCCESS) {
                i2c_buf[0] = ACCEL_CONFIG;
                i2c_buf[1] = 0x08;
                // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
                i2c_write_async(IMU_ADDR, i2c_buf, 2);
                imu_state = IMU_STATE_INIT_ACCEL;
            } else if (status == I2C_STATUS_ERROR) {
                imu_state = IMU_STATE_INIT_START;
            }
            break;

        case IMU_STATE_INIT_ACCEL:
            if (status == I2C_STATUS_SUCCESS) {
                i2c_buf[0] = SMPLRT_DIV;
                i2c_buf[1] = 0x00;
                // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
                i2c_write_async(IMU_ADDR, i2c_buf, 2);
                imu_state = IMU_STATE_INIT_SMPLRT;
            } else if (status == I2C_STATUS_ERROR) {
                imu_state = IMU_STATE_INIT_START;
            }
            break;

        case IMU_STATE_INIT_SMPLRT:
            if (status == I2C_STATUS_SUCCESS) {
                i2c_buf[0] = ACCEL_XOUT_H;
                // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
                i2c_write_async(IMU_ADDR, i2c_buf, 1);
                imu_state = IMU_STATE_WRITE_PTR_WAIT;
            } else if (status == I2C_STATUS_ERROR) {
                imu_state = IMU_STATE_INIT_START;
            }
            break;

        case IMU_STATE_WRITE_PTR_WAIT:
            if (status == I2C_STATUS_SUCCESS) {
                imu_state = IMU_STATE_IDLE;
            } else if (status == I2C_STATUS_ERROR) {
                imu_state = IMU_STATE_IDLE;
                break;
            } else {
                break;
            }
            // Fall through to IDLE để bắt đầu đọc ngay lập tức nếu bus rảnh

        case IMU_STATE_IDLE:
            if (status != I2C_STATUS_BUSY) {
                // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
                // Đọc 14 byte liên tiếp bao phủ từ ACCEL_XOUT_H đến GYRO_ZOUT_L (bao gồm GYRO_XOUT_H)
                i2c_read_async(IMU_ADDR, i2c_buf, 14);
                imu_state = IMU_STATE_READ_WAIT;
            }
            break;

        case IMU_STATE_READ_WAIT:
            if (status == I2C_STATUS_SUCCESS) {
                int16_t accel_z = (int16_t)((i2c_buf[4] << 8) | i2c_buf[5]);
                int16_t gyro_y_raw = (int16_t)((i2c_buf[10] << 8) | i2c_buf[11]);

                float az = (float)accel_z;
                if (az > 8200.0f) az = 8200.0f;
                if (az < -8200.0f) az = -8200.0f;

                float angle_acc = asin(az / 8200.0f) * 57.296f;
                current_angle += gyro_y_raw * 0.000031f;
                current_angle = current_angle * 0.9996f + angle_acc * 0.0004f;

                // Đặt lại con trỏ thanh ghi về 0x3B chuẩn bị cho chu kỳ đọc tiếp theo
                i2c_buf[0] = ACCEL_XOUT_H;
                // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
                i2c_write_async(IMU_ADDR, i2c_buf, 1);
                imu_state = IMU_STATE_WRITE_PTR_WAIT;
            } else if (status == I2C_STATUS_ERROR) {
                // Lỗi bus: bỏ qua dữ liệu, giữ nguyên góc cũ và thử lại ở vòng sau
                imu_state = IMU_STATE_IDLE;
            }
            break;
    }
}

float imu_get_tilt_angle(void) {
    return current_angle;
}
