#include "drv_imu.h"
#include "drv_i2c.h"
#include <math.h>
#include <stdint.h>
#include <stdbool.h>

typedef enum {
    IMU_STATE_UNINIT = 0,
    IMU_STATE_INIT_WHOAMI_START,
    IMU_STATE_INIT_WHOAMI_WAIT_WRITE,
    IMU_STATE_INIT_WHOAMI_READ_START,
    IMU_STATE_INIT_WHOAMI_WAIT_READ,
    IMU_STATE_INIT_PWR_START,
    IMU_STATE_INIT_PWR_WAIT,
    IMU_STATE_INIT_DELAY,
    IMU_STATE_INIT_SMPLRT_START,
    IMU_STATE_INIT_SMPLRT_WAIT,
    IMU_STATE_INIT_GYRO_START,
    IMU_STATE_INIT_GYRO_WAIT,
    IMU_STATE_INIT_ACCEL_START,
    IMU_STATE_INIT_ACCEL_WAIT,
    IMU_STATE_INIT_CONFIG_START,
    IMU_STATE_INIT_CONFIG_WAIT,
    IMU_STATE_IDLE,
    IMU_STATE_READ_ADDR_START,
    IMU_STATE_READ_ADDR_WAIT,
    IMU_STATE_READ_DATA_START,
    IMU_STATE_READ_DATA_WAIT
} imu_state_t;

static imu_state_t state = IMU_STATE_UNINIT;
static uint8_t delay_counter = 0;
static float current_angle = 0.0f;
static float angle_gyro = 0.0f;

void imu_init(void) {
    i2c_init();
    state = IMU_STATE_INIT_WHOAMI_START;
    delay_counter = 0;
    current_angle = 0.0f;
    angle_gyro = 0.0f;
}

float imu_get_tilt_angle(void) {
    return current_angle;
}

void imu_update(void) {
    static uint8_t tx_buf[2];
    static uint8_t rx_buf[14];
    static uint8_t reg_addr;
    bool state_changed;

    do {
        state_changed = false;
        switch (state) {
            case IMU_STATE_UNINIT:
                break;

            case IMU_STATE_INIT_WHOAMI_START:
                // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
                reg_addr = 0x75; // WHO_AM_I
                if (i2c_write_async(0x68, &reg_addr, 1)) {
                    state = IMU_STATE_INIT_WHOAMI_WAIT_WRITE;
                    state_changed = true;
                }
                break;

            case IMU_STATE_INIT_WHOAMI_WAIT_WRITE:
                if (i2c_get_status() == I2C_STATUS_SUCCESS) {
                    state = IMU_STATE_INIT_WHOAMI_READ_START;
                    state_changed = true;
                } else if (i2c_get_status() == I2C_STATUS_ERROR) {
                    state = IMU_STATE_INIT_WHOAMI_START;
                    state_changed = true;
                }
                break;

            case IMU_STATE_INIT_WHOAMI_READ_START:
                if (i2c_read_async(0x68, rx_buf, 1)) {
                    state = IMU_STATE_INIT_WHOAMI_WAIT_READ;
                    state_changed = true;
                }
                break;

            case IMU_STATE_INIT_WHOAMI_WAIT_READ:
                if (i2c_get_status() == I2C_STATUS_SUCCESS) {
                    if (rx_buf[0] == 0x68) {
                        state = IMU_STATE_INIT_PWR_START;
                        state_changed = true;
                    } else {
                        state = IMU_STATE_INIT_WHOAMI_START;
                        state_changed = true;
                    }
                } else if (i2c_get_status() == I2C_STATUS_ERROR) {
                    state = IMU_STATE_INIT_WHOAMI_START;
                    state_changed = true;
                }
                break;

            case IMU_STATE_INIT_PWR_START:
                // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
                tx_buf[0] = 0x6B; // PWR_MGMT_1
                tx_buf[1] = 0x00;
                if (i2c_write_async(0x68, tx_buf, 2)) {
                    state = IMU_STATE_INIT_PWR_WAIT;
                    state_changed = true;
                }
                break;

            case IMU_STATE_INIT_PWR_WAIT:
                if (i2c_get_status() == I2C_STATUS_SUCCESS) {
                    state = IMU_STATE_INIT_DELAY;
                    delay_counter = 25; // 25 chu kỳ * 4ms = 100ms
                    state_changed = true;
                } else if (i2c_get_status() == I2C_STATUS_ERROR) {
                    state = IMU_STATE_INIT_PWR_START;
                    state_changed = true;
                }
                break;

            case IMU_STATE_INIT_DELAY:
                if (delay_counter > 0) {
                    delay_counter--;
                } else {
                    state = IMU_STATE_INIT_SMPLRT_START;
                    state_changed = true;
                }
                break;

            case IMU_STATE_INIT_SMPLRT_START:
                // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
                tx_buf[0] = 0x19; // SMPLRT_DIV
                tx_buf[1] = 0x00;
                if (i2c_write_async(0x68, tx_buf, 2)) {
                    state = IMU_STATE_INIT_SMPLRT_WAIT;
                    state_changed = true;
                }
                break;

            case IMU_STATE_INIT_SMPLRT_WAIT:
                if (i2c_get_status() == I2C_STATUS_SUCCESS) {
                    state = IMU_STATE_INIT_GYRO_START;
                    state_changed = true;
                } else if (i2c_get_status() == I2C_STATUS_ERROR) {
                    state = IMU_STATE_INIT_SMPLRT_START;
                    state_changed = true;
                }
                break;

            case IMU_STATE_INIT_GYRO_START:
                // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
                tx_buf[0] = 0x1B; // GYRO_CONFIG
                tx_buf[1] = 0x00;
                if (i2c_write_async(0x68, tx_buf, 2)) {
                    state = IMU_STATE_INIT_GYRO_WAIT;
                    state_changed = true;
                }
                break;

            case IMU_STATE_INIT_GYRO_WAIT:
                if (i2c_get_status() == I2C_STATUS_SUCCESS) {
                    state = IMU_STATE_INIT_ACCEL_START;
                    state_changed = true;
                } else if (i2c_get_status() == I2C_STATUS_ERROR) {
                    state = IMU_STATE_INIT_GYRO_START;
                    state_changed = true;
                }
                break;

            case IMU_STATE_INIT_ACCEL_START:
                // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
                tx_buf[0] = 0x1C; // ACCEL_CONFIG
                tx_buf[1] = 0x08;
                if (i2c_write_async(0x68, tx_buf, 2)) {
                    state = IMU_STATE_INIT_ACCEL_WAIT;
                    state_changed = true;
                }
                break;

            case IMU_STATE_INIT_ACCEL_WAIT:
                if (i2c_get_status() == I2C_STATUS_SUCCESS) {
                    state = IMU_STATE_INIT_CONFIG_START;
                    state_changed = true;
                } else if (i2c_get_status() == I2C_STATUS_ERROR) {
                    state = IMU_STATE_INIT_ACCEL_START;
                    state_changed = true;
                }
                break;

            case IMU_STATE_INIT_CONFIG_START:
                // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
                tx_buf[0] = 0x1A; // CONFIG
                tx_buf[1] = 0x03;
                if (i2c_write_async(0x68, tx_buf, 2)) {
                    state = IMU_STATE_INIT_CONFIG_WAIT;
                    state_changed = true;
                }
                break;

            case IMU_STATE_INIT_CONFIG_WAIT:
                if (i2c_get_status() == I2C_STATUS_SUCCESS) {
                    state = IMU_STATE_IDLE;
                    state_changed = true;
                } else if (i2c_get_status() == I2C_STATUS_ERROR) {
                    state = IMU_STATE_INIT_CONFIG_START;
                    state_changed = true;
                }
                break;

            case IMU_STATE_IDLE:
                state = IMU_STATE_READ_ADDR_START;
                state_changed = true;
                break;

            case IMU_STATE_READ_ADDR_START:
                // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
                reg_addr = 0x3B; // ACCEL_XOUT_H
                if (i2c_write_async(0x68, &reg_addr, 1)) {
                    state = IMU_STATE_READ_ADDR_WAIT;
                    state_changed = true;
                }
                break;

            case IMU_STATE_READ_ADDR_WAIT:
                if (i2c_get_status() == I2C_STATUS_SUCCESS) {
                    state = IMU_STATE_READ_DATA_START;
                    state_changed = true;
                } else if (i2c_get_status() == I2C_STATUS_ERROR) {
                    state = IMU_STATE_IDLE;
                }
                break;

            case IMU_STATE_READ_DATA_START:
                if (i2c_read_async(0x68, rx_buf, 14)) {
                    state = IMU_STATE_READ_DATA_WAIT;
                    state_changed = true;
                }
                break;

            case IMU_STATE_READ_DATA_WAIT:
                if (i2c_get_status() == I2C_STATUS_SUCCESS) {
                    int16_t accel_z = (int16_t)((rx_buf[4] << 8) | rx_buf[5]);
                    int16_t gyro_y = (int16_t)((rx_buf[10] << 8) | rx_buf[11]);

                    if (accel_z > 8200) accel_z = 8200;
                    if (accel_z < -8200) accel_z = -8200;

                    float angle_acc = asin((float)accel_z / 8200.0) * 57.296;
                    angle_gyro += gyro_y * 0.000031;
                    angle_gyro = angle_gyro * 0.9996 + angle_acc * 0.0004;

                    current_angle = angle_gyro;

                    state = IMU_STATE_IDLE;
                } else if (i2c_get_status() == I2C_STATUS_ERROR) {
                    state = IMU_STATE_IDLE;
                }
                break;
        }
    } while (state_changed);
}
