import os
import subprocess
import ctypes
import pytest

def compile_module():
    src_files = ["src/drv_imu.c", "src/drv_i2c.c", "/Users/v/Documents/KTDT/packs/avr/hostmock/eaa_io_space.c"]
    cmd = ["cc", "-std=c11", "-Wall", "-fPIC", "-shared", "-I/Users/v/Documents/KTDT/packs/avr/hostmock", "-Isrc"] + src_files + ["-o", "libdrv_imu.so"]
    result = subprocess.run(cmd, capture_output=True, text=True)
    if result.returncode != 0:
        print(result.stderr)
        pytest.fail("Compilation failed")
    return ctypes.CDLL("./libdrv_imu.so")

class TWISimulator:
    def __init__(self, lib):
        self.lib = lib
        self.device_addr = 0x68
        self.registers = {0x75: 0x68}
        for i in range(256):
            if i not in self.registers:
                self.registers[i] = 0
        self.reg_ptr = 0
        self.is_first_byte = True

    def run_transaction(self):
        timeout = 1000
        while timeout > 0:
            timeout -= 1
            twcr = ctypes.c_uint8.in_dll(self.lib, "TWCR").value
            if twcr & 0x80:
                ctypes.c_uint8.in_dll(self.lib, "TWCR").value &= ~0x80

                if twcr & 0x20:
                    status = ctypes.c_uint8.in_dll(self.lib, "TWSR").value & 0xF8
                    if status == 0xF8 or status == 0x00:
                        ctypes.c_uint8.in_dll(self.lib, "TWSR").value = 0x08
                    else:
                        ctypes.c_uint8.in_dll(self.lib, "TWSR").value = 0x10
                    self.is_first_byte = True
                elif twcr & 0x10:
                    ctypes.c_uint8.in_dll(self.lib, "TWCR").value &= ~0x10
                    break
                elif twcr & 0x04:
                    status = ctypes.c_uint8.in_dll(self.lib, "TWSR").value & 0xF8
                    if status == 0xF8:
                        break
                    elif status in (0x08, 0x10):
                        sla = ctypes.c_uint8.in_dll(self.lib, "TWDR").value
                        if sla == (self.device_addr << 1):
                            ctypes.c_uint8.in_dll(self.lib, "TWSR").value = 0x18
                            self.is_first_byte = True
                        elif sla == (self.device_addr << 1 | 1):
                            ctypes.c_uint8.in_dll(self.lib, "TWSR").value = 0x40
                        else:
                            ctypes.c_uint8.in_dll(self.lib, "TWSR").value = 0x20
                    elif status in (0x18, 0x28):
                        data = ctypes.c_uint8.in_dll(self.lib, "TWDR").value
                        if self.is_first_byte:
                            self.reg_ptr = data
                            self.is_first_byte = False
                        else:
                            self.registers[self.reg_ptr] = data
                            self.reg_ptr = (self.reg_ptr + 1) & 0xFF
                        ctypes.c_uint8.in_dll(self.lib, "TWSR").value = 0x28
                    elif status in (0x40, 0x50):
                        ctypes.c_uint8.in_dll(self.lib, "TWDR").value = self.registers[self.reg_ptr]
                        self.reg_ptr = (self.reg_ptr + 1) & 0xFF
                        if twcr & 0x40:
                            ctypes.c_uint8.in_dll(self.lib, "TWSR").value = 0x50
                        else:
                            ctypes.c_uint8.in_dll(self.lib, "TWSR").value = 0x58

                ctypes.c_uint8.in_dll(self.lib, "TWCR").value |= 0x80
                self.lib.TWI_vect_fn()
            else:
                break

def test_imu():
    lib = compile_module()
    lib.imu_init.argtypes = []
    lib.imu_init.restype = None
    lib.imu_update.argtypes = []
    lib.imu_update.restype = None
    lib.imu_get_tilt_angle.argtypes = []
    lib.imu_get_tilt_angle.restype = ctypes.c_float
    lib.i2c_get_status.argtypes = []
    lib.i2c_get_status.restype = ctypes.c_int
    lib.TWI_vect_fn.argtypes = []
    lib.TWI_vect_fn.restype = None

    lib.imu_init()
    sim = TWISimulator(lib)

    # Run init sequence
    for _ in range(100):
        lib.imu_update()
        sim.run_transaction()

    # Verify correct registers were written with correct values
    assert sim.registers[0x6B] == 0x00
    assert sim.registers[0x1B] == 0x00
    assert sim.registers[0x1C] == 0x08
    assert sim.registers[0x1A] == 0x03

    # Setup mock sensor data
    # ACCEL_Z = 4100, GYRO_Y = 1310
    sim.registers[0x3F] = (4100 >> 8) & 0xFF
    sim.registers[0x40] = 4100 & 0xFF
    sim.registers[0x45] = (1310 >> 8) & 0xFF
    sim.registers[0x46] = 1310 & 0xFF

    # Run one read cycle
    for _ in range(10):
        lib.imu_update()
        sim.run_transaction()

    angle1 = lib.imu_get_tilt_angle()
    # Expected: ~0.05259
    assert abs(angle1 - 0.05259) < 0.001

    # Run another read cycle to test accumulation
    for _ in range(10):
        lib.imu_update()
        sim.run_transaction()

    angle2 = lib.imu_get_tilt_angle()
    assert angle2 > angle1

    # Simulate bus error (wrong address -> NACK)
    sim.device_addr = 0x99
    for _ in range(10):
        lib.imu_update()
        sim.run_transaction()

    angle3 = lib.imu_get_tilt_angle()
    # Angle should remain unchanged after a failed read
    assert angle3 == angle2
