#include "drv_imu.h"
#include "drv_i2c.h"
#include <math.h>
#include <stdint.h>
#include <stdbool.h>

typedef enum {
    IMU_STATE_UNINIT = 0,
    IMU_STATE_INIT_PWR_REQ,
    IMU_STATE_INIT_PWR_WAIT,
    IMU_STATE_INIT_GYRO_REQ,
    IMU_STATE_INIT_GYRO_WAIT,
    IMU_STATE_INIT_ACCEL_REQ,
    IMU_STATE_INIT_ACCEL_WAIT,
    IMU_STATE_INIT_CONFIG_REQ,
    IMU_STATE_INIT_CONFIG_WAIT,
    IMU_STATE_IDLE,
    IMU_STATE_READ_REQ,
    IMU_STATE_READ_WAIT_REG,
    IMU_STATE_READ_DATA_REQ,
    IMU_STATE_READ_WAIT_DATA
} imu_state_t;

static imu_state_t state = IMU_STATE_UNINIT;
static uint8_t i2c_buf[14];
static float current_angle = 0.0f;
static float angle_gyro = 0.0f;

void imu_init(void) {
    state = IMU_STATE_INIT_PWR_REQ;
}

void imu_start_read(void) {
    if (state == IMU_STATE_IDLE) {
        state = IMU_STATE_READ_REQ;
    }
}

float imu_get_tilt_angle(void) {
    return current_angle;
}

void imu_update(void) {
    i2c_status_t status = i2c_get_status();

    switch (state) {
        case IMU_STATE_UNINIT:
            break;

        case IMU_STATE_INIT_PWR_REQ:
            i2c_buf[0] = 0x6B; // PWR_MGMT_1
            i2c_buf[1] = 0x00; // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
            if (i2c_write_async(0x68, i2c_buf, 2)) {
                state = IMU_STATE_INIT_PWR_WAIT;
            }
            break;

        case IMU_STATE_INIT_PWR_WAIT:
            if (status == I2C_STATUS_SUCCESS) {
                state = IMU_STATE_INIT_GYRO_REQ;
            } else if (status == I2C_STATUS_ERROR) {
                state = IMU_STATE_INIT_PWR_REQ;
            }
            break;

        case IMU_STATE_INIT_GYRO_REQ:
            i2c_buf[0] = 0x1B; // GYRO_CONFIG
            i2c_buf[1] = 0x00; // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
            if (i2c_write_async(0x68, i2c_buf, 2)) {
                state = IMU_STATE_INIT_GYRO_WAIT;
            }
            break;

        case IMU_STATE_INIT_GYRO_WAIT:
            if (status == I2C_STATUS_SUCCESS) {
                state = IMU_STATE_INIT_ACCEL_REQ;
            } else if (status == I2C_STATUS_ERROR) {
                state = IMU_STATE_INIT_GYRO_REQ;
            }
            break;

        case IMU_STATE_INIT_ACCEL_REQ:
            i2c_buf[0] = 0x1C; // ACCEL_CONFIG
            i2c_buf[1] = 0x08; // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
            if (i2c_write_async(0x68, i2c_buf, 2)) {
                state = IMU_STATE_INIT_ACCEL_WAIT;
            }
            break;

        case IMU_STATE_INIT_ACCEL_WAIT:
            if (status == I2C_STATUS_SUCCESS) {
                state = IMU_STATE_INIT_CONFIG_REQ;
            } else if (status == I2C_STATUS_ERROR) {
                state = IMU_STATE_INIT_ACCEL_REQ;
            }
            break;

        case IMU_STATE_INIT_CONFIG_REQ:
            i2c_buf[0] = 0x1A; // CONFIG
            i2c_buf[1] = 0x03; // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
            if (i2c_write_async(0x68, i2c_buf, 2)) {
                state = IMU_STATE_INIT_CONFIG_WAIT;
            }
            break;

        case IMU_STATE_INIT_CONFIG_WAIT:
            if (status == I2C_STATUS_SUCCESS) {
                state = IMU_STATE_IDLE;
            } else if (status == I2C_STATUS_ERROR) {
                state = IMU_STATE_INIT_CONFIG_REQ;
            }
            break;

        case IMU_STATE_IDLE:
            break;

        case IMU_STATE_READ_REQ:
            i2c_buf[0] = 0x3B; // ACCEL_XOUT_H
            // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
            if (i2c_write_async(0x68, i2c_buf, 1)) {
                state = IMU_STATE_READ_WAIT_REG;
            }
            break;

        case IMU_STATE_READ_WAIT_REG:
            if (status == I2C_STATUS_SUCCESS) {
                state = IMU_STATE_READ_DATA_REQ;
            } else if (status == I2C_STATUS_ERROR) {
                state = IMU_STATE_IDLE;
            }
            break;

        case IMU_STATE_READ_DATA_REQ:
            if (i2c_read_async(0x68, i2c_buf, 14)) {
                state = IMU_STATE_READ_WAIT_DATA;
            }
            break;

        case IMU_STATE_READ_WAIT_DATA:
            if (status == I2C_STATUS_SUCCESS) {
                int16_t accel_z = (int16_t)((i2c_buf[4] << 8) | i2c_buf[5]);
                int16_t gyro_y = (int16_t)((i2c_buf[10] << 8) | i2c_buf[11]);

                if (accel_z > 8200) accel_z = 8200;
                if (accel_z < -8200) accel_z = -8200;

                float angle_acc = asin((float)accel_z / 8200.0) * 57.296;
                angle_gyro += (float)gyro_y * 0.000031;
                angle_gyro = angle_gyro * 0.9996 + angle_acc * 0.0004;
                current_angle = angle_gyro;

                state = IMU_STATE_IDLE;
            } else if (status == I2C_STATUS_ERROR) {
                state = IMU_STATE_IDLE;
            }
            break;
    }
}
