        if twcr & 0x10: # TWSTO
            TWCR.value = twcr & ~0x90
            break

        if twcr & 0x20: # TWSTA
            TWSR.value = 0x08 if (TWSR.value & 0xF8) not in (0x08, 0x18, 0x28, 0x40, 0x50) else 0x10
            TWCR.value = twcr & ~0x20
            lib.TWI_vect_fn()
            continue

        state = TWSR.value & 0xF8

        if state in (0x08, 0x10):
            sla = TWDR.value
            if force_nack:
                TWSR.value = 0x20
                if sla == 0xD1:
                    TWSR.value = 0x48
            elif sla == 0xD0:
                TWSR.value = 0x18
            elif sla == 0xD1:
                TWSR.value = 0x40
            else:
                TWSR.value = 0x20
            lib.TWI_vect_fn()
            continue

        elif state == 0x18:
            current_reg_ref[0] = TWDR.value
            TWSR.value = 0x28
            lib.TWI_vect_fn()
            continue

        elif state == 0x28:
            mpu_regs[current_reg_ref[0]] = TWDR.value
            current_reg_ref[0] += 1
            TWSR.value = 0x28
            lib.TWI_vect_fn()
            continue

        elif state == 0x40:
            TWDR.value = mpu_regs.get(current_reg_ref[0], 0)
            current_reg_ref[0] += 1
            if twcr & 0x40:
                TWSR.value = 0x50
            else:
                TWSR.value = 0x58
            lib.TWI_vect_fn()
            continue

        elif state == 0x50:
            TWDR.value = mpu_regs.get(current_reg_ref[0], 0)
            current_reg_ref[0] += 1
            if twcr & 0x40:
                TWSR.value = 0x50
            else:
                TWSR.value = 0x58
            lib.TWI_vect_fn()
            continue

