#include "drv_imu.h"
#include "drv_i2c.h"
#include <math.h>
#include <stddef.h>

typedef enum {
    IMU_STATE_UNINIT = 0,
    IMU_STATE_INIT_PWR,
    IMU_STATE_INIT_GYRO,
    IMU_STATE_INIT_ACCEL,
    IMU_STATE_INIT_CONFIG,
    IMU_STATE_IDLE,
    IMU_STATE_READING_REG,
    IMU_STATE_READING_DATA
} imu_state_t;

static imu_state_t imu_state = IMU_STATE_UNINIT;
static uint8_t i2c_buf[14];
static bool read_requested = false;

static float angle_gyro = 0.0f;
static float angle_acc = 0.0f;

static int32_t gyro_y_offset = 0;
static int32_t accel_z_offset = 0;

static bool is_calibrating = false;
static uint16_t calib_samples = 0;
static int32_t calib_gyro_sum = 0;
static int32_t calib_accel_sum = 0;
#define CALIB_SAMPLE_COUNT 500

static int16_t last_accel_z_raw = 0;

void imu_init(void) {
    i2c_init();
    imu_state = IMU_STATE_UNINIT;
    read_requested = false;
}

static void process_imu_data(void) {
    int16_t accel_z_raw = (int16_t)((i2c_buf[4] << 8) | i2c_buf[5]);
    int16_t gyro_y_raw = (int16_t)((i2c_buf[10] << 8) | i2c_buf[11]);

    last_accel_z_raw = accel_z_raw;

    if (is_calibrating) {
        calib_gyro_sum += gyro_y_raw;
        calib_accel_sum += accel_z_raw;
        calib_samples++;
        if (calib_samples >= CALIB_SAMPLE_COUNT) {
            is_calibrating = false;
        }
        return;
    }

    int32_t accel_z = (int32_t)accel_z_raw - accel_z_offset;
    int32_t gyro_y = (int32_t)gyro_y_raw - gyro_y_offset;

    if (accel_z > 8200) accel_z = 8200;
    if (accel_z < -8200) accel_z = -8200;

    angle_acc = asin((float)accel_z / 8200.0f) * 57.296f;
    angle_gyro += (float)gyro_y * 0.000031f;
    angle_gyro = angle_gyro * 0.9996f + angle_acc * 0.0004f;
}

void imu_update(void) {
    i2c_status_t status = i2c_get_status();
    if (status == I2C_STATUS_BUSY) {
        return;
    }

    switch (imu_state) {
        case IMU_STATE_UNINIT:
            i2c_buf[0] = 0x6B;
            i2c_buf[1] = 0x00; // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
            if (i2c_write_async(0x68, i2c_buf, 2)) {
                imu_state = IMU_STATE_INIT_PWR;
            }
            break;
        case IMU_STATE_INIT_PWR:
            if (status == I2C_STATUS_SUCCESS) {
                i2c_buf[0] = 0x1B;
                i2c_buf[1] = 0x00; // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
                if (i2c_write_async(0x68, i2c_buf, 2)) {
                    imu_state = IMU_STATE_INIT_GYRO;
                }
            } else if (status == I2C_STATUS_ERROR) {
                imu_state = IMU_STATE_UNINIT;
            }
            break;
        case IMU_STATE_INIT_GYRO:
            if (status == I2C_STATUS_SUCCESS) {
                i2c_buf[0] = 0x1C;
                i2c_buf[1] = 0x08; // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
                if (i2c_write_async(0x68, i2c_buf, 2)) {
                    imu_state = IMU_STATE_INIT_ACCEL;
                }
            } else if (status == I2C_STATUS_ERROR) {
                imu_state = IMU_STATE_UNINIT;
            }
            break;
        case IMU_STATE_INIT_ACCEL:
            if (status == I2C_STATUS_SUCCESS) {
                i2c_buf[0] = 0x1A;
                i2c_buf[1] = 0x03; // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
                if (i2c_write_async(0x68, i2c_buf, 2)) {
                    imu_state = IMU_STATE_INIT_CONFIG;
                }
            } else if (status == I2C_STATUS_ERROR) {
                imu_state = IMU_STATE_UNINIT;
            }
            break;
        case IMU_STATE_INIT_CONFIG:
            if (status == I2C_STATUS_SUCCESS) {
                imu_state = IMU_STATE_IDLE;
            } else if (status == I2C_STATUS_ERROR) {
                imu_state = IMU_STATE_UNINIT;
            }
            break;
        case IMU_STATE_IDLE:
            if (read_requested) {
                i2c_buf[0] = 0x3B; // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
                if (i2c_write_async(0x68, i2c_buf, 1)) {
                    imu_state = IMU_STATE_READING_REG;
                    read_requested = false;
                }
            }
            break;
        case IMU_STATE_READING_REG:
            if (status == I2C_STATUS_SUCCESS) {
                if (i2c_read_async(0x68, i2c_buf, 14)) {
                    imu_state = IMU_STATE_READING_DATA;
                }
            } else if (status == I2C_STATUS_ERROR) {
                imu_state = IMU_STATE_IDLE;
            }
            break;
        case IMU_STATE_READING_DATA:
            if (status == I2C_STATUS_SUCCESS) {
                process_imu_data();
                imu_state = IMU_STATE_IDLE;
            } else if (status == I2C_STATUS_ERROR) {
                imu_state = IMU_STATE_IDLE;
            }
            break;
    }
}

void imu_start_read(void) {
    read_requested = true;
}

float imu_get_tilt_angle(void) {
    return angle_gyro;
}

void imu_calibrate_begin(void) {
    is_calibrating = true;
    calib_samples = 0;
    calib_gyro_sum = 0;
    calib_accel_sum = 0;
}

bool imu_calibrate_busy(void) {
    return is_calibrating;
}

void imu_calibrate_commit(void) {
    if (calib_samples > 0) {
        gyro_y_offset = calib_gyro_sum / calib_samples;
        accel_z_offset = calib_accel_sum / calib_samples;
    }

    int32_t accel_z = (int32_t)last_accel_z_raw - accel_z_offset;
    if (accel_z > 8200) accel_z = 8200;
    if (accel_z < -8200) accel_z = -8200;

    angle_acc = asin((float)accel_z / 8200.0f) * 57.296f;
    angle_gyro = angle_acc;
}
