#include "drv_imu.h"
#include "drv_i2c.h"
#include <math.h>

// ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
// ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31

#define MPU6050_ADDR 0x68
#define CALIBRATION_SAMPLES 500

typedef enum {
    IMU_STATE_UNINIT,
    IMU_STATE_INIT_PWR,
    IMU_STATE_INIT_PWR_WAIT,
    IMU_STATE_INIT_GYRO,
    IMU_STATE_INIT_GYRO_WAIT,
    IMU_STATE_INIT_ACCEL,
    IMU_STATE_INIT_ACCEL_WAIT,
    IMU_STATE_INIT_CONFIG,
    IMU_STATE_INIT_CONFIG_WAIT,
    IMU_STATE_INIT_PTR,
    IMU_STATE_INIT_PTR_WAIT,
    IMU_STATE_IDLE,
    IMU_STATE_READING
} imu_state_t;

static imu_state_t state = IMU_STATE_UNINIT;
static uint8_t i2c_buf[14];

static float angle_gyro = 0.0f;
static float angle_acc = 0.0f;
static float gyro_offset = 0.0f;
static float acc_offset = 0.0f;

static bool is_calibrating = false;
static uint16_t calib_count = 0;
static int32_t gyro_sum = 0;
static int32_t acc_sum = 0;

void imu_init(void) {
    i2c_init();
    state = IMU_STATE_INIT_PWR;
}

static void process_imu_data(void) {
    int16_t accel_z_raw = (int16_t)(((uint16_t)i2c_buf[4] << 8) | i2c_buf[5]);
    int16_t gyro_y_raw = (int16_t)(((uint16_t)i2c_buf[10] << 8) | i2c_buf[11]);

    if (is_calibrating) {
        if (calib_count < CALIBRATION_SAMPLES) {
            gyro_sum += gyro_y_raw;
            acc_sum += accel_z_raw;
            calib_count++;
        }
    } else {
        float gyro_y = (float)gyro_y_raw - gyro_offset;
        float accel_z = (float)accel_z_raw - acc_offset;

        if (accel_z > 8200.0f) accel_z = 8200.0f;
        if (accel_z < -8200.0f) accel_z = -8200.0f;

        angle_acc = asin(accel_z / 8200.0f) * 57.296f;
        angle_gyro += gyro_y * 0.000031f;
        angle_gyro = angle_gyro * 0.9996f + angle_acc * 0.0004f;
    }
}

void imu_update(void) {
    i2c_status_t status = i2c_get_status();

    switch (state) {
        case IMU_STATE_INIT_PWR:
            i2c_buf[0] = 0x6B; // PWR_MGMT_1
            i2c_buf[1] = 0x00; // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
            if (i2c_write_async(MPU6050_ADDR, i2c_buf, 2)) {
                state = IMU_STATE_INIT_PWR_WAIT;
            }
            break;
        case IMU_STATE_INIT_PWR_WAIT:
            if (status == I2C_STATUS_SUCCESS) state = IMU_STATE_INIT_GYRO;
            else if (status == I2C_STATUS_ERROR) state = IMU_STATE_INIT_PWR;
            break;

        case IMU_STATE_INIT_GYRO:
            i2c_buf[0] = 0x1B; // GYRO_CONFIG
            i2c_buf[1] = 0x00; // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
            if (i2c_write_async(MPU6050_ADDR, i2c_buf, 2)) {
                state = IMU_STATE_INIT_GYRO_WAIT;
            }
            break;
        case IMU_STATE_INIT_GYRO_WAIT:
            if (status == I2C_STATUS_SUCCESS) state = IMU_STATE_INIT_ACCEL;
            else if (status == I2C_STATUS_ERROR) state = IMU_STATE_INIT_GYRO;
            break;

        case IMU_STATE_INIT_ACCEL:
            i2c_buf[0] = 0x1C; // ACCEL_CONFIG
            i2c_buf[1] = 0x08; // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
            if (i2c_write_async(MPU6050_ADDR, i2c_buf, 2)) {
                state = IMU_STATE_INIT_ACCEL_WAIT;
            }
            break;
        case IMU_STATE_INIT_ACCEL_WAIT:
            if (status == I2C_STATUS_SUCCESS) state = IMU_STATE_INIT_CONFIG;
            else if (status == I2C_STATUS_ERROR) state = IMU_STATE_INIT_ACCEL;
            break;

        case IMU_STATE_INIT_CONFIG:
            i2c_buf[0] = 0x1A; // CONFIG
            i2c_buf[1] = 0x03; // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
            if (i2c_write_async(MPU6050_ADDR, i2c_buf, 2)) {
                state = IMU_STATE_INIT_CONFIG_WAIT;
            }
            break;
        case IMU_STATE_INIT_CONFIG_WAIT:
            if (status == I2C_STATUS_SUCCESS) state = IMU_STATE_INIT_PTR;
            else if (status == I2C_STATUS_ERROR) state = IMU_STATE_INIT_CONFIG;
            break;

        case IMU_STATE_INIT_PTR:
            i2c_buf[0] = 0x3B; // ACCEL_XOUT_H
            if (i2c_write_async(MPU6050_ADDR, i2c_buf, 1)) {
                state = IMU_STATE_INIT_PTR_WAIT;
            }
            break;
        case IMU_STATE_INIT_PTR_WAIT:
            if (status == I2C_STATUS_SUCCESS) state = IMU_STATE_IDLE;
            else if (status == I2C_STATUS_ERROR) state = IMU_STATE_INIT_PTR;
            break;

        case IMU_STATE_READING:
            if (status == I2C_STATUS_SUCCESS) {
                process_imu_data();
                state = IMU_STATE_IDLE;
            } else if (status == I2C_STATUS_ERROR) {
                state = IMU_STATE_IDLE;
            }
            break;

        default:
            break;
    }
}

void imu_start_read(void) {
    if (state == IMU_STATE_IDLE) {
        if (i2c_read_async(MPU6050_ADDR, i2c_buf, 14)) {
            state = IMU_STATE_READING;
        }
    }
}

float imu_get_tilt_angle(void) {
    return angle_gyro;
}

void imu_calibrate_begin(void) {
    is_calibrating = true;
    calib_count = 0;
    gyro_sum = 0;
    acc_sum = 0;
}

bool imu_calibrate_busy(void) {
    return (is_calibrating && calib_count < CALIBRATION_SAMPLES);
}

void imu_calibrate_commit(void) {
    if (calib_count > 0) {
        gyro_offset = (float)gyro_sum / calib_count;
        acc_offset = (float)acc_sum / calib_count;
    } else {
        gyro_offset = 0.0f;
        acc_offset = 0.0f;
    }

    float accel_z = acc_offset;
    if (accel_z > 8200.0f) accel_z = 8200.0f;
    if (accel_z < -8200.0f) accel_z = -8200.0f;
    angle_acc = asin(accel_z / 8200.0f) * 57.296f;

    angle_gyro = angle_acc;
    is_calibrating = false;
}
