#include "drv_imu.h"
#include "drv_i2c.h"
#include <math.h>

#define MPU6050_ADDR 0x68
#define CALIBRATION_SAMPLES 500

typedef enum {
    IMU_STATE_UNINIT = 0,
    IMU_STATE_INIT_WHOAMI,
    IMU_STATE_INIT_WHOAMI_WAIT,
    IMU_STATE_INIT_WHOAMI_READ_WAIT,
    IMU_STATE_INIT_PWR,
    IMU_STATE_INIT_PWR_WAIT,
    IMU_STATE_INIT_GYRO,
    IMU_STATE_INIT_GYRO_WAIT,
    IMU_STATE_INIT_ACCEL,
    IMU_STATE_INIT_ACCEL_WAIT,
    IMU_STATE_INIT_CONFIG,
    IMU_STATE_INIT_CONFIG_WAIT,
    IMU_STATE_INIT_DELAY,
    IMU_STATE_IDLE,
    IMU_STATE_READ_ADDR_WAIT,
    IMU_STATE_READ_DATA_WAIT
} imu_state_t;

static imu_state_t imu_state = IMU_STATE_UNINIT;
static uint8_t i2c_tx_buf[2];
static uint8_t i2c_rx_buf[14];
static uint8_t init_delay_counter = 0;

static bool is_calibrating = false;
static uint16_t calib_sample_count = 0;
static int32_t calib_accel_z_sum = 0;
static int32_t calib_gyro_y_sum = 0;

static int16_t accel_z_offset = 0;
static int16_t gyro_y_offset = 0;

static float current_angle = 0.0f;

void imu_init(void) {
    i2c_init();
    imu_state = IMU_STATE_INIT_WHOAMI;
    is_calibrating = false;
    current_angle = 0.0f;
}

void imu_update(void) {
    i2c_status_t status = i2c_get_status();

    switch (imu_state) {
        case IMU_STATE_UNINIT:
            break;

        case IMU_STATE_INIT_WHOAMI:
            if (status == I2C_STATUS_IDLE || status == I2C_STATUS_SUCCESS) {
                i2c_tx_buf[0] = 0x75; // WHO_AM_I, ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
                if (i2c_write_async(MPU6050_ADDR, i2c_tx_buf, 1)) {
                    imu_state = IMU_STATE_INIT_WHOAMI_WAIT;
                }
            }
            break;

        case IMU_STATE_INIT_WHOAMI_WAIT:
            if (status == I2C_STATUS_SUCCESS) {
                if (i2c_read_async(MPU6050_ADDR, i2c_rx_buf, 1)) {
                    imu_state = IMU_STATE_INIT_WHOAMI_READ_WAIT;
                }
            } else if (status == I2C_STATUS_ERROR) {
                imu_state = IMU_STATE_INIT_WHOAMI;
            }
            break;

        case IMU_STATE_INIT_WHOAMI_READ_WAIT:
            if (status == I2C_STATUS_SUCCESS) {
                if (i2c_rx_buf[0] == 0x68) {
                    imu_state = IMU_STATE_INIT_PWR;
                } else {
                    imu_state = IMU_STATE_INIT_WHOAMI;
                }
            } else if (status == I2C_STATUS_ERROR) {
                imu_state = IMU_STATE_INIT_WHOAMI;
            }
            break;

        case IMU_STATE_INIT_PWR:
            if (status == I2C_STATUS_IDLE || status == I2C_STATUS_SUCCESS) {
                i2c_tx_buf[0] = 0x6B; // PWR_MGMT_1, ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
                i2c_tx_buf[1] = 0x00; 
                if (i2c_write_async(MPU6050_ADDR, i2c_tx_buf, 2)) {
                    imu_state = IMU_STATE_INIT_PWR_WAIT;
                }
            }
            break;

        case IMU_STATE_INIT_PWR_WAIT:
            if (status == I2C_STATUS_SUCCESS) {
                imu_state = IMU_STATE_INIT_GYRO;
            } else if (status == I2C_STATUS_ERROR) {
                imu_state = IMU_STATE_INIT_PWR;
            }
            break;

        case IMU_STATE_INIT_GYRO:
            if (status == I2C_STATUS_IDLE || status == I2C_STATUS_SUCCESS) {
                i2c_tx_buf[0] = 0x1B; // GYRO_CONFIG, ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
                i2c_tx_buf[1] = 0x00; 
                if (i2c_write_async(MPU6050_ADDR, i2c_tx_buf, 2)) {
                    imu_state = IMU_STATE_INIT_GYRO_WAIT;
                }
            }
            break;

        case IMU_STATE_INIT_GYRO_WAIT:
            if (status == I2C_STATUS_SUCCESS) {
                imu_state = IMU_STATE_INIT_ACCEL;
            } else if (status == I2C_STATUS_ERROR) {
                imu_state = IMU_STATE_INIT_GYRO;
            }
            break;

        case IMU_STATE_INIT_ACCEL:
            if (status == I2C_STATUS_IDLE || status == I2C_STATUS_SUCCESS) {
                i2c_tx_buf[0] = 0x1C; // ACCEL_CONFIG, ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
                i2c_tx_buf[1] = 0x08; 
                if (i2c_write_async(MPU6050_ADDR, i2c_tx_buf, 2)) {
                    imu_state = IMU_STATE_INIT_ACCEL_WAIT;
                }
            }
            break;

        case IMU_STATE_INIT_ACCEL_WAIT:
            if (status == I2C_STATUS_SUCCESS) {
                imu_state = IMU_STATE_INIT_CONFIG;
            } else if (status == I2C_STATUS_ERROR) {
                imu_state = IMU_STATE_INIT_ACCEL;
            }
            break;

        case IMU_STATE_INIT_CONFIG:
            if (status == I2C_STATUS_IDLE || status == I2C_STATUS_SUCCESS) {
                i2c_tx_buf[0] = 0x1A; // CONFIG, ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
                i2c_tx_buf[1] = 0x03; 
                if (i2c_write_async(MPU6050_ADDR, i2c_tx_buf, 2)) {
                    imu_state = IMU_STATE_INIT_CONFIG_WAIT;
                }
            }
            break;

        case IMU_STATE_INIT_CONFIG_WAIT:
            if (status == I2C_STATUS_SUCCESS) {
                init_delay_counter = 25; 
                imu_state = IMU_STATE_INIT_DELAY;
            } else if (status == I2C_STATUS_ERROR) {
                imu_state = IMU_STATE_INIT_CONFIG;
            }
            break;

        case IMU_STATE_INIT_DELAY:
            if (init_delay_counter > 0) {
                init_delay_counter--;
            } else {
                imu_state = IMU_STATE_IDLE;
            }
            break;

        case IMU_STATE_IDLE:
            if (status == I2C_STATUS_IDLE || status == I2C_STATUS_SUCCESS) {
                i2c_tx_buf[0] = 0x3B; // ACCEL_XOUT_H, ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
                if (i2c_write_async(MPU6050_ADDR, i2c_tx_buf, 1)) {
                    imu_state = IMU_STATE_READ_ADDR_WAIT;
                }
            }
            break;

        case IMU_STATE_READ_ADDR_WAIT:
            if (status == I2C_STATUS_SUCCESS) {
                if (i2c_read_async(MPU6050_ADDR, i2c_rx_buf, 14)) {
                    imu_state = IMU_STATE_READ_DATA_WAIT;
                }
            } else if (status == I2C_STATUS_ERROR) {
                imu_state = IMU_STATE_IDLE;
            }
            break;

        case IMU_STATE_READ_DATA_WAIT:
            if (status == I2C_STATUS_SUCCESS) {
                int16_t accel_z_raw = (int16_t)((i2c_rx_buf[4] << 8) | i2c_rx_buf[5]);
                int16_t gyro_y_raw = (int16_t)((i2c_rx_buf[10] << 8) | i2c_rx_buf[11]);

                if (is_calibrating) {
                    if (calib_sample_count < CALIBRATION_SAMPLES) {
                        calib_accel_z_sum += accel_z_raw;
                        calib_gyro_y_sum += gyro_y_raw;
                        calib_sample_count++;
                    }
                } else {
                    int16_t az = accel_z_raw - accel_z_offset;
                    int16_t gy = gyro_y_raw - gyro_y_offset;

                    float az_f = (float)az;
                    if (az_f > 8200.0f) az_f = 8200.0f;
                    if (az_f < -8200.0f) az_f = -8200.0f;

                    float angle_acc = asin(az_f / 8200.0f) * 57.296f;
                    current_angle += gy * 0.000031f;
                    current_angle = current_angle * 0.9996f + angle_acc * 0.0004f;
                }
                imu_state = IMU_STATE_IDLE;
            } else if (status == I2C_STATUS_ERROR) {
                imu_state = IMU_STATE_IDLE;
            }
            break;
    }
}

void imu_calibrate_begin(void) {
    is_calibrating = true;
    calib_sample_count = 0;
    calib_accel_z_sum = 0;
    calib_gyro_y_sum = 0;
}

bool imu_calibrate_busy(void) {
    return is_calibrating && (calib_sample_count < CALIBRATION_SAMPLES);
}

void imu_calibrate_commit(void) {
    if (calib_sample_count > 0) {
        accel_z_offset = (int16_t)(calib_accel_z_sum / calib_sample_count);
        gyro_y_offset = (int16_t)(calib_gyro_y_sum / calib_sample_count);
    }
    current_angle = 0.0f;
    is_calibrating = false;
}

float imu_get_tilt_angle(void) {
    return current_angle;
}
