#include "drv_imu.h"
#include "drv_i2c.h"
#include <math.h>

#define IMU_ADDR 0x68
#define CALIBRATION_SAMPLES 500

typedef enum {
    STATE_INIT_WHOAMI_ADDR,
    STATE_INIT_WHOAMI_ADDR_WAIT,
    STATE_INIT_WHOAMI_DATA_WAIT,
    STATE_INIT_PWR_WAIT,
    STATE_INIT_GYRO,
    STATE_INIT_GYRO_WAIT,
    STATE_INIT_ACCEL,
    STATE_INIT_ACCEL_WAIT,
    STATE_INIT_CONFIG,
    STATE_INIT_CONFIG_WAIT,
    STATE_INIT_DELAY,
    STATE_IDLE,
    STATE_READ_ADDR_WAIT,
    STATE_READ_DATA_WAIT
} imu_state_t;

static imu_state_t state = STATE_INIT_WHOAMI_ADDR;
static uint8_t i2c_buf[14];
static uint8_t delay_cnt = 0;

static float current_angle = 0.0f;
static int32_t gyro_y_offset = 0;
static int32_t accel_z_offset = 0;

static bool is_calibrating = false;
static uint16_t calib_sample_count = 0;
static int32_t calib_gyro_sum = 0;
static int32_t calib_accel_sum = 0;

void imu_init(void) {
    i2c_init();
    state = STATE_INIT_WHOAMI_ADDR;
}

static void process_imu_data(void) {
    // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
    int16_t accel_z_raw = (int16_t)((i2c_buf[4] << 8) | i2c_buf[5]);
    int16_t gyro_y_raw = (int16_t)((i2c_buf[10] << 8) | i2c_buf[11]);

    if (is_calibrating) {
        if (calib_sample_count < CALIBRATION_SAMPLES) {
            calib_gyro_sum += gyro_y_raw;
            calib_accel_sum += accel_z_raw;
            calib_sample_count++;
        }
    }

    float gyro_y_corr = (float)gyro_y_raw - (float)gyro_y_offset;
    float accel_z_corr = (float)accel_z_raw - (float)accel_z_offset;

    float az = accel_z_corr;
    if (az > 8200.0f) az = 8200.0f;
    if (az < -8200.0f) az = -8200.0f;

    float angle_acc = asinf(az / 8200.0f) * 57.296f;
    current_angle += gyro_y_corr * 0.000031f;
    current_angle = current_angle * 0.9996f + angle_acc * 0.0004f;
}

void imu_update(void) {
    i2c_status_t st = i2c_get_status();

    switch (state) {
        case STATE_INIT_WHOAMI_ADDR:
            i2c_buf[0] = 0x75; // WHO_AM_I
            // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
            if (i2c_write_async(IMU_ADDR, i2c_buf, 1)) {
                state = STATE_INIT_WHOAMI_ADDR_WAIT;
            }
            break;

        case STATE_INIT_WHOAMI_ADDR_WAIT:
            if (st == I2C_STATUS_SUCCESS) {
                if (i2c_read_async(IMU_ADDR, i2c_buf, 1)) {
                    state = STATE_INIT_WHOAMI_DATA_WAIT;
                }
            } else if (st == I2C_STATUS_ERROR) {
                state = STATE_INIT_WHOAMI_ADDR;
            }
            break;

        case STATE_INIT_WHOAMI_DATA_WAIT:
            if (st == I2C_STATUS_SUCCESS) {
                if (i2c_buf[0] == 0x68) {
                    i2c_buf[0] = 0x6B; // PWR_MGMT_1
                    i2c_buf[1] = 0x00;
                    // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
                    if (i2c_write_async(IMU_ADDR, i2c_buf, 2)) {
                        state = STATE_INIT_PWR_WAIT;
                    }
                } else {
                    state = STATE_INIT_WHOAMI_ADDR;
                }
            } else if (st == I2C_STATUS_ERROR) {
                state = STATE_INIT_WHOAMI_ADDR;
            }
            break;

        case STATE_INIT_PWR_WAIT:
            if (st == I2C_STATUS_SUCCESS) {
                state = STATE_INIT_GYRO;
            } else if (st == I2C_STATUS_ERROR) {
                state = STATE_INIT_WHOAMI_ADDR;
            }
            break;

        case STATE_INIT_GYRO:
            i2c_buf[0] = 0x1B; // GYRO_CONFIG
            i2c_buf[1] = 0x00;
            // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
            if (i2c_write_async(IMU_ADDR, i2c_buf, 2)) {
                state = STATE_INIT_GYRO_WAIT;
            }
            break;

        case STATE_INIT_GYRO_WAIT:
            if (st == I2C_STATUS_SUCCESS) {
                state = STATE_INIT_ACCEL;
            } else if (st == I2C_STATUS_ERROR) {
                state = STATE_INIT_WHOAMI_ADDR;
            }
            break;

        case STATE_INIT_ACCEL:
            i2c_buf[0] = 0x1C; // ACCEL_CONFIG
            i2c_buf[1] = 0x08;
            // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
            if (i2c_write_async(IMU_ADDR, i2c_buf, 2)) {
                state = STATE_INIT_ACCEL_WAIT;
            }
            break;

        case STATE_INIT_ACCEL_WAIT:
            if (st == I2C_STATUS_SUCCESS) {
                state = STATE_INIT_CONFIG;
            } else if (st == I2C_STATUS_ERROR) {
                state = STATE_INIT_WHOAMI_ADDR;
            }
            break;

        case STATE_INIT_CONFIG:
            i2c_buf[0] = 0x1A; // CONFIG
            i2c_buf[1] = 0x03;
            // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
            if (i2c_write_async(IMU_ADDR, i2c_buf, 2)) {
                state = STATE_INIT_CONFIG_WAIT;
            }
            break;

        case STATE_INIT_CONFIG_WAIT:
            if (st == I2C_STATUS_SUCCESS) {
                state = STATE_INIT_DELAY;
                delay_cnt = 25;
            } else if (st == I2C_STATUS_ERROR) {
                state = STATE_INIT_WHOAMI_ADDR;
            }
            break;

        case STATE_INIT_DELAY:
            if (delay_cnt > 0) {
                delay_cnt--;
            } else {
                state = STATE_IDLE;
            }
            break;

        case STATE_IDLE:
            i2c_buf[0] = 0x3B; // ACCEL_XOUT_H
            // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
            if (i2c_write_async(IMU_ADDR, i2c_buf, 1)) {
                state = STATE_READ_ADDR_WAIT;
            }
            break;

        case STATE_READ_ADDR_WAIT:
            if (st == I2C_STATUS_SUCCESS) {
                if (i2c_read_async(IMU_ADDR, i2c_buf, 14)) {
                    state = STATE_READ_DATA_WAIT;
                }
            } else if (st == I2C_STATUS_ERROR) {
                state = STATE_IDLE;
            }
            break;

        case STATE_READ_DATA_WAIT:
            if (st == I2C_STATUS_SUCCESS) {
                process_imu_data();
                state = STATE_IDLE;
            } else if (st == I2C_STATUS_ERROR) {
                state = STATE_IDLE;
            }
            break;
    }
}

void imu_calibrate_begin(void) {
    is_calibrating = true;
    calib_sample_count = 0;
    calib_gyro_sum = 0;
    calib_accel_sum = 0;
}

bool imu_calibrate_busy(void) {
    return is_calibrating && (calib_sample_count < CALIBRATION_SAMPLES);
}

void imu_calibrate_commit(void) {
    if (calib_sample_count > 0) {
        gyro_y_offset = calib_gyro_sum / calib_sample_count;
        accel_z_offset = calib_accel_sum / calib_sample_count;
    }
    is_calibrating = false;
    current_angle = 0.0f;
}

float imu_get_tilt_angle(void) {
    return current_angle;
}
