    IMU_STATE_READ_WAIT,
    IMU_STATE_READ_DONE
} imu_state_t;

static imu_state_t state = IMU_STATE_INIT_WHOAMI_REQ;
static uint8_t i2c_buf[14];

static float angle_gyro = 0.0f;
static float gyro_y_offset = 0.0f;
static float accel_z_offset = 0.0f;

static bool is_calibrating = false;
static uint16_t calib_count = 0;
static float sum_gyro_y = 0.0f;
static float sum_accel_z = 0.0f;

void imu_init(void) {
    i2c_init();
    state = IMU_STATE_INIT_WHOAMI_REQ;
    angle_gyro = 0.0f;
    gyro_y_offset = 0.0f;
    accel_z_offset = 0.0f;
    is_calibrating = false;
    calib_count = 0;
}

void imu_update(void) {
    switch (state) {
        case IMU_STATE_INIT_WHOAMI_REQ:
            if (i2c_get_status() != I2C_STATUS_BUSY) {
                i2c_buf[0] = 0x75; // WHO_AM_I
                if (i2c_write_async(MPU6050_ADDR, i2c_buf, 1)) {
                    state = IMU_STATE_INIT_WHOAMI_WAIT;
                }
            }
            break;
        case IMU_STATE_INIT_WHOAMI_WAIT:
            if (i2c_get_status() == I2C_STATUS_SUCCESS) {
                if (i2c_read_async(MPU6050_ADDR, i2c_buf, 1)) {
                    state = IMU_STATE_INIT_PWR1;
                }
            } else if (i2c_get_status() == I2C_STATUS_ERROR) {
                state = IMU_STATE_INIT_WHOAMI_REQ;
            }
            break;
        case IMU_STATE_INIT_PWR1:
            if (i2c_get_status() == I2C_STATUS_SUCCESS) {
                i2c_buf[0] = 0x6B; // PWR_MGMT_1
                i2c_buf[1] = 0x00;
                if (i2c_write_async(MPU6050_ADDR, i2c_buf, 2)) {
                    state = IMU_STATE_INIT_GYRO;
                }
            } else if (i2c_get_status() == I2C_STATUS_ERROR) {
                state = IMU_STATE_INIT_WHOAMI_REQ;
            }
            break;
        case IMU_STATE_INIT_GYRO:
            if (i2c_get_status() == I2C_STATUS_SUCCESS) {
                i2c_buf[0] = 0x1B; // GYRO_CONFIG
                i2c_buf[1] = 0x00;
                if (i2c_write_async(MPU6050_ADDR, i2c_buf, 2)) {
                    state = IMU_STATE_INIT_ACCEL;
                }
            } else if (i2c_get_status() == I2C_STATUS_ERROR) {
                state = IMU_STATE_INIT_WHOAMI_REQ;
            }
            break;
        case IMU_STATE_INIT_ACCEL:
            if (i2c_get_status() == I2C_STATUS_SUCCESS) {
                i2c_buf[0] = 0x1C; // ACCEL_CONFIG
                i2c_buf[1] = 0x08;
                if (i2c_write_async(MPU6050_ADDR, i2c_buf, 2)) {
                    state = IMU_STATE_INIT_CONFIG;
                }
            } else if (i2c_get_status() == I2C_STATUS_ERROR) {
                state = IMU_STATE_INIT_WHOAMI_REQ;
            }
            break;
        case IMU_STATE_INIT_CONFIG:
            if (i2c_get_status() == I2C_STATUS_SUCCESS) {
                i2c_buf[0] = 0x1A; // CONFIG
                i2c_buf[1] = 0x03;
                if (i2c_write_async(MPU6050_ADDR, i2c_buf, 2)) {
                    state = IMU_STATE_INIT_WAIT;
                }
            } else if (i2c_get_status() == I2C_STATUS_ERROR) {
                state = IMU_STATE_INIT_WHOAMI_REQ;
            }
            break;
        case IMU_STATE_INIT_WAIT:
            if (i2c_get_status() == I2C_STATUS_SUCCESS) {
                state = IMU_STATE_READ_START;
            } else if (i2c_get_status() == I2C_STATUS_ERROR) {
                state = IMU_STATE_INIT_WHOAMI_REQ;
            }
            break;
        case IMU_STATE_READ_START:
            if (i2c_get_status() != I2C_STATUS_BUSY) {
                i2c_buf[0] = 0x3B; // ACCEL_XOUT_H
                if (i2c_write_async(MPU6050_ADDR, i2c_buf, 1)) {
                    state = IMU_STATE_READ_WAIT;
                }
            }
            break;
        case IMU_STATE_READ_WAIT:
            if (i2c_get_status() == I2C_STATUS_SUCCESS) {
                if (i2c_read_async(MPU6050_ADDR, i2c_buf, 14)) {
                    state = IMU_STATE_READ_DONE;
                }
            } else if (i2c_get_status() == I2C_STATUS_ERROR) {
                state = IMU_STATE_READ_START;
            }
            break;
        case IMU_STATE_READ_DONE:
            break;
    }

    if (state == IMU_STATE_READ_DONE) {
        if (i2c_get_status() == I2C_STATUS_SUCCESS) {
            int16_t accel_z_raw = (int16_t)((i2c_buf[4] << 8) | i2c_buf[5]);
            int16_t gyro_y_raw = (int16_t)((i2c_buf[10] << 8) | i2c_buf[11]);

            if (is_calibrating) {
                sum_accel_z += accel_z_raw;
                sum_gyro_y += gyro_y_raw;
                calib_count++;
                if (calib_count >= 500) {
                    is_calibrating = false;
                }
            } else {
                float az = accel_z_raw - accel_z_offset;
                if (az > 8200.0f) az = 8200.0f;
                if (az < -8200.0f) az = -8200.0f;

                float angle_acc = asin(az / 8200.0f) * 57.296f;
                float gy = gyro_y_raw - gyro_y_offset;

                angle_gyro += gy * 0.0000763358f;
                angle_gyro = angle_gyro * 0.996f + angle_acc * 0.004f;
            }
            state = IMU_STATE_READ_START;
        } else if (i2c_get_status() == I2C_STATUS_ERROR) {
            state = IMU_STATE_READ_START;
        }
    }
}

void imu_calibrate_begin(void) {
    is_calibrating = true;
    calib_count = 0;
    sum_accel_z = 0.0f;
    sum_gyro_y = 0.0f;
}

bool imu_calibrate_busy(void) {
    return is_calibrating;
}

void imu_calibrate_commit(void) {
    if (calib_count > 0) {
        accel_z_offset = sum_accel_z / calib_count;
        gyro_y_offset = sum_gyro_y / calib_count;
