```file:src/drv_imu.c
#include "drv_imu.h"
#include "drv_i2c.h"
#include <math.h>

#define MPU6050_ADDR 0x68
#define CALIBRATION_SAMPLES 500

typedef enum {
    IMU_STATE_INIT_WHOAMI_REQ,
    IMU_STATE_INIT_WHOAMI_READ,
    IMU_STATE_INIT_WHOAMI_WAIT,
    IMU_STATE_INIT_PWR,
    IMU_STATE_INIT_PWR_WAIT,
    IMU_STATE_INIT_CFG,
    IMU_STATE_INIT_CFG_WAIT,
    IMU_STATE_IDLE,
    IMU_STATE_REQ_READ,
    IMU_STATE_READ_WAIT
} imu_state_t;

static imu_state_t imu_state = IMU_STATE_INIT_WHOAMI_REQ;
static uint8_t i2c_buf[14];
static float angle_gyro = 0.0f;

static bool is_calibrating = false;
static uint16_t calib_count = 0;
static int32_t sum_accel_z = 0;
static int32_t sum_gyro_y = 0;
static int16_t offset_accel_z = 0;
static int16_t offset_gyro_y = 0;

void imu_init(void) {
    // ref: ds-021, ATmega328P datasheet rev. DS40002061B, tr.222-224
    i2c_init();
    imu_state = IMU_STATE_INIT_WHOAMI_REQ;
}

static void process_imu_data(int16_t accel_z_raw, int16_t gyro_y_raw) {
    if (is_calibrating) {
        if (calib_count < CALIBRATION_SAMPLES) {
            sum_accel_z += accel_z_raw;
            sum_gyro_y += gyro_y_raw;
            calib_count++;
        }
        return;
    }

    int16_t az = accel_z_raw - offset_accel_z;
    int16_t gy = gyro_y_raw - offset_gyro_y;

    if (az > 8200) az = 8200;
    if (az < -8200) az = -8200;

    float angle_acc = asin((float)az / 8200.0f) * 57.296f;
    angle_gyro += gy * 0.000031f;
    angle_gyro = angle_gyro * 0.9996f + angle_acc * 0.0004f;
}

void imu_update(void) {
    switch (imu_state) {
        case IMU_STATE_INIT_WHOAMI_REQ:
            i2c_buf[0] = 0x75; // WHO_AM_I
            if (i2c_write_async(MPU6050_ADDR, i2c_buf, 1)) {
                imu_state = IMU_STATE_INIT_WHOAMI_READ;
            }
            break;
        case IMU_STATE_INIT_WHOAMI_READ:
            if (i2c_get_status() == I2C_STATUS_SUCCESS) {
                if (i2c_read_async(MPU6050_ADDR, i2c_buf, 1)) {
                    imu_state = IMU_STATE_INIT_WHOAMI_WAIT;
                }
            } else if (i2c_get_status() == I2C_STATUS_ERROR) {
                imu_state = IMU_STATE_INIT_WHOAMI_REQ;
            }
            break;
        case IMU_STATE_INIT_WHOAMI_WAIT:
            if (i2c_get_status() == I2C_STATUS_SUCCESS) {
                if (i2c_buf[0] == 0x68) {
                    imu_state = IMU_STATE_INIT_PWR;
                } else {
                    imu_state = IMU_STATE_INIT_WHOAMI_REQ;
                }
            } else if (i2c_get_status() == I2C_STATUS_ERROR) {
                imu_state = IMU_STATE_INIT_WHOAMI_REQ;
            }
            break;
        case IMU_STATE_INIT_PWR:
            // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
            i2c_buf[0] = 0x6B; // PWR_MGMT_1
            i2c_buf[1] = 0x00;
            if (i2c_write_async(MPU6050_ADDR, i2c_buf, 2)) {
                imu_state = IMU_STATE_INIT_PWR_WAIT;
            }
            break;
        case IMU_STATE_INIT_PWR_WAIT:
            if (i2c_get_status() == I2C_STATUS_SUCCESS) {
                imu_state = IMU_STATE_INIT_CFG;
            } else if (i2c_get_status() == I2C_STATUS_ERROR) {
                imu_state = IMU_STATE_INIT_PWR;
            }
            break;
        case IMU_STATE_INIT_CFG:
            // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
            // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
            i2c_buf[0] = 0x19; // SMPLRT_DIV
            i2c_buf[1] = 0x00; // SMPLRT_DIV
            i2c_buf[2] = 0x03; // CONFIG
            i2c_buf[3] = 0x00; // GYRO_CONFIG
            i2c_buf[4] = 0x08; // ACCEL_CONFIG
            if (i2c_write_async(MPU6050_ADDR, i2c_buf, 5)) {
                imu_state = IMU_STATE_INIT_CFG_WAIT;
            }
            break;
        case IMU_STATE_INIT_CFG_WAIT:
            if (i2c_get_status() == I2C_STATUS_SUCCESS) {
                imu_state = IMU_STATE_IDLE;
            } else if (i2c_get_status() == I2C_STATUS_ERROR) {
                imu_state = IMU_STATE_INIT_CFG;
            }
            break;
        case IMU_STATE_IDLE:
            // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
            i2c_buf[0] = 0x3B; // ACCEL_XOUT_H
            if (i2c_write_async(MPU6050_ADDR, i2c_buf, 1)) {
                imu_state = IMU_STATE_REQ_READ;
            }
            break;
        case IMU_STATE_REQ_READ:
            if (i2c_get_status() == I2C_STATUS_SUCCESS) {
                if (i2c_read_async(MPU6050_ADDR, i2c_buf, 14)) {
                    imu_state = IMU_STATE_READ_WAIT;
                }
            } else if (i2c_get_status() == I2C_STATUS_ERROR) {
                imu_state = IMU_STATE_IDLE;
            }
            break;
        case IMU_STATE_READ_WAIT:
            if (i2c_get_status() == I2C_STATUS_SUCCESS) {
                int16_t accel_z = (int16_t)((i2c_buf[4] << 8) | i2c_buf[5]);
                int16_t gyro_y  = (int16_t)((i2c_buf[10] << 8) | i2c_buf[11]);
                process_imu_data(accel_z, gyro_y);
                imu_state = IMU_STATE_IDLE;
            } else if (i2c_get_status() == I2C_STATUS_ERROR) {
                imu_state = IMU_STATE_IDLE;
            }
            break;
    }
}

float imu_get_tilt_angle(void) {
    return angle_gyro;
}

void imu_calibrate_begin(void) {
    is_calibrating = true;
    calib_count = 0;
    sum_accel_z = 0;
    sum_gyro_y = 0;
}

bool imu_calibrate_busy(void) {
    return is_calibrating && (calib_count < CALIBRATION_SAMPLES);
}

void imu_calibrate_commit(void) {
    if (calib_count > 0) {
        offset_accel_z = sum_accel_z / calib_count;
        offset_gyro_y = sum_gyro_y / calib_count;
    }
    is_calibrating = false;
    angle_gyro = 0.0f;
}
