def step_twi(lib, twi_state, mpu_regs):
    TWCR = ctypes.c_uint8.in_dll(lib, "TWCR")
    TWDR = ctypes.c_uint8.in_dll(lib, "TWDR")
    TWSR = ctypes.c_uint8.in_dll(lib, "TWSR")

    if not (TWCR.value & 0x80):
        return False

    twcr_val = TWCR.value

    if twcr_val & 0x20:
        if twi_state['status'] == 'IDLE':
            TWSR.value = 0x08
        else:
            TWSR.value = 0x10
        twi_state['status'] = 'START'
        twi_state['write_buf'] = []
        lib.TWI_vect_fn()
        return True

    if twcr_val & 0x10:
        if twi_state['write_buf']:
            reg = twi_state['write_buf'][0]
            for i, val in enumerate(twi_state['write_buf'][1:]):
                mpu_regs[reg + i] = val
            twi_state['current_reg'] = reg + len(twi_state['write_buf']) - 1
            if len(twi_state['write_buf']) == 1:
                twi_state['current_reg'] = reg
        twi_state['status'] = 'IDLE'
        TWCR.value &= ~0x10
        return True

    if twi_state['status'] in ['START', 'REP_START']:
        sla = TWDR.value
        if sla == 0xD0:
            TWSR.value = 0x18
            twi_state['status'] = 'MT_DATA'
        elif sla == 0xD1:
            TWSR.value = 0x40
            twi_state['status'] = 'MR_DATA'
            reg = twi_state.get('current_reg', 0)
            twi_state['read_data'] = []
            for i in range(14):
                twi_state['read_data'].append(mpu_regs.get(reg + i, 0))
            twi_state['read_idx'] = 0
        else:
            TWSR.value = 0x20
        lib.TWI_vect_fn()
        return True

    if twi_state['status'] == 'MT_DATA':
        data = TWDR.value
        twi_state['write_buf'].append(data)
        TWSR.value = 0x28
        lib.TWI_vect_fn()
        return True

    if twi_state['status'] == 'MR_DATA':
        if twi_state['read_idx'] < len(twi_state['read_data']):
            TWDR.value = twi_state['read_data'][twi_state['read_idx']]
            twi_state['read_idx'] += 1
        else:
            TWDR.value = 0x00

        if twcr_val & 0x40:
            TWSR.value = 0x50
        else:
            TWSR.value = 0x58
        lib.TWI_vect_fn()
        return True

    return False

def run_twi(lib, twi_state, mpu_regs):
    while step_twi(lib, twi_state, mpu_regs):
        pass

