#include "drv_imu.h"
#include "drv_i2c.h"
#include <math.h>

#define MPU6050_ADDR 0x68
#define NUM_CALIB_SAMPLES 500

typedef enum {
    IMU_STATE_INIT_START = 0,
    IMU_STATE_INIT_WHOAMI_REQ,
    IMU_STATE_INIT_WHOAMI_WAIT,
    IMU_STATE_INIT_PWR_REQ,
    IMU_STATE_INIT_PWR,
    IMU_STATE_INIT_SMPLRT,
    IMU_STATE_INIT_CONFIG,
    IMU_STATE_INIT_GYRO,
    IMU_STATE_INIT_ACCEL,
    IMU_STATE_IDLE,
    IMU_STATE_READ_REQ,
    IMU_STATE_READ_WAIT
} imu_state_t;

static imu_state_t state = IMU_STATE_INIT_START;
static uint8_t i2c_buf[14];
static float angle_gyro = 0.0f;

static bool calibrating = false;
static uint16_t calib_count = 0;
static int32_t accel_z_sum = 0;
static int32_t gyro_y_sum = 0;

static int16_t accel_z_offset = 0;
static int16_t gyro_y_offset = 0;

void imu_init(void) {
    i2c_init();
    state = IMU_STATE_INIT_START;
}

void imu_update(void) {
    i2c_status_t status = i2c_get_status();

    if (status == I2C_STATUS_BUSY) {
        return;
    }

    switch (state) {
        case IMU_STATE_INIT_START:
            i2c_buf[0] = 0x75; // WHO_AM_I
            if (i2c_write_async(MPU6050_ADDR, i2c_buf, 1)) {
                state = IMU_STATE_INIT_WHOAMI_REQ;
            }
            break;

        case IMU_STATE_INIT_WHOAMI_REQ:
            if (status == I2C_STATUS_SUCCESS) {
                if (i2c_read_async(MPU6050_ADDR, i2c_buf, 1)) {
                    state = IMU_STATE_INIT_WHOAMI_WAIT;
                }
            } else if (status == I2C_STATUS_ERROR) {
                state = IMU_STATE_INIT_START;
            }
            break;

        case IMU_STATE_INIT_WHOAMI_WAIT:
            if (status == I2C_STATUS_SUCCESS) {
                if (i2c_buf[0] == 0x68) { // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
                    state = IMU_STATE_INIT_PWR_REQ;
                } else {
                    state = IMU_STATE_INIT_START;
                }
            } else if (status == I2C_STATUS_ERROR) {
                state = IMU_STATE_INIT_START;
            }
            break;

        case IMU_STATE_INIT_PWR_REQ:
            i2c_buf[0] = 0x6B;
            i2c_buf[1] = 0x00; // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
            if (i2c_write_async(MPU6050_ADDR, i2c_buf, 2)) {
                state = IMU_STATE_INIT_PWR;
            }
            break;

        case IMU_STATE_INIT_PWR:
            if (status == I2C_STATUS_SUCCESS) {
                i2c_buf[0] = 0x19;
                i2c_buf[1] = 0x00; // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
                if (i2c_write_async(MPU6050_ADDR, i2c_buf, 2)) {
                    state = IMU_STATE_INIT_SMPLRT;
                }
            } else if (status == I2C_STATUS_ERROR) {
                state = IMU_STATE_INIT_START;
            }
            break;

        case IMU_STATE_INIT_SMPLRT:
            if (status == I2C_STATUS_SUCCESS) {
                i2c_buf[0] = 0x1A;
                i2c_buf[1] = 0x03; // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
                if (i2c_write_async(MPU6050_ADDR, i2c_buf, 2)) {
                    state = IMU_STATE_INIT_CONFIG;
                }
            } else if (status == I2C_STATUS_ERROR) {
                state = IMU_STATE_INIT_START;
            }
            break;

        case IMU_STATE_INIT_CONFIG:
            if (status == I2C_STATUS_SUCCESS) {
                i2c_buf[0] = 0x1B;
                i2c_buf[1] = 0x00; // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
                if (i2c_write_async(MPU6050_ADDR, i2c_buf, 2)) {
                    state = IMU_STATE_INIT_GYRO;
                }
            } else if (status == I2C_STATUS_ERROR) {
                state = IMU_STATE_INIT_START;
            }
            break;

        case IMU_STATE_INIT_GYRO:
            if (status == I2C_STATUS_SUCCESS) {
                i2c_buf[0] = 0x1C;
                i2c_buf[1] = 0x08; // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
                if (i2c_write_async(MPU6050_ADDR, i2c_buf, 2)) {
                    state = IMU_STATE_INIT_ACCEL;
                }
            } else if (status == I2C_STATUS_ERROR) {
                state = IMU_STATE_INIT_START;
            }
            break;

        case IMU_STATE_INIT_ACCEL:
            if (status == I2C_STATUS_SUCCESS) {
                state = IMU_STATE_IDLE;
            } else if (status == I2C_STATUS_ERROR) {
                state = IMU_STATE_INIT_START;
            }
            break;

        case IMU_STATE_IDLE:
            i2c_buf[0] = 0x3B; // ACCEL_XOUT_H
            if (i2c_write_async(MPU6050_ADDR, i2c_buf, 1)) {
                state = IMU_STATE_READ_REQ;
            }
            break;

        case IMU_STATE_READ_REQ:
            if (status == I2C_STATUS_SUCCESS) {
                if (i2c_read_async(MPU6050_ADDR, i2c_buf, 14)) {
                    state = IMU_STATE_READ_WAIT;
                }
            } else if (status == I2C_STATUS_ERROR) {
                state = IMU_STATE_IDLE;
            }
            break;

        case IMU_STATE_READ_WAIT:
            if (status == I2C_STATUS_SUCCESS) {
                int16_t accel_z_raw = (int16_t)((i2c_buf[4] << 8) | i2c_buf[5]);
                int16_t gyro_y_raw = (int16_t)((i2c_buf[10] << 8) | i2c_buf[11]);

                if (calibrating) {
                    if (calib_count < NUM_CALIB_SAMPLES) {
                        accel_z_sum += accel_z_raw;
                        gyro_y_sum += gyro_y_raw;
                        calib_count++;
                    }
                } else {
                    int16_t az = accel_z_raw - accel_z_offset;
                    int16_t gy = gyro_y_raw - gyro_y_offset;

                    float az_f = (float)az;
                    if (az_f > 8200.0f) az_f = 8200.0f;
                    if (az_f < -8200.0f) az_f = -8200.0f;

                    float angle_acc = asin(az_f / 8200.0f) * 57.296f;
                    angle_gyro += gy * 0.000031f;
                    angle_gyro = angle_gyro * 0.9996f + angle_acc * 0.0004f;
                }
                state = IMU_STATE_IDLE;
            } else if (status == I2C_STATUS_ERROR) {
                state = IMU_STATE_IDLE;
            }
            break;
    }
}

float imu_get_tilt_angle(void) {
    return angle_gyro;
}

void imu_calibrate_begin(void) {
    calibrating = true;
    calib_count = 0;
    accel_z_sum = 0;
    gyro_y_sum = 0;
}

bool imu_calibrate_busy(void) {
    return calibrating && (calib_count < NUM_CALIB_SAMPLES);
}

void imu_calibrate_commit(void) {
    if (calib_count > 0) {
        accel_z_offset = (int16_t)(accel_z_sum / calib_count);
        gyro_y_offset = (int16_t)(gyro_y_sum / calib_count);
    }
    calibrating = false;
    angle_gyro = 0.0f;
}
