```file:src/drv_imu.c
#include "drv_imu.h"
#include "drv_i2c.h"
#include <math.h>
#include <stddef.h>

#define MPU6050_ADDR 0x68

// Registers
#define REG_SMPLRT_DIV 0x19
#define REG_CONFIG 0x1A
#define REG_GYRO_CONFIG 0x1B
#define REG_ACCEL_CONFIG 0x1C
#define REG_ACCEL_XOUT_H 0x3B
#define REG_PWR_MGMT_1 0x6B

typedef enum {
    STATE_INIT_PWR_W = 0,
    STATE_INIT_PWR_WAIT,
    STATE_INIT_SMPLRT_W,
    STATE_INIT_SMPLRT_WAIT,
    STATE_INIT_CONFIG_W,
    STATE_INIT_CONFIG_WAIT,
    STATE_INIT_GYRO_W,
    STATE_INIT_GYRO_WAIT,
    STATE_INIT_ACCEL_W,
    STATE_INIT_ACCEL_WAIT,
    STATE_IDLE,
    STATE_READ_REG_WAIT,
    STATE_READ_DATA_R,
    STATE_READ_DATA_WAIT
} imu_state_t;

static imu_state_t state = STATE_INIT_PWR_W;
static uint8_t i2c_buf[14];

static float current_angle = 0.0f;

// Calibration
#define CALIB_SAMPLES 500
static bool calib_busy = false;
static uint16_t calib_count = 0;
static int32_t accel_z_sum = 0;
static int32_t gyro_y_sum = 0;
static int16_t accel_z_offset = 0;
static int16_t gyro_y_offset = 0;

void imu_init(void) {
    i2c_init();
    state = STATE_INIT_PWR_W;
    current_angle = 0.0f;
    calib_busy = false;
    calib_count = 0;
    accel_z_sum = 0;
    gyro_y_sum = 0;
    accel_z_offset = 0;
    gyro_y_offset = 0;
}

void imu_update(void) {
    i2c_status_t status = i2c_get_status();

    if (status == I2C_STATUS_BUSY) {
        return;
    }

    switch (state) {
        case STATE_INIT_PWR_W:
            i2c_buf[0] = REG_PWR_MGMT_1;
            i2c_buf[1] = 0x00; // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
            if (i2c_write_async(MPU6050_ADDR, i2c_buf, 2)) {
                state = STATE_INIT_PWR_WAIT;
            }
            break;
        case STATE_INIT_PWR_WAIT:
            if (status == I2C_STATUS_SUCCESS) state = STATE_INIT_SMPLRT_W;
            else if (status == I2C_STATUS_ERROR) state = STATE_INIT_PWR_W;
            break;

        case STATE_INIT_SMPLRT_W:
            i2c_buf[0] = REG_SMPLRT_DIV;
            i2c_buf[1] = 0x00; // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
            if (i2c_write_async(MPU6050_ADDR, i2c_buf, 2)) {
                state = STATE_INIT_SMPLRT_WAIT;
            }
            break;
        case STATE_INIT_SMPLRT_WAIT:
            if (status == I2C_STATUS_SUCCESS) state = STATE_INIT_CONFIG_W;
            else if (status == I2C_STATUS_ERROR) state = STATE_INIT_SMPLRT_W;
            break;

        case STATE_INIT_CONFIG_W:
            i2c_buf[0] = REG_CONFIG;
            i2c_buf[1] = 0x03; // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
            if (i2c_write_async(MPU6050_ADDR, i2c_buf, 2)) {
                state = STATE_INIT_CONFIG_WAIT;
            }
            break;
        case STATE_INIT_CONFIG_WAIT:
            if (status == I2C_STATUS_SUCCESS) state = STATE_INIT_GYRO_W;
            else if (status == I2C_STATUS_ERROR) state = STATE_INIT_CONFIG_W;
            break;

        case STATE_INIT_GYRO_W:
            i2c_buf[0] = REG_GYRO_CONFIG;
            i2c_buf[1] = 0x00; // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
            if (i2c_write_async(MPU6050_ADDR, i2c_buf, 2)) {
                state = STATE_INIT_GYRO_WAIT;
            }
            break;
        case STATE_INIT_GYRO_WAIT:
            if (status == I2C_STATUS_SUCCESS) state = STATE_INIT_ACCEL_W;
            else if (status == I2C_STATUS_ERROR) state = STATE_INIT_GYRO_W;
            break;

        case STATE_INIT_ACCEL_W:
            i2c_buf[0] = REG_ACCEL_CONFIG;
            i2c_buf[1] = 0x08; // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
            if (i2c_write_async(MPU6050_ADDR, i2c_buf, 2)) {
                state = STATE_INIT_ACCEL_WAIT;
            }
            break;
        case STATE_INIT_ACCEL_WAIT:
            if (status == I2C_STATUS_SUCCESS) state = STATE_IDLE;
            else if (status == I2C_STATUS_ERROR) state = STATE_INIT_ACCEL_W;
            break;

        case STATE_IDLE:
            i2c_buf[0] = REG_ACCEL_XOUT_H; // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
            if (i2c_write_async(MPU6050_ADDR, i2c_buf, 1)) {
                state = STATE_READ_REG_WAIT;
            }
            break;
        case STATE_READ_REG_WAIT:
            if (status == I2C_STATUS_SUCCESS) state = STATE_READ_DATA_R;
            else if (status == I2C_STATUS_ERROR) state = STATE_IDLE;
            break;

        case STATE_READ_DATA_R:
            if (i2c_read_async(MPU6050_ADDR, i2c_buf, 14)) {
                state = STATE_READ_DATA_WAIT;
            }
            break;
        case STATE_READ_DATA_WAIT:
            if (status == I2C_STATUS_SUCCESS) {
                int16_t accel_z_raw = (int16_t)((i2c_buf[4] << 8) | i2c_buf[5]);
                int16_t gyro_y_raw = (int16_t)((i2c_buf[10] << 8) | i2c_buf[11]);

                if (calib_busy) {
                    accel_z_sum += accel_z_raw;
                    gyro_y_sum += gyro_y_raw;
                    calib_count++;
                } else {
                    int16_t az = accel_z_raw - accel_z_offset;
                    int16_t gy = gyro_y_raw - gyro_y_offset;

                    float az_f = (float)az;
                    if (az_f > 8200.0f) az_f = 8200.0f;
                    if (az_f < -8200.0f) az_f = -8200.0f;

                    float angle_acc = asin(az_f / 8200.0f) * 57.296f;
                    current_angle += gy * 0.000031f;
                    current_angle = current_angle * 0.9996f + angle_acc * 0.0004f;
                }
                state = STATE_IDLE;
            } else if (status == I2C_STATUS_ERROR) {
                state = STATE_IDLE;
            }
            break;
    }
}

float imu_get_tilt_angle(void) {
    return current_angle;
}

void imu_calibrate_begin(void) {
    calib_busy = true;
    calib_count = 0;
    accel_z_sum = 0;
    gyro_y_sum = 0;
}

bool imu_calibrate_busy(void) {
    return calib_busy;
}

void imu_calibrate_commit(void) {
    if (calib_count > 0) {
        accel_z_offset = accel_z_sum / calib_count;
        gyro_y_offset = gyro_y_sum / calib_count;
    } else {
        accel_z_offset = 0;
        gyro_y_offset = 0;
    }
    current_angle = 0.0f;
    calib_busy = false;
}
