```file:src/drv_imu.c
#include "drv_imu.h"
#include "drv_i2c.h"
#include <math.h>
#include <stdint.h>
#include <stdbool.h>

#define MPU6050_ADDR 0x68
#define CALIB_SAMPLES 500

typedef enum {
    STATE_INIT_WHOAMI_REQ,
    STATE_INIT_WHOAMI_READ,
    STATE_INIT_WHOAMI_CHECK,
    STATE_INIT_PWR,
    STATE_INIT_CFG,
    STATE_REQ_READ,
    STATE_READING,
    STATE_READING_WAIT
} imu_state_t;

static imu_state_t state = STATE_INIT_WHOAMI_REQ;
static uint8_t i2c_buf[14];

static bool calibrating = false;
static int32_t accel_z_sum = 0;
static int32_t gyro_y_sum = 0;
static uint16_t calib_count = 0;

static int16_t accel_z_offset = 0;
static int16_t gyro_y_offset = 0;

static float angle_gyro = 0.0f;

void imu_init(void) {
    i2c_init();
    state = STATE_INIT_WHOAMI_REQ;
    calibrating = false;
    accel_z_sum = 0;
    gyro_y_sum = 0;
    calib_count = 0;
    accel_z_offset = 0;
    gyro_y_offset = 0;
    angle_gyro = 0.0f;
}

static void process_data(void) {
    // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
    int16_t accel_z_raw = (int16_t)((i2c_buf[4] << 8) | i2c_buf[5]);
    int16_t gyro_y_raw = (int16_t)((i2c_buf[10] << 8) | i2c_buf[11]);

    if (calibrating) {
        if (calib_count < CALIB_SAMPLES) {
            accel_z_sum += accel_z_raw;
            gyro_y_sum += gyro_y_raw;
            calib_count++;
        }
    } else {
        float az = (float)(accel_z_raw - accel_z_offset);
        if (az > 8200.0f) az = 8200.0f;
        if (az < -8200.0f) az = -8200.0f;

        float angle_acc = asin(az / 8200.0f) * 57.296f;

        float gy = (float)(gyro_y_raw - gyro_y_offset);
        angle_gyro += gy * 0.000031f;
        angle_gyro = angle_gyro * 0.9996f + angle_acc * 0.0004f;
    }
}

void imu_update(void) {
    i2c_status_t status = i2c_get_status();

    if (status == I2C_STATUS_BUSY) {
        return;
    }

    switch (state) {
        case STATE_INIT_WHOAMI_REQ:
            // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
            i2c_buf[0] = 0x75;
            if (i2c_write_async(MPU6050_ADDR, i2c_buf, 1)) {
                state = STATE_INIT_WHOAMI_READ;
            }
            break;

        case STATE_INIT_WHOAMI_READ:
            if (status == I2C_STATUS_SUCCESS) {
                if (i2c_read_async(MPU6050_ADDR, i2c_buf, 1)) {
                    state = STATE_INIT_WHOAMI_CHECK;
                }
            } else if (status == I2C_STATUS_ERROR) {
                state = STATE_INIT_WHOAMI_REQ;
            }
            break;

        case STATE_INIT_WHOAMI_CHECK:
            if (status == I2C_STATUS_SUCCESS) {
                if (i2c_buf[0] == 0x68) {
                    // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
                    i2c_buf[0] = 0x6B;
                    i2c_buf[1] = 0x00;
                    if (i2c_write_async(MPU6050_ADDR, i2c_buf, 2)) {
                        state = STATE_INIT_CFG;
                    } else {
                        state = STATE_INIT_PWR;
                    }
                } else {
                    state = STATE_INIT_WHOAMI_REQ;
                }
            } else if (status == I2C_STATUS_ERROR) {
                state = STATE_INIT_WHOAMI_REQ;
            }
            break;

        case STATE_INIT_PWR:
            // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
            i2c_buf[0] = 0x6B;
            i2c_buf[1] = 0x00;
            if (i2c_write_async(MPU6050_ADDR, i2c_buf, 2)) {
                state = STATE_INIT_CFG;
            }
            break;

        case STATE_INIT_CFG:
            if (status == I2C_STATUS_SUCCESS || status == I2C_STATUS_IDLE) {
                // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
                // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
                i2c_buf[0] = 0x19;
                i2c_buf[1] = 0x00;
                i2c_buf[2] = 0x03;
                i2c_buf[3] = 0x00;
                i2c_buf[4] = 0x08;
                if (i2c_write_async(MPU6050_ADDR, i2c_buf, 5)) {
                    state = STATE_REQ_READ;
                }
            } else if (status == I2C_STATUS_ERROR) {
                state = STATE_INIT_PWR;
            }
            break;

        case STATE_REQ_READ:
            // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
            i2c_buf[0] = 0x3B;
            if (i2c_write_async(MPU6050_ADDR, i2c_buf, 1)) {
                state = STATE_READING;
            }
            break;

        case STATE_READING:
            if (status == I2C_STATUS_SUCCESS) {
                if (i2c_read_async(MPU6050_ADDR, i2c_buf, 14)) {
                    state = STATE_READING_WAIT;
                }
            } else if (status == I2C_STATUS_ERROR) {
                state = STATE_REQ_READ;
            }
            break;

        case STATE_READING_WAIT:
            if (status == I2C_STATUS_SUCCESS) {
                process_data();
                i2c_buf[0] = 0x3B;
                if (i2c_write_async(MPU6050_ADDR, i2c_buf, 1)) {
                    state = STATE_READING;
                } else {
                    state = STATE_REQ_READ;
                }
            } else if (status == I2C_STATUS_ERROR) {
                state = STATE_REQ_READ;
            }
            break;
    }
}

float imu_get_tilt_angle(void) {
    return angle_gyro;
}

void imu_calibrate_begin(void) {
    accel_z_sum = 0;
    gyro_y_sum = 0;
    calib_count = 0;
    calibrating = true;
}

bool imu_calibrate_busy(void) {
    return calibrating && (calib_count < CALIB_SAMPLES);
}

void imu_calibrate_commit(void) {
    if (calib_count > 0) {
        accel_z_offset = (int16_t)(accel_z_sum / calib_count);
        gyro_y_offset = (int16_t)(gyro_y_sum / calib_count);
    }
    angle_gyro = 0.0f;
    calibrating = false;
}
