#include "drv_i2c.h"
#include <avr/io.h>
#include <avr/interrupt.h>
#include <stddef.h>

#define I2C_TIMEOUT_TICKS 5

static volatile i2c_status_t i2c_status = I2C_STATUS_IDLE;
static volatile uint8_t i2c_addr = 0;
static volatile uint8_t *i2c_buf = NULL;
static volatile uint8_t i2c_len = 0;
static volatile uint8_t i2c_idx = 0;
static volatile uint8_t i2c_ticks = 0;

void i2c_init(void) {
    uint8_t sreg = SREG;
    cli();

    // ref: ds-021, ATmega328P datasheet rev. DS40002061B, tr.222-224
    TWSR = 0x00;
    TWBR = 12;

    // Phát STOP nếu đang giữ bus
    TWCR = (1 << TWEN) | (1 << TWINT) | (1 << TWSTO);

    i2c_status = I2C_STATUS_IDLE;
    i2c_buf = NULL;
    i2c_len = 0;
    i2c_idx = 0;
    i2c_ticks = 0;

    // ref: ds-023, ATmega328P datasheet rev. DS40002061B, tr.235-240
    // Không cấu hình TWAR/TWAMR vì chỉ hoạt động ở chế độ master

    SREG = sreg;
}

bool i2c_write_async(uint8_t addr, const uint8_t *data, uint8_t len) {
    uint8_t sreg = SREG;
    cli();
    if (i2c_status == I2C_STATUS_BUSY) {
        SREG = sreg;
        return false;
    }
    i2c_status = I2C_STATUS_BUSY;
    i2c_addr = addr << 1;
    i2c_buf = (uint8_t *)data;
    i2c_len = len;
    i2c_idx = 0;
    i2c_ticks = 0;

    // Phát START
    // ref: ds-021, ATmega328P datasheet rev. DS40002061B, tr.222-224
    TWCR = (1 << TWEN) | (1 << TWIE) | (1 << TWINT) | (1 << TWSTA);
    SREG = sreg;
    return true;
}

bool i2c_read_async(uint8_t addr, uint8_t *data, uint8_t len) {
    uint8_t sreg = SREG;
    cli();
    if (i2c_status == I2C_STATUS_BUSY) {
        SREG = sreg;
        return false;
    }
    i2c_status = I2C_STATUS_BUSY;
    i2c_addr = (addr << 1) | 1;
    i2c_buf = data;
    i2c_len = len;
    i2c_idx = 0;
    i2c_ticks = 0;

    // Phát START
    // ref: ds-021, ATmega328P datasheet rev. DS40002061B, tr.222-224
    TWCR = (1 << TWEN) | (1 << TWIE) | (1 << TWINT) | (1 << TWSTA);
    SREG = sreg;
    return true;
}

i2c_status_t i2c_get_status(void) {
    uint8_t sreg = SREG;
    cli();
    i2c_status_t st = i2c_status;
    SREG = sreg;
    return st;
}

void i2c_tick(void) {
    uint8_t sreg = SREG;
    cli();
    if (i2c_status == I2C_STATUS_BUSY) {
        i2c_ticks++;
        if (i2c_ticks >= I2C_TIMEOUT_TICKS) {
            // Phát STOP
            // ref: ds-021, ATmega328P datasheet rev. DS40002061B, tr.222-224
            TWCR = (1 << TWEN) | (1 << TWINT) | (1 << TWSTO);
            i2c_status = I2C_STATUS_ERROR;
        }
    }
    SREG = sreg;
}

ISR(TWI_vect) {
    // ref: ds-022, ATmega328P datasheet rev. DS40002061B, tr.228-232
    uint8_t status = TWSR & 0xF8;
    i2c_ticks = 0;

    switch (status) {
        case 0x08: // Đã phát START
        case 0x10: // Đã phát START lặp lại
            TWDR = i2c_addr;
            TWCR = (1 << TWEN) | (1 << TWIE) | (1 << TWINT);
            break;

        case 0x18: // Đã gửi SLA+W, nhận ACK
        case 0x28: // Đã gửi byte dữ liệu, nhận ACK
            if (i2c_idx < i2c_len) {
                TWDR = i2c_buf[i2c_idx++];
                TWCR = (1 << TWEN) | (1 << TWIE) | (1 << TWINT);
            } else {
                // Xong, phát STOP
                TWCR = (1 << TWEN) | (1 << TWIE) | (1 << TWINT) | (1 << TWSTO);
                i2c_status = I2C_STATUS_SUCCESS;
            }
            break;

        case 0x40: // Đã gửi SLA+R, nhận ACK
            if (i2c_len > 1) {
                // Trả ACK cho byte tiếp theo
                TWCR = (1 << TWEN) | (1 << TWIE) | (1 << TWINT) | (1 << TWEA);
            } else {
                // Trả NACK cho byte cuối
                TWCR = (1 << TWEN) | (1 << TWIE) | (1 << TWINT);
            }
            break;

        case 0x50: // Đã nhận byte dữ liệu, đã trả ACK
            i2c_buf[i2c_idx++] = TWDR;
            if (i2c_idx < i2c_len - 1) {
                TWCR = (1 << TWEN) | (1 << TWIE) | (1 << TWINT) | (1 << TWEA);
            } else {
                TWCR = (1 << TWEN) | (1 << TWIE) | (1 << TWINT);
            }
            break;

        case 0x58: // Đã nhận byte dữ liệu, đã trả NACK
            i2c_buf[i2c_idx++] = TWDR;
            // Phát STOP
            TWCR = (1 << TWEN) | (1 << TWIE) | (1 << TWINT) | (1 << TWSTO);
            i2c_status = I2C_STATUS_SUCCESS;
            break;

        case 0x20: // Đã gửi SLA+W, nhận NACK
        case 0x38: // Mất quyền trọng tài
        default:
            // Lỗi, phát STOP
            TWCR = (1 << TWEN) | (1 << TWIE) | (1 << TWINT) | (1 << TWSTO);
            i2c_status = I2C_STATUS_ERROR;
            break;
    }
}
