    data = (ctypes.c_uint8 * 1)(0)
    assert i2c_lib.i2c_write_async(0x50, data, 1) == True

    TWCR = get_reg(i2c_lib, "TWCR")

    for _ in range(4):
        i2c_lib.i2c_tick()
        assert i2c_lib.i2c_get_status() == 1 # BUSY

    i2c_lib.i2c_tick()
    assert i2c_lib.i2c_get_status() == 3 # ERROR
    assert (TWCR.value & (1 << 4)) != 0 # TWSTO

    assert i2c_lib.i2c_write_async(0x50, data, 1) == True
