```file:src/drv_imu.c
#include "drv_imu.h"
#include "drv_i2c.h"
#include <stdint.h>
#include <math.h>

#define MPU6050_ADDR 0x68
#define CALIBRATION_SAMPLES 500

typedef enum {
    IMU_STATE_INIT_START,
    IMU_STATE_INIT_PWR_WAIT,
    IMU_STATE_INIT_GYRO_WAIT,
    IMU_STATE_INIT_ACCEL_WAIT,
    IMU_STATE_INIT_CONFIG_WAIT,
    IMU_STATE_INIT_DELAY,
    IMU_STATE_IDLE,
    IMU_STATE_READ_REQ_WAIT,
    IMU_STATE_READ_DATA_WAIT
} imu_state_t;

static imu_state_t current_state = IMU_STATE_INIT_START;
static uint8_t i2c_buf[14];
static uint8_t init_wait_counter = 0;

static bool is_calibrating = false;
static uint16_t calib_count = 0;
static int32_t accel_z_sum = 0;
static int32_t gyro_y_sum = 0;

static int16_t accel_z_offset = 0;
static int16_t gyro_y_offset = 0;

static float angle_gyro = 0.0f;

void imu_init(void) {
    i2c_init();
    current_state = IMU_STATE_INIT_START;
}

static void process_imu_data(void) {
    int16_t accel_z_raw = (int16_t)((i2c_buf[4] << 8) | i2c_buf[5]);
    int16_t gyro_y_raw = (int16_t)((i2c_buf[10] << 8) | i2c_buf[11]);

    if (is_calibrating) {
        if (calib_count < CALIBRATION_SAMPLES) {
            accel_z_sum += accel_z_raw;
            gyro_y_sum += gyro_y_raw;
            calib_count++;
        }
        return;
    }

    int16_t accel_z = accel_z_raw - accel_z_offset;
    int16_t gyro_y = gyro_y_raw - gyro_y_offset;

    if (accel_z > 8200) accel_z = 8200;
    if (accel_z < -8200) accel_z = -8200;

    float angle_acc = asin((float)accel_z / 8200.0f) * 57.296f;
    angle_gyro += (float)gyro_y * 0.000031f;
    angle_gyro = angle_gyro * 0.9996f + angle_acc * 0.0004f;
}

void imu_update(void) {
    i2c_status_t status = i2c_get_status();
    if (status == I2C_BUSY) return;

    switch (current_state) {
        case IMU_STATE_INIT_START:
            i2c_buf[0] = 0x6B; // PWR_MGMT_1
            i2c_buf[1] = 0x00; // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
            if (i2c_write_async(MPU6050_ADDR, i2c_buf, 2)) {
                current_state = IMU_STATE_INIT_PWR_WAIT;
            }
            break;
        case IMU_STATE_INIT_PWR_WAIT:
            if (status == I2C_SUCCESS) {
                i2c_buf[0] = 0x1B; // GYRO_CONFIG
                i2c_buf[1] = 0x00; // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
                if (i2c_write_async(MPU6050_ADDR, i2c_buf, 2)) {
                    current_state = IMU_STATE_INIT_GYRO_WAIT;
                }
            } else if (status == I2C_ERROR) {
                current_state = IMU_STATE_INIT_START;
            }
            break;
        case IMU_STATE_INIT_GYRO_WAIT:
            if (status == I2C_SUCCESS) {
                i2c_buf[0] = 0x1C; // ACCEL_CONFIG
                i2c_buf[1] = 0x08; // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
                if (i2c_write_async(MPU6050_ADDR, i2c_buf, 2)) {
                    current_state = IMU_STATE_INIT_ACCEL_WAIT;
                }
            } else if (status == I2C_ERROR) {
                current_state = IMU_STATE_INIT_START;
            }
            break;
        case IMU_STATE_INIT_ACCEL_WAIT:
            if (status == I2C_SUCCESS) {
                i2c_buf[0] = 0x1A; // CONFIG
                i2c_buf[1] = 0x03; // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
                if (i2c_write_async(MPU6050_ADDR, i2c_buf, 2)) {
                    current_state = IMU_STATE_INIT_CONFIG_WAIT;
                }
            } else if (status == I2C_ERROR) {
                current_state = IMU_STATE_INIT_START;
            }
            break;
        case IMU_STATE_INIT_CONFIG_WAIT:
            if (status == I2C_SUCCESS) {
                init_wait_counter = 25;
                current_state = IMU_STATE_INIT_DELAY;
            } else if (status == I2C_ERROR) {
                current_state = IMU_STATE_INIT_START;
            }
            break;
        case IMU_STATE_INIT_DELAY:
            if (init_wait_counter > 0) {
                init_wait_counter--;
            } else {
                current_state = IMU_STATE_IDLE;
            }
            break;
        case IMU_STATE_IDLE:
            i2c_buf[0] = 0x3B; // ACCEL_XOUT_H, ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
            if (i2c_write_async(MPU6050_ADDR, i2c_buf, 1)) {
                current_state = IMU_STATE_READ_REQ_WAIT;
            }
            break;
        case IMU_STATE_READ_REQ_WAIT:
            if (status == I2C_SUCCESS) {
                if (i2c_read_async(MPU6050_ADDR, i2c_buf, 14)) {
                    current_state = IMU_STATE_READ_DATA_WAIT;
                }
            } else if (status == I2C_ERROR) {
                current_state = IMU_STATE_IDLE;
            }
            break;
        case IMU_STATE_READ_DATA_WAIT:
            if (status == I2C_SUCCESS) {
                process_imu_data();
                current_state = IMU_STATE_IDLE;
            } else if (status == I2C_ERROR) {
                current_state = IMU_STATE_IDLE;
            }
            break;
    }
}

void imu_calibrate_begin(void) {
    is_calibrating = true;
    calib_count = 0;
    accel_z_sum = 0;
    gyro_y_sum = 0;
}

bool imu_calibrate_busy(void) {
    return is_calibrating && (calib_count < CALIBRATION_SAMPLES);
}

void imu_calibrate_commit(void) {
    if (calib_count > 0) {
        accel_z_offset = (int16_t)(accel_z_sum / calib_count);
        gyro_y_offset = (int16_t)(gyro_y_sum / calib_count);
    }
    is_calibrating = false;
    angle_gyro = 0.0f;
}

float imu_get_tilt_angle(void) {
    return angle_gyro;
}
