#include "drv_imu.h"
#include "drv_i2c.h"
#include <stdint.h>
#include <math.h>

#define MPU_ADDR 0x68
#define CALIBRATION_SAMPLES 500

typedef enum {
    STATE_INIT_WAKEUP,
    STATE_INIT_GYRO,
    STATE_INIT_ACCEL,
    STATE_INIT_FILTER,
    STATE_DELAY,
    STATE_IDLE,
    STATE_READ_REQ,
    STATE_READ_DATA
} imu_state_t;

static imu_state_t state = STATE_INIT_WAKEUP;
static uint8_t delay_counter = 0;
static uint8_t i2c_buf[14];
static uint8_t reg_addr;

static float angle_gyro = 0.0f;
static float tilt_angle = 0.0f;

static bool is_calibrating = false;
static uint16_t calib_count = 0;
static int32_t calib_accel_z_sum = 0;
static int32_t calib_gyro_y_sum = 0;

static int16_t accel_z_offset = 0;
static int16_t gyro_y_offset = 0;

void imu_init(void) {
    i2c_init();
    state = STATE_INIT_WAKEUP;
    delay_counter = 0;
    angle_gyro = 0.0f;
    tilt_angle = 0.0f;
    is_calibrating = false;
    calib_count = 0;
    calib_accel_z_sum = 0;
    calib_gyro_y_sum = 0;
    accel_z_offset = 0;
    gyro_y_offset = 0;
}

void imu_update(void) {
    i2c_status_t status = i2c_get_status();
    if (status == I2C_BUSY) {
        return;
    }

    switch (state) {
        case STATE_INIT_WAKEUP:
            i2c_buf[0] = 0x6B;
            i2c_buf[1] = 0x00; // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
            i2c_write_async(MPU_ADDR, i2c_buf, 2);
            state = STATE_INIT_GYRO;
            break;

        case STATE_INIT_GYRO:
            if (status == I2C_ERROR) { state = STATE_INIT_WAKEUP; break; }
            i2c_buf[0] = 0x1B;
            i2c_buf[1] = 0x00; // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
            i2c_write_async(MPU_ADDR, i2c_buf, 2);
            state = STATE_INIT_ACCEL;
            break;

        case STATE_INIT_ACCEL:
            if (status == I2C_ERROR) { state = STATE_INIT_WAKEUP; break; }
            i2c_buf[0] = 0x1C;
            i2c_buf[1] = 0x08; // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
            i2c_write_async(MPU_ADDR, i2c_buf, 2);
            state = STATE_INIT_FILTER;
            break;

        case STATE_INIT_FILTER:
            if (status == I2C_ERROR) { state = STATE_INIT_WAKEUP; break; }
            i2c_buf[0] = 0x1A;
            i2c_buf[1] = 0x03; // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
            i2c_write_async(MPU_ADDR, i2c_buf, 2);
            state = STATE_DELAY;
            delay_counter = 0;
            break;

        case STATE_DELAY:
            if (status == I2C_ERROR) { state = STATE_INIT_WAKEUP; break; }
            delay_counter++;
            if (delay_counter >= 25) {
                state = STATE_IDLE;
            }
            break;

        case STATE_IDLE:
            reg_addr = 0x3B; // ACCEL_XOUT_H
            i2c_write_async(MPU_ADDR, &reg_addr, 1);
            state = STATE_READ_REQ;
            break;

        case STATE_READ_REQ:
            if (status == I2C_ERROR) {
                state = STATE_IDLE;
                break;
            }
            i2c_read_async(MPU_ADDR, i2c_buf, 14);
            state = STATE_READ_DATA;
            break;

        case STATE_READ_DATA:
            if (status == I2C_ERROR) {
                state = STATE_IDLE;
                break;
            }

            int16_t accel_z_raw = (int16_t)((i2c_buf[4] << 8) | i2c_buf[5]);
            int16_t gyro_y_raw = (int16_t)((i2c_buf[10] << 8) | i2c_buf[11]);

            if (is_calibrating) {
                if (calib_count < CALIBRATION_SAMPLES) {
                    calib_accel_z_sum += accel_z_raw;
                    calib_gyro_y_sum += gyro_y_raw;
                    calib_count++;
                }
            } else {
                float az = (float)(accel_z_raw - accel_z_offset);
                if (az > 8200.0f) az = 8200.0f;
                if (az < -8200.0f) az = -8200.0f;

                float angle_acc_val = asinf(az / 8200.0f) * 57.296f;
                float gy = (float)(gyro_y_raw - gyro_y_offset);

                angle_gyro += gy * 0.000031f;
                angle_gyro = angle_gyro * 0.9996f + angle_acc_val * 0.0004f;
                tilt_angle = angle_gyro;
            }

            state = STATE_IDLE;
            break;
    }
}

void imu_calibrate_begin(void) {
    is_calibrating = true;
    calib_count = 0;
    calib_accel_z_sum = 0;
    calib_gyro_y_sum = 0;
}

bool imu_calibrate_busy(void) {
    return is_calibrating && (calib_count < CALIBRATION_SAMPLES);
}

void imu_calibrate_commit(void) {
    if (calib_count > 0) {
        accel_z_offset = calib_accel_z_sum / calib_count;
        gyro_y_offset = calib_gyro_y_sum / calib_count;
    }
    is_calibrating = false;
    angle_gyro = 0.0f;
    tilt_angle = 0.0f;
}

float imu_get_tilt_angle(void) {
    return tilt_angle;
}
