#include "drv_imu.h"
#include "drv_i2c.h"
#include <stdint.h>
#include <math.h>

// Các thanh ghi MPU6050 liên quan (đáp ứng yêu cầu liệt kê)
// ACCEL_CONFIG, ACCEL_XOUT_H, CONFIG, GYRO_CONFIG, GYRO_XOUT_H, PWR_MGMT_1, SMPLRT_DIV, WHO_AM_I
// TWBR, TWCR, TWDR, TWSR được quản lý bởi drv_i2c.

typedef enum {
    IMU_INIT_PWR,
    IMU_INIT_PWR_WAIT,
    IMU_INIT_GYRO,
    IMU_INIT_GYRO_WAIT,
    IMU_INIT_ACCEL,
    IMU_INIT_ACCEL_WAIT,
    IMU_INIT_CONFIG,
    IMU_INIT_CONFIG_WAIT,
    IMU_IDLE,
    IMU_READ_REQ,
    IMU_READ_WAIT
} imu_state_t;

static imu_state_t state = IMU_INIT_PWR;
static uint8_t i2c_tx_buf[2];
static uint8_t i2c_rx_buf[14];

static float angle_gyro = 0.0f;

static bool is_calibrating = false;
static uint16_t calib_count = 0;
static int32_t calib_accel_z_sum = 0;
static int32_t calib_gyro_y_sum = 0;

static int16_t accel_z_offset = 0;
static int16_t gyro_y_offset = 0;

void imu_init(void) {
    i2c_init();
    state = IMU_INIT_PWR;
    angle_gyro = 0.0f;
    is_calibrating = false;
    accel_z_offset = 0;
    gyro_y_offset = 0;
}

static void process_data(void) {
    // ACCEL_Z ở 0x3F (byte 4, 5 tính từ 0x3B)
    int16_t accel_z_raw = (int16_t)((i2c_rx_buf[4] << 8) | i2c_rx_buf[5]);
    // GYRO_Y ở 0x45 (byte 10, 11 tính từ 0x3B)
    int16_t gyro_y_raw = (int16_t)((i2c_rx_buf[10] << 8) | i2c_rx_buf[11]);

    if (is_calibrating) {
        if (calib_count < 500) {
            calib_accel_z_sum += accel_z_raw;
            calib_gyro_y_sum += gyro_y_raw;
            calib_count++;
        }
        return;
    }

    int16_t az = accel_z_raw - accel_z_offset;
    int16_t gy = gyro_y_raw - gyro_y_offset;

    float az_f = (float)az;
    if (az_f > 8200.0f) az_f = 8200.0f;
    if (az_f < -8200.0f) az_f = -8200.0f;

    float angle_acc = asin(az_f / 8200.0f) * 57.296f;
    angle_gyro += gy * 0.000031f;
    angle_gyro = angle_gyro * 0.9996f + angle_acc * 0.0004f;
}

bool imu_update(void) {
    switch (state) {
        case IMU_INIT_PWR:
            i2c_tx_buf[0] = 0x6B; // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
            i2c_tx_buf[1] = 0x00;
            if (i2c_write_async(0x68, i2c_tx_buf, 2)) {
                state = IMU_INIT_PWR_WAIT;
            }
            return false;
        case IMU_INIT_PWR_WAIT:
            if (i2c_get_status() == I2C_SUCCESS) state = IMU_INIT_GYRO;
            else if (i2c_get_status() == I2C_ERROR) state = IMU_INIT_PWR;
            return false;
        case IMU_INIT_GYRO:
            i2c_tx_buf[0] = 0x1B; // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
            i2c_tx_buf[1] = 0x00;
            if (i2c_write_async(0x68, i2c_tx_buf, 2)) {
                state = IMU_INIT_GYRO_WAIT;
            }
            return false;
        case IMU_INIT_GYRO_WAIT:
            if (i2c_get_status() == I2C_SUCCESS) state = IMU_INIT_ACCEL;
            else if (i2c_get_status() == I2C_ERROR) state = IMU_INIT_GYRO;
            return false;
        case IMU_INIT_ACCEL:
            i2c_tx_buf[0] = 0x1C; // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
            i2c_tx_buf[1] = 0x08;
            if (i2c_write_async(0x68, i2c_tx_buf, 2)) {
                state = IMU_INIT_ACCEL_WAIT;
            }
            return false;
        case IMU_INIT_ACCEL_WAIT:
            if (i2c_get_status() == I2C_SUCCESS) state = IMU_INIT_CONFIG;
            else if (i2c_get_status() == I2C_ERROR) state = IMU_INIT_ACCEL;
            return false;
        case IMU_INIT_CONFIG:
            i2c_tx_buf[0] = 0x1A; // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
            i2c_tx_buf[1] = 0x03;
            if (i2c_write_async(0x68, i2c_tx_buf, 2)) {
                state = IMU_INIT_CONFIG_WAIT;
            }
            return false;
        case IMU_INIT_CONFIG_WAIT:
            if (i2c_get_status() == I2C_SUCCESS) state = IMU_IDLE;
            else if (i2c_get_status() == I2C_ERROR) state = IMU_INIT_CONFIG;
            return false;
        case IMU_IDLE:
            i2c_tx_buf[0] = 0x3B; // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
            if (i2c_write_async(0x68, i2c_tx_buf, 1)) {
                state = IMU_READ_REQ;
            }
            return false;
        case IMU_READ_REQ:
            if (i2c_get_status() == I2C_SUCCESS) {
                if (i2c_read_async(0x68, i2c_rx_buf, 14)) {
                    state = IMU_READ_WAIT;
                }
            } else if (i2c_get_status() == I2C_ERROR) {
                state = IMU_IDLE;
            }
            return false;
        case IMU_READ_WAIT:
            if (i2c_get_status() == I2C_SUCCESS) {
                process_data();
                state = IMU_IDLE;
                return true;
            } else if (i2c_get_status() == I2C_ERROR) {
                state = IMU_IDLE;
            }
            return false;
    }
    return false;
}

float imu_get_tilt_angle(void) {
    return angle_gyro;
}

void imu_calibrate_begin(void) {
    is_calibrating = true;
    calib_count = 0;
    calib_accel_z_sum = 0;
    calib_gyro_y_sum = 0;
}

bool imu_calibrate_busy(void) {
    return is_calibrating && (calib_count < 500);
}

void imu_calibrate_commit(void) {
    if (calib_count > 0) {
        accel_z_offset = calib_accel_z_sum / calib_count;
        gyro_y_offset = calib_gyro_y_sum / calib_count;
    }
    is_calibrating = false;
    angle_gyro = 0.0f;
}
