```file:src/drv_imu.c
#include "drv_imu.h"
#include "drv_i2c.h"
#include <math.h>
#include <stdint.h>
#include <stddef.h>

#define MPU6050_ADDR 0x68

#define REG_CONFIG       0x1A
#define REG_GYRO_CONFIG  0x1B
#define REG_ACCEL_CONFIG 0x1C
#define REG_ACCEL_XOUT_H 0x3B
#define REG_PWR_MGMT_1   0x6B

typedef enum {
    STATE_INIT_START,
    STATE_INIT_PWR,
    STATE_INIT_GYRO,
    STATE_INIT_ACCEL,
    STATE_INIT_CONFIG,
    STATE_IDLE,
    STATE_READING_ADDR,
    STATE_READING_DATA
} imu_state_t;

static imu_state_t state = STATE_INIT_START;
static uint8_t i2c_buf[14];

static float angle_gyro = 0.0f;
static float accel_z_offset = 0.0f;
static float gyro_y_offset = 0.0f;

static bool is_calibrating = false;
static uint16_t calib_count = 0;
static int32_t calib_accel_z_sum = 0;
static int32_t calib_gyro_y_sum = 0;

#define CALIB_SAMPLES 500

void imu_init(void) {
    i2c_init();
    state = STATE_INIT_START;
    angle_gyro = 0.0f;
    accel_z_offset = 0.0f;
    gyro_y_offset = 0.0f;
    is_calibrating = false;
    calib_count = 0;
    calib_accel_z_sum = 0;
    calib_gyro_y_sum = 0;
}

bool imu_update(void) {
    i2c_status_t st = i2c_get_status();

    if (st == I2C_BUSY) {
        return false;
    }

    switch (state) {
        case STATE_INIT_START:
            i2c_buf[0] = REG_PWR_MGMT_1;
            i2c_buf[1] = 0x00; // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
            i2c_write_async(MPU6050_ADDR, i2c_buf, 2);
            state = STATE_INIT_PWR;
            break;

        case STATE_INIT_PWR:
            if (st == I2C_SUCCESS) {
                i2c_buf[0] = REG_GYRO_CONFIG;
                i2c_buf[1] = 0x00; // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
                i2c_write_async(MPU6050_ADDR, i2c_buf, 2);
                state = STATE_INIT_GYRO;
            } else if (st == I2C_ERROR) {
                state = STATE_INIT_START;
            }
            break;

        case STATE_INIT_GYRO:
            if (st == I2C_SUCCESS) {
                i2c_buf[0] = REG_ACCEL_CONFIG;
                i2c_buf[1] = 0x08; // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
                i2c_write_async(MPU6050_ADDR, i2c_buf, 2);
                state = STATE_INIT_ACCEL;
            } else if (st == I2C_ERROR) {
                state = STATE_INIT_START;
            }
            break;

        case STATE_INIT_ACCEL:
            if (st == I2C_SUCCESS) {
                i2c_buf[0] = REG_CONFIG;
                i2c_buf[1] = 0x03; // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
                i2c_write_async(MPU6050_ADDR, i2c_buf, 2);
                state = STATE_INIT_CONFIG;
            } else if (st == I2C_ERROR) {
                state = STATE_INIT_START;
            }
            break;

        case STATE_INIT_CONFIG:
            if (st == I2C_SUCCESS) {
                state = STATE_IDLE;
            } else if (st == I2C_ERROR) {
                state = STATE_INIT_START;
            }
            break;

        case STATE_IDLE:
            i2c_buf[0] = REG_ACCEL_XOUT_H;
            i2c_write_async(MPU6050_ADDR, i2c_buf, 1);
            state = STATE_READING_ADDR;
            break;

        case STATE_READING_ADDR:
            if (st == I2C_SUCCESS) {
                i2c_read_async(MPU6050_ADDR, i2c_buf, 14);
                state = STATE_READING_DATA;
            } else if (st == I2C_ERROR) {
                state = STATE_IDLE;
            }
            break;

        case STATE_READING_DATA:
            if (st == I2C_SUCCESS) {
                state = STATE_IDLE;

                int16_t accel_z_raw = (int16_t)((i2c_buf[4] << 8) | i2c_buf[5]);
                int16_t gyro_y_raw = (int16_t)((i2c_buf[10] << 8) | i2c_buf[11]);

                if (is_calibrating) {
                    if (calib_count < CALIB_SAMPLES) {
                        calib_accel_z_sum += accel_z_raw;
                        calib_gyro_y_sum += gyro_y_raw;
                        calib_count++;
                    }
                } else {
                    float az = (float)accel_z_raw - accel_z_offset;
                    if (az > 8200.0f) az = 8200.0f;
                    if (az < -8200.0f) az = -8200.0f;

                    float angle_acc = asin(az / 8200.0) * 57.296;

                    float gy = (float)gyro_y_raw - gyro_y_offset;
                    angle_gyro += gy * 0.000031;
                    angle_gyro = angle_gyro * 0.9996 + angle_acc * 0.0004;
                }
                return true;
            } else if (st == I2C_ERROR) {
                state = STATE_IDLE;
            }
            break;
    }

    return false;
}

float imu_get_tilt_angle(void) {
    return angle_gyro;
}

void imu_calibrate_begin(void) {
    is_calibrating = true;
    calib_count = 0;
    calib_accel_z_sum = 0;
    calib_gyro_y_sum = 0;
}

bool imu_calibrate_busy(void) {
    return is_calibrating && (calib_count < CALIB_SAMPLES);
}

void imu_calibrate_commit(void) {
    if (calib_count > 0) {
        accel_z_offset = (float)calib_accel_z_sum / calib_count;
        gyro_y_offset = (float)calib_gyro_y_sum / calib_count;
    }
    is_calibrating = false;
    angle_gyro = 0.0f;
}
