#include "drv_imu.h"
#include "drv_i2c.h"
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <stddef.h>

#define MPU6050_ADDR 0x68
#define REG_CONFIG 0x1A
#define REG_GYRO_CONFIG 0x1B
#define REG_ACCEL_CONFIG 0x1C
#define REG_ACCEL_XOUT_H 0x3B
#define REG_PWR_MGMT_1 0x6B

#define CALIBRATION_SAMPLES 500

typedef enum {
    IMU_STATE_INIT_START,
    IMU_STATE_INIT_PWR,
    IMU_STATE_INIT_GYRO,
    IMU_STATE_INIT_ACCEL,
    IMU_STATE_INIT_CONFIG,
    IMU_STATE_IDLE,
    IMU_STATE_READ_REQ,
    IMU_STATE_READ_WAIT
} imu_state_t;

static imu_state_t state = IMU_STATE_INIT_START;
static uint8_t i2c_buf[14];
static float current_angle = 0.0f;

static bool calib_busy = false;
static uint16_t calib_count = 0;
static int32_t calib_accel_sum = 0;
static int32_t calib_gyro_sum = 0;

static int16_t offset_accel_z = 0;
static int16_t offset_gyro_y = 0;

void imu_init(void) {
    i2c_init();
    state = IMU_STATE_INIT_START;
    current_angle = 0.0f;
    calib_busy = false;
    calib_count = 0;
    calib_accel_sum = 0;
    calib_gyro_sum = 0;
    offset_accel_z = 0;
    offset_gyro_y = 0;
}

bool imu_update(void) {
    if (state == IMU_STATE_INIT_START) {
        if (i2c_get_status() == I2C_IDLE || i2c_get_status() == I2C_SUCCESS) {
            i2c_buf[0] = REG_PWR_MGMT_1;
            i2c_buf[1] = 0x00; // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
            i2c_write_async(MPU6050_ADDR, i2c_buf, 2);
            state = IMU_STATE_INIT_PWR;
        }
        return false;
    } else if (state == IMU_STATE_INIT_PWR) {
        if (i2c_get_status() == I2C_SUCCESS) {
            i2c_buf[0] = REG_GYRO_CONFIG;
            i2c_buf[1] = 0x00; // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
            i2c_write_async(MPU6050_ADDR, i2c_buf, 2);
            state = IMU_STATE_INIT_GYRO;
        } else if (i2c_get_status() == I2C_ERROR) {
            state = IMU_STATE_INIT_START;
        }
        return false;
    } else if (state == IMU_STATE_INIT_GYRO) {
        if (i2c_get_status() == I2C_SUCCESS) {
            i2c_buf[0] = REG_ACCEL_CONFIG;
            i2c_buf[1] = 0x08; // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
            i2c_write_async(MPU6050_ADDR, i2c_buf, 2);
            state = IMU_STATE_INIT_ACCEL;
        } else if (i2c_get_status() == I2C_ERROR) {
            state = IMU_STATE_INIT_START;
        }
        return false;
    } else if (state == IMU_STATE_INIT_ACCEL) {
        if (i2c_get_status() == I2C_SUCCESS) {
            i2c_buf[0] = REG_CONFIG;
            i2c_buf[1] = 0x03; // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
            i2c_write_async(MPU6050_ADDR, i2c_buf, 2);
            state = IMU_STATE_INIT_CONFIG;
        } else if (i2c_get_status() == I2C_ERROR) {
            state = IMU_STATE_INIT_START;
        }
        return false;
    } else if (state == IMU_STATE_INIT_CONFIG) {
        if (i2c_get_status() == I2C_SUCCESS) {
            state = IMU_STATE_IDLE;
        } else if (i2c_get_status() == I2C_ERROR) {
            state = IMU_STATE_INIT_START;
        }
        return false;
    } else if (state == IMU_STATE_IDLE) {
        if (i2c_get_status() == I2C_IDLE || i2c_get_status() == I2C_SUCCESS) {
            i2c_buf[0] = REG_ACCEL_XOUT_H; // ref: ds-032, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.29-31
            i2c_write_async(MPU6050_ADDR, i2c_buf, 1);
            state = IMU_STATE_READ_REQ;
        }
        return false;
    } else if (state == IMU_STATE_READ_REQ) {
        if (i2c_get_status() == I2C_SUCCESS) {
            i2c_read_async(MPU6050_ADDR, i2c_buf, 14);
            state = IMU_STATE_READ_WAIT;
        } else if (i2c_get_status() == I2C_ERROR) {
            state = IMU_STATE_IDLE;
        }
        return false;
    } else if (state == IMU_STATE_READ_WAIT) {
        if (i2c_get_status() == I2C_SUCCESS) {
            int16_t accel_z_raw = (int16_t)(((uint16_t)i2c_buf[4] << 8) | i2c_buf[5]);
            int16_t gyro_y_raw = (int16_t)(((uint16_t)i2c_buf[10] << 8) | i2c_buf[11]);

            if (calib_busy) {
                if (calib_count < CALIBRATION_SAMPLES) {
                    calib_accel_sum += accel_z_raw;
                    calib_gyro_sum += gyro_y_raw;
                    calib_count++;
                }
            } else {
                int16_t accel_z = accel_z_raw - offset_accel_z;
                int16_t gyro_y = gyro_y_raw - offset_gyro_y;

                if (accel_z > 8200) accel_z = 8200;
                if (accel_z < -8200) accel_z = -8200;

                float angle_acc = asin((float)accel_z / 8200.0) * 57.296;
                current_angle += (float)gyro_y * 0.000031;
                current_angle = current_angle * 0.9996 + angle_acc * 0.0004;
            }

            state = IMU_STATE_IDLE;
            return true;
        } else if (i2c_get_status() == I2C_ERROR) {
            state = IMU_STATE_IDLE;
            return false;
        }
        return false;
    }

    return false;
}

float imu_get_tilt_angle(void) {
    return current_angle;
}

void imu_calibrate_begin(void) {
    calib_busy = true;
    calib_count = 0;
    calib_accel_sum = 0;
    calib_gyro_sum = 0;
}

bool imu_calibrate_busy(void) {
    return (calib_busy && calib_count < CALIBRATION_SAMPLES);
}

void imu_calibrate_commit(void) {
    if (calib_count > 0) {
        offset_accel_z = (int16_t)(calib_accel_sum / calib_count);
        offset_gyro_y = (int16_t)(calib_gyro_sum / calib_count);
    }
    calib_busy = false;
    current_angle = 0.0f;
}
