#ifndef LOGIC_PID_H
#define LOGIC_PID_H

#include <stdbool.h>

/**
 * @brief Đặt hệ số PID.
 * 
 * Hàm này chỉ cập nhật hệ số, KHÔNG xoá trạng thái tích phân hay đạo hàm,
 * cho phép tinh chỉnh (tuning) trực tiếp khi robot đang chạy mà không gây giật.
 * 
 * @param kp Hệ số P
 * @param ki Hệ số I (đã bao gồm dt = 4ms)
 * @param kd Hệ số D (đã bao gồm dt = 4ms)
 */
void pid_set_tunings(float kp, float ki, float kd);

/**
 * @brief Tính toán giá trị đầu ra PID.
 * 
 * @param angle Góc nghiêng hiện tại (đơn vị: độ).
 * @param pid_setpoint Điểm đặt góc nghiêng (đơn vị: độ).
 * @param is_running Cờ cho phép chạy. Nếu false, xoá trạng thái và trả về 0.
 * @return float Giá trị điều khiển động cơ (khoảng -400 đến 400).
 */
float pid_compute(float angle, float pid_setpoint, bool is_running);

#endif // LOGIC_PID_H
