@pytest.fixture(scope="module")
def pid_lib():
    lib_path = build_lib()
    lib = ctypes.CDLL(os.path.abspath(lib_path))

    lib.pid_set_tunings.argtypes = [ctypes.c_float, ctypes.c_float, ctypes.c_float]
    lib.pid_set_tunings.restype = None

    lib.pid_compute.argtypes = [ctypes.c_float, ctypes.c_float, ctypes.c_bool]
    lib.pid_compute.restype = ctypes.c_float

    return lib

def test_integral_and_output_clamp(pid_lib):
    pid_lib.pid_compute(0.0, 0.0, False) # Reset
    pid_lib.pid_set_tunings(100.0, 100.0, 0.0)

    out = pid_lib.pid_compute(10.0, 0.0, True)
    assert out == 400.0

    out = pid_lib.pid_compute(10.0, 0.0, True)
    assert out == 400.0

    pid_lib.pid_compute(0.0, 0.0, False) # Reset
    out = pid_lib.pid_compute(-10.0, 0.0, True)
    assert out == -400.0

def test_deadband(pid_lib):
    pid_lib.pid_compute(0.0, 0.0, False) # Reset
    pid_lib.pid_set_tunings(1.0, 0.0, 0.0)

    out = pid_lib.pid_compute(4.0, 0.0, True)
    assert out == 0.0

    out = pid_lib.pid_compute(-4.0, 0.0, True)
    assert out == 0.0

    out = pid_lib.pid_compute(6.0, 0.0, True)
    assert out == 6.0

def test_clear_state_on_stop(pid_lib):
    pid_lib.pid_compute(0.0, 0.0, False) # Reset
    pid_lib.pid_set_tunings(0.0, 10.0, 0.0)

    pid_lib.pid_compute(10.0, 0.0, True)

    out = pid_lib.pid_compute(10.0, 0.0, False)
    assert out == 0.0

    out = pid_lib.pid_compute(0.0, 0.0, True)
    assert out == 0.0

def test_change_tunings_midway(pid_lib):
