    pid_lib.pid_set_tunings(0.0, 10.0, 0.0)

    pid_lib.pid_compute(10.0, 0.0, True)

    # Đổi hệ số không làm mất tích phân
    pid_lib.pid_set_tunings(0.0, 5.0, 0.0)

    out = pid_lib.pid_compute(0.0, 0.0, True)
