def test_self_balancing_setpoint(pid_lib):
    pid_lib.pid_compute(0.0, 0.0, False) # Reset
    pid_lib.pid_set_tunings(10.0, 0.0, 0.0)

    out1 = pid_lib.pid_compute(-1.0, 0.0, True)
    out2 = pid_lib.pid_compute(-1.0, 0.0, True)

    # Đầu ra âm kéo dài làm điểm cân bằng tăng -> sai số âm hơn -> đầu ra âm hơn
    assert out2 < out1

def test_latching_stop(pid_lib):
    pid_lib.pid_compute(0.0, 0.0, False) # Reset
    pid_lib.pid_set_tunings(10.0, 0.0, 0.0)

    out = pid_lib.pid_compute(10.0, 0.0, True)
    assert out == 100.0

    # Góc > 30 độ -> dừng
    out = pid_lib.pid_compute(35.0, 0.0, True)
    assert out == 0.0

    # Góc về bình thường nhưng chưa reset -> vẫn dừng
    out = pid_lib.pid_compute(10.0, 0.0, True)
    assert out == 0.0

    # Reset bằng cách tắt is_running rồi bật lại
    pid_lib.pid_compute(10.0, 0.0, False)
    out = pid_lib.pid_compute(10.0, 0.0, True)
    assert out == 100.0

def test_braking_function(pid_lib):
    pid_lib.pid_compute(0.0, 0.0, False) # Reset
    pid_lib.pid_set_tunings(10.0, 0.0, 0.0)

    out1 = pid_lib.pid_compute(2.0, 0.0, True)
    assert out1 == 20.0

    # Lượt sau, do out1 > 10, hàm phanh cộng thêm vào sai số
    out2 = pid_lib.pid_compute(2.0, 0.0, True)
    assert out2 > 23.0
