    assert out < 0.0

    sb_after = pid_lib.pid_get_self_balance_setpoint()
    assert sb_after > sb_before # Should increase by 0.0015
    assert abs(sb_after - (sb_before + 0.0015)) < 1e-6

    # Force a positive output
