    assert out > 0.0

    sb_after2 = pid_lib.pid_get_self_balance_setpoint()
    assert sb_after2 < sb_after # Should decrease by 0.0015
    assert abs(sb_after2 - (sb_after - 0.0015)) < 1e-6
