#include "app_balance.h"
#include "drv_imu.h"
#include "logic_pid.h"
#include "drv_stepper.h"
#include "drv_buzzer.h"
#include "drv_button.h"

extern void i2c_tick(void);

typedef enum {
    STATE_INIT,
    STATE_CHO_NUT,
    STATE_HIEU_CHINH,
    STATE_SAN_SANG,
    STATE_CAN_BANG,
    STATE_NGA
} app_state_t;

static app_state_t current_state = STATE_INIT;
static uint32_t last_beep_time = 0;
static uint8_t beep_count = 0;

void app_init(void) {
    imu_init();
    stepper_init();
    buzzer_init();
    button_init();
    current_state = STATE_INIT;
}

void app_tick(uint32_t now_ms) {
    i2c_tick();

    while (!imu_update()) {
        // Bơm liên tục cho tới khi có mẫu mới
    }

    buzzer_update(now_ms);
    button_event_t btn = button_get_event(now_ms);

    switch (current_state) {
        case STATE_INIT:
            buzzer_beep_async(now_ms, 100);
            current_state = STATE_CHO_NUT;
            break;

        case STATE_CHO_NUT:
            if (btn == BUTTON_EVENT_PRESSED) {
                current_state = STATE_HIEU_CHINH;
                imu_calibrate_begin();
                buzzer_beep_async(now_ms, 50);
                beep_count = 1;
                last_beep_time = now_ms;
            }
            break;

        case STATE_HIEU_CHINH:
            if (now_ms - last_beep_time >= 380 && beep_count < 5) {
                buzzer_beep_async(now_ms, 50);
                last_beep_time = now_ms;
                beep_count++;
            }
            if (!imu_calibrate_busy()) {
                imu_calibrate_commit();
                current_state = STATE_SAN_SANG;
                buzzer_beep_async(now_ms, 50);
                beep_count = 1;
                last_beep_time = now_ms;
            }
            break;

        case STATE_SAN_SANG:
            if (beep_count == 1 && now_ms - last_beep_time >= 150) {
                buzzer_beep_async(now_ms, 50);
                last_beep_time = now_ms;
                beep_count++;
            } else if (beep_count == 2 && now_ms - last_beep_time >= 150) {
                current_state = STATE_CAN_BANG;
            }
            break;

        case STATE_CAN_BANG:
            {
                float angle = imu_get_tilt_angle();
                if (angle > 30.0f || angle < -30.0f) {
                    stepper_set_speed(0, 0);
                    pid_compute(angle, 0.0f, false);
                    current_state = STATE_NGA;
                } else {
                    float out = pid_compute(angle, 0.0f, true);
                    int16_t motor = 0;
                    if (out > 0.0f) {
                        out = 405.0f - (5500.0f / (out + 9.0f));
                        motor = 400 - (int16_t)out;
                    } else if (out < 0.0f) {
                        out = -405.0f - (5500.0f / (out - 9.0f));
                        motor = -400 - (int16_t)out;
                    }
                    stepper_set_speed(motor, motor);
                }
            }
            break;

        case STATE_NGA:
            if (btn == BUTTON_EVENT_PRESSED) {
                current_state = STATE_CHO_NUT;
            }
            break;
    }
}
