#include <stdint.h>
#include <stdbool.h>
#include "drv_imu.h"
#include "logic_pid.h"
#include "drv_stepper.h"
#include "drv_buzzer.h"
#include "drv_button.h"

void i2c_tick(void);

void app_balance_update(uint32_t now_ms) {
    static uint8_t state = 0; // 0:CHO_NUT, 1:HIEU_CHINH, 2:SAN_SANG, 3:CAN_BANG, 4:NGA
    static uint32_t state_timer = 0;
    static uint8_t beep_count = 0;
    static bool is_init = false;

    if (!is_init) {
        buzzer_beep_async(now_ms, 100);
        is_init = true;
    }

    i2c_tick();

    uint16_t timeout = 1000;
    while (timeout > 0) {
        if (imu_update()) {
            break;
        }
        timeout--;
    }

    buzzer_update(now_ms);
    button_event_t btn = button_get_event(now_ms);
    float angle = imu_get_tilt_angle();

    switch (state) {
        case 0: // CHO_NUT
            if (btn == BUTTON_EVENT_PRESSED) {
                state = 1; // HIEU_CHINH
                imu_calibrate_begin();
                state_timer = now_ms;
                beep_count = 0;
            }
            break;

        case 1: // HIEU_CHINH
            if (now_ms - state_timer >= 380) {
                if (beep_count < 5) {
                    buzzer_beep_async(now_ms, 100);
                    beep_count++;
                }
                state_timer = now_ms;
            }
            if (!imu_calibrate_busy()) {
                imu_calibrate_commit();
                state = 2; // SAN_SANG
                state_timer = now_ms;
                beep_count = 0;
            }
            break;

        case 2: // SAN_SANG
            if (now_ms - state_timer >= 200) {
                if (beep_count < 2) {
                    buzzer_beep_async(now_ms, 100);
                    beep_count++;
                    state_timer = now_ms;
                } else {
                    state = 3; // CAN_BANG
                }
            }
            break;

        case 3: // CAN_BANG
            if (angle > 30.0f || angle < -30.0f) {
                stepper_set_speed(0, 0);
                pid_compute(angle, 0.0f, false);
                state = 4; // NGA
            } else {
                float out = pid_compute(angle, 0.0f, true);
                int16_t motor = 0;
                if (out > 0.0f) {
                    float comp = 405.0f - (5500.0f / (out + 9.0f));
                    motor = 400 - (int16_t)comp;
                } else if (out < 0.0f) {
                    float comp = -405.0f - (5500.0f / (out - 9.0f));
                    motor = -400 - (int16_t)comp;
                }
                stepper_set_speed(motor, motor);
            }
            break;

        case 4: // NGA
            if (btn == BUTTON_EVENT_PRESSED) {
                state = 0; // CHO_NUT
                buzzer_beep_async(now_ms, 100);
            }
            break;
    }
}

