#include "app_balance.h"
#include "drv_imu.h"
#include "logic_pid.h"
#include "drv_stepper.h"
#include "drv_buzzer.h"
#include "drv_button.h"

// Max IMU pump iterations: 4ms loop / 430us per read = 9.3 -> 9
#define MAX_IMU_PUMP_ITER 9

typedef enum {
    STATE_CHO_NUT = 0,
    STATE_HIEU_CHINH,
    STATE_SAN_SANG,
    STATE_CAN_BANG,
    STATE_NGA
} app_state_t;

static uint32_t now_ms = 0;
static app_state_t state = STATE_CHO_NUT;
static uint8_t beep_count = 0;
static uint32_t next_beep_time = 0;

// Bắt buộc gọi để giữ bus I2C không bị treo
void i2c_tick(void);

void app_init(void) {
    imu_init();
    stepper_init();
    buzzer_init();
    button_init();
    pid_set_tunings(0.0f, 0.0f, 0.0f);

    state = STATE_CHO_NUT;
    buzzer_beep_async(0, 100); // 1 bíp khi có điện
}

void app_step(void) {
    now_ms += 4;

    // 1. Tick I2C
    i2c_tick();

    // 2. Bơm IMU tới khi có mẫu hoặc hết trần
    bool has_sample = false;
    for (int i = 0; i < MAX_IMU_PUMP_ITER; i++) {
        if (imu_update()) {
            has_sample = true;
            break;
        }
    }

    // 3. Cập nhật ngoại vi và đọc nút
    buzzer_update(now_ms);
    button_event_t btn = button_get_event(now_ms);

    // 4. Máy trạng thái
    switch (state) {
        case STATE_CHO_NUT:
            if (btn == BUTTON_EVENT_PRESSED) {
                state = STATE_HIEU_CHINH;
                imu_calibrate_begin();
                beep_count = 0;
                next_beep_time = now_ms;
            }
            break;

        case STATE_HIEU_CHINH:
            // 5 bíp rải đều trong ~1.9s (mỗi 380ms)
            if (beep_count < 5 && now_ms >= next_beep_time) {
                buzzer_beep_async(now_ms, 50);
                next_beep_time = now_ms + 380;
                beep_count++;
            }

            if (!imu_calibrate_busy()) {
                imu_calibrate_commit();
                state = STATE_SAN_SANG;
                buzzer_beep_async(now_ms, 100); // Bíp 1 của SAN_SANG
                next_beep_time = now_ms + 200;
                beep_count = 1;
            }
            break;

        case STATE_SAN_SANG:
            // Chờ bíp thứ 2 rồi vào cân bằng
            if (beep_count == 1 && now_ms >= next_beep_time) {
                buzzer_beep_async(now_ms, 100); // Bíp 2 của SAN_SANG
                beep_count = 2;
                state = STATE_CAN_BANG;
            }
            break;

        case STATE_CAN_BANG:
            if (has_sample) {
                float angle = imu_get_tilt_angle();

                if (angle > 30.0f || angle < -30.0f) {
                    stepper_set_speed(0, 0);
                    pid_compute(angle, 0.0f, false); // Xoá tích phân
                    state = STATE_NGA;
                } else {
                    float out = pid_compute(angle, 0.0f, true);
                    float motor = 0.0f;

                    // Bù phi tuyến theo mã tham chiếu
                    if (out > 0.0f) {
                        float comp = 405.0f - (5500.0f / (out + 9.0f));
                        motor = 400.0f - comp;
                    } else if (out < 0.0f) {
                        float comp = -405.0f - (5500.0f / (out - 9.0f));
                        motor = -400.0f - comp;
                    }

                    stepper_set_speed((int16_t)motor, (int16_t)motor);
                }
            }
            break;

        case STATE_NGA:
            if (btn == BUTTON_EVENT_PRESSED) {
                state = STATE_SAN_SANG;
                buzzer_beep_async(now_ms, 100);
                next_beep_time = now_ms + 200;
                beep_count = 1;
            }
            break;
    }
}

void app_tick(void) {
    app_step();
}
