```file:src/app_balance.c
#include "app_balance.h"
#include "drv_imu.h"
#include "logic_pid.h"
#include "drv_stepper.h"
#include "drv_buzzer.h"
#include "drv_button.h"
#include <stdbool.h>
#include <stdint.h>

/*
 * Calculation for MAX_IMU_PUMP_ITERATIONS:
 * The control loop runs every 4ms. We want to spend at most 1ms pumping the IMU.
 * Assuming each call to imu_update() takes at least 10 CPU cycles.
 * At 16MHz, 10 cycles = 0.625us.
 * 1ms / 0.625us = 1600 iterations.
 */
#define MAX_IMU_PUMP_ITERATIONS 1600

#define CALIB_TIMEOUT_MS 10000
#define MAX_MISSED_SAMPLES 10

typedef enum {
    STATE_CHO_NUT = 0,
    STATE_HIEU_CHINH,
    STATE_SAN_SANG,
    STATE_CAN_BANG,
    STATE_NGA
} app_state_t;

static app_state_t current_state = STATE_CHO_NUT;
static uint32_t now_ms = 0;
static uint32_t calib_start_ms = 0;
static uint8_t missed_samples = 0;

static uint8_t beep_count = 0;
static uint8_t beep_target = 0;
static uint32_t beep_next_ms = 0;
static uint32_t beep_on_ms = 0;
static uint32_t beep_off_ms = 0;
static bool beep_repeat = false;
static bool beep_is_on = false;

extern void i2c_tick(void);

static void start_beep_seq(uint8_t count, uint32_t on_ms, uint32_t off_ms, bool repeat, uint32_t now) {
    beep_count = 0;
    beep_target = count;
    beep_on_ms = on_ms;
    beep_off_ms = off_ms;
    beep_repeat = repeat;
    beep_next_ms = now;
    beep_is_on = false;
}

static void process_beep_seq(uint32_t now) {
    if (beep_target > 0) {
        if (now >= beep_next_ms) {
            if (!beep_is_on) {
                buzzer_beep_async(now, beep_on_ms);
                beep_is_on = true;
                beep_next_ms = now + beep_on_ms;
            } else {
                beep_is_on = false;
                beep_count++;
                if (beep_count >= beep_target) {
                    if (beep_repeat) {
                        beep_count = 0;
                        beep_next_ms = now + 500;
                    } else {
                        beep_target = 0;
                    }
                } else {
                    beep_next_ms = now + beep_off_ms;
                }
            }
        }
    }
}

void app_init(void) {
    imu_init();
    stepper_init();
    buzzer_init();
    button_init();

    current_state = STATE_CHO_NUT;
    now_ms = 0;
    missed_samples = 0;

    start_beep_seq(1, 100, 0, false, now_ms);
}

void app_step(void) {
    now_ms += 4;

    i2c_tick();

    bool got_sample = false;
    for (int i = 0; i < MAX_IMU_PUMP_ITERATIONS; i++) {
        if (imu_update()) {
            got_sample = true;
            break;
        }
    }

    buzzer_update(now_ms);
    process_beep_seq(now_ms);

    button_event_t btn = button_get_event(now_ms);

    if (current_state == STATE_CHO_NUT) {
        if (btn == BUTTON_EVENT_PRESSED) {
            current_state = STATE_HIEU_CHINH;
            calib_start_ms = now_ms;
            imu_calibrate_begin();
            start_beep_seq(5, 100, 200, false, now_ms);
        }
    } else if (current_state == STATE_HIEU_CHINH) {
        if (btn == BUTTON_EVENT_PRESSED) {
            current_state = STATE_CHO_NUT;
            start_beep_seq(1, 100, 0, false, now_ms);
        } else {
            if (!imu_calibrate_busy()) {
                imu_calibrate_commit();
                current_state = STATE_SAN_SANG;
                start_beep_seq(2, 100, 100, false, now_ms);
            } else if (now_ms - calib_start_ms > CALIB_TIMEOUT_MS) {
                current_state = STATE_NGA;
                start_beep_seq(3, 100, 100, true, now_ms);
            }
        }
    } else if (current_state == STATE_SAN_SANG) {
        if (beep_target == 0) {
            current_state = STATE_CAN_BANG;
        }
    } else if (current_state == STATE_NGA) {
        if (btn == BUTTON_EVENT_PRESSED) {
            current_state = STATE_CHO_NUT;
            start_beep_seq(1, 100, 0, false, now_ms);
        }
    }

    if (got_sample) {
        missed_samples = 0;
        float angle = imu_get_tilt_angle();

        if (current_state == STATE_CAN_BANG || current_state == STATE_SAN_SANG) {
            if (angle > 30.0f || angle < -30.0f) {
                stepper_set_speed(0, 0);
                pid_compute(angle, 0.0f, false);
                current_state = STATE_NGA;
                beep_target = 0;
            } else if (current_state == STATE_CAN_BANG) {
                float out = pid_compute(angle, 0.0f, true);
                int16_t motor = 0;
                if (out > 0.0f) {
                    out = 405.0f - (5500.0f / (out + 9.0f));
                    motor = (int16_t)(400.0f - out);
                } else if (out < 0.0f) {
                    out = -405.0f + (5500.0f / (-out + 9.0f));
                    motor = (int16_t)(-400.0f - out);
                }
                stepper_set_speed(motor, motor);
            }
        }
    } else {
        if (missed_samples < 255) {
            missed_samples++;
        }
        if (missed_samples >= MAX_MISSED_SAMPLES) {
            if (current_state != STATE_NGA) {
                stepper_set_speed(0, 0);
                pid_compute(0.0f, 0.0f, false);
                current_state = STATE_NGA;
                beep_target = 0;
            }
        }
    }
}

void app_tick(void) {
    app_step();
}
