#include "app_balance.h"
#include "drv_imu.h"
#include "logic_pid.h"
#include "drv_stepper.h"
#include "drv_buzzer.h"
#include "drv_button.h"

// Control loop is 4ms (4000us). Driver assumes 31us per update.
// Max iterations = 4000 / 31 = 129.
#define MAX_IMU_PUMPS 129
#define CALIB_TIMEOUT_MS 10000
#define MAX_MISSING_SAMPLES 10

typedef enum {
    STATE_CHO_NUT = 0,
    STATE_HIEU_CHINH,
    STATE_SAN_SANG,
    STATE_CAN_BANG,
    STATE_NGA
} app_state_t;

static app_state_t state = STATE_CHO_NUT;
static uint32_t now_ms = 0;
static uint32_t calib_start_ms = 0;
static uint32_t san_sang_start_ms = 0;
static uint8_t missing_samples_count = 0;
static uint8_t nga_reason = 0;

typedef struct {
    uint32_t start_ms;
    uint8_t count;
    uint8_t max_count;
    uint32_t period_ms;
    uint32_t duration_ms;
    bool active;
    bool repeat;
} beep_seq_t;

static beep_seq_t current_beep;

extern void i2c_tick(void);

static void start_beep_seq(uint8_t count, uint32_t period, uint32_t duration, bool repeat) {
    current_beep.start_ms = now_ms;
    current_beep.count = 1;
    current_beep.max_count = count;
    current_beep.period_ms = period;
    current_beep.duration_ms = duration;
    current_beep.active = true;
    current_beep.repeat = repeat;
    buzzer_beep_async(now_ms, duration);
}

static void update_beep_seq(void) {
    if (!current_beep.active) return;
    uint32_t elapsed = now_ms - current_beep.start_ms;
    uint32_t cycle_time = current_beep.max_count * current_beep.period_ms;
    if (current_beep.repeat) {
        cycle_time += 1000;
    }

    if (elapsed >= cycle_time) {
        if (current_beep.repeat) {
            current_beep.start_ms = now_ms;
            current_beep.count = 1;
            buzzer_beep_async(now_ms, current_beep.duration_ms);
        } else {
            current_beep.active = false;
        }
    } else {
        uint8_t expected_count = (elapsed / current_beep.period_ms) + 1;
        if (expected_count > current_beep.max_count) {
            expected_count = current_beep.max_count;
        }
        if (expected_count > current_beep.count) {
            buzzer_beep_async(now_ms, current_beep.duration_ms);
            current_beep.count = expected_count;
        }
    }
}

void app_init(void) {
    imu_init();
    stepper_init();
    buzzer_init();
    button_init();

    state = STATE_CHO_NUT;
    now_ms = 0;
    missing_samples_count = 0;
    nga_reason = 0;

    start_beep_seq(1, 500, 100, false);
}

void app_step(void) {
    now_ms += 4;

    i2c_tick();

    bool got_sample = false;
    for (int i = 0; i < MAX_IMU_PUMPS; i++) {
        if (imu_update()) {
            got_sample = true;
            break;
        }
    }

    if (!got_sample) {
        missing_samples_count++;
        if (missing_samples_count >= MAX_MISSING_SAMPLES) {
            if (state != STATE_NGA) {
                stepper_set_speed(0, 0);
                pid_compute(0.0f, 0.0f, false);
                state = STATE_NGA;
                nga_reason = 0;
                current_beep.active = false;
            }
        }
    } else {
        missing_samples_count = 0;
    }

    buzzer_update(now_ms);
    button_event_t btn = button_get_event(now_ms);
    update_beep_seq();

    switch (state) {
        case STATE_CHO_NUT:
            if (btn == BUTTON_EVENT_PRESSED) {
                state = STATE_HIEU_CHINH;
                calib_start_ms = now_ms;
                imu_calibrate_begin();
                start_beep_seq(5, 500, 100, false);
            }
            break;

        case STATE_HIEU_CHINH:
            if (btn == BUTTON_EVENT_PRESSED) {
                state = STATE_CHO_NUT;
                start_beep_seq(1, 500, 100, false);
            } else if (now_ms - calib_start_ms > CALIB_TIMEOUT_MS) {
                state = STATE_NGA;
                nga_reason = 1;
                start_beep_seq(3, 200, 100, true);
            } else if (!imu_calibrate_busy()) {
                imu_calibrate_commit();
                state = STATE_SAN_SANG;
                san_sang_start_ms = now_ms;
                start_beep_seq(2, 200, 100, false);
            }
            break;

        case STATE_SAN_SANG:
            if (now_ms - san_sang_start_ms > 1000) {
                state = STATE_CAN_BANG;
                current_beep.active = false;
            }
            break;

        case STATE_CAN_BANG:
            if (got_sample) {
                float angle = imu_get_tilt_angle();
                if (angle > 30.0f || angle < -30.0f) {
                    stepper_set_speed(0, 0);
                    pid_compute(angle, 0.0f, false);
                    state = STATE_NGA;
                    nga_reason = 0;
                    current_beep.active = false;
                } else {
                    float out = pid_compute(angle, 0.0f, true);
                    float motor = 0.0f;
                    if (out > 0.0f) {
                        float comp = 405.0f - (5500.0f / (out + 9.0f));
                        motor = 400.0f - comp;
                    } else if (out < 0.0f) {
                        float comp = -405.0f + (5500.0f / (-out + 9.0f));
                        motor = -400.0f - comp;
                    }
                    stepper_set_speed((int16_t)motor, (int16_t)motor);
                }
            }
            break;

        case STATE_NGA:
            if (btn == BUTTON_EVENT_PRESSED) {
                state = STATE_CHO_NUT;
                start_beep_seq(1, 500, 100, false);
            }
            break;
    }
}

void app_tick(void) {
    app_step();
}
